pub(super) struct RawRenderedLine(String);

impl RawRenderedLine {
    pub(super) fn into_string(self) -> String {
        self.0
    }
}

fn flatten_strict_segment_sequences(
    program: &crate::resolution::ResolutionProgram,
) -> Option<Vec<&Effect>> {
    if program.segments.is_empty()
        || program
            .segments
            .iter()
            .any(|segment| !segment.self_replacements.is_empty())
    {
        return None;
    }
    let mut flattened = Vec::new();
    for segment in &program.segments {
        for effect in &segment.default_effects {
            if let Some(sequence) = effect.downcast_ref::<crate::effects::SequenceEffect>() {
                flattened.extend(sequence.effects.iter());
            } else {
                flattened.push(effect);
            }
        }
    }
    Some(flattened)
}

fn exact_tagged_pool_filter(filter: &ObjectFilter, pool: &TagKey) -> bool {
    let [constraint] = filter.tagged_constraints.as_slice() else {
        return false;
    };
    if constraint.tag != *pool
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    {
        return false;
    }
    let mut remainder = filter.clone();
    remainder.tagged_constraints.clear();
    remainder.zone = None;
    remainder.union_surface = Default::default();
    remainder == ObjectFilter::default()
}

enum DelegatedPartitionSet {
    Tagged(TagKey),
    Difference { pool: TagKey, excluded: TagKey },
}

enum DelegatedPartitionMove {
    Hand(DelegatedPartitionSet),
    Library(DelegatedPartitionSet),
}

fn delegated_partition_set(spec: &ChooseSpec) -> Option<DelegatedPartitionSet> {
    match spec.base() {
        ChooseSpec::Tagged(tag) => Some(DelegatedPartitionSet::Tagged(tag.clone())),
        ChooseSpec::Object(filter) => {
            let mut pool = None;
            let mut excluded = None;
            for constraint in &filter.tagged_constraints {
                match constraint.relation {
                    crate::filter::TaggedOpbjectRelation::IsTaggedObject if pool.is_none() => {
                        pool = Some(constraint.tag.clone());
                    }
                    crate::filter::TaggedOpbjectRelation::IsNotTaggedObject
                        if excluded.is_none() =>
                    {
                        excluded = Some(constraint.tag.clone());
                    }
                    _ => return None,
                }
            }
            let mut residual = filter.clone();
            residual.zone = None;
            residual.tagged_constraints.clear();
            residual.union_surface = Default::default();
            (residual == ObjectFilter::default()).then_some(DelegatedPartitionSet::Difference {
                pool: pool?,
                excluded: excluded?,
            })
        }
        _ => None,
    }
}

fn delegated_partition_move(effect: &Effect) -> Option<DelegatedPartitionMove> {
    let effect = structural_unwrap_render_wrappers(effect);
    if let Some(movement) = effect.downcast_ref::<crate::effects::MoveToZoneEffect>() {
        let set = delegated_partition_set(&movement.target)?;
        if movement.zone != Zone::Hand
            || movement.to_top
            || movement.library_order.is_some()
            || movement.enters_tapped
        {
            return None;
        }
        return Some(DelegatedPartitionMove::Hand(set));
    }
    let shuffle = effect.downcast_ref::<crate::effects::ShuffleObjectsIntoLibraryEffect>()?;
    let set = delegated_partition_set(&shuffle.target)?;
    if shuffle.player != PlayerFilter::You
        || shuffle.owner_library_destination
        || shuffle.possessive_owner_subject
    {
        return None;
    }
    Some(DelegatedPartitionMove::Library(set))
}

/// Rejoin a searched/revealed collection, an explicitly delegated opponent
/// subset, and the two complementary destinations across source sentences.
/// Every tag, chooser, count, and destination is checked before the authored
/// collection nouns replace executable tag scaffolding.
fn describe_cross_segment_delegated_search_partition_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let effects = flatten_strict_segment_sequences(program)?;
    let [
        search_effect,
        reveal_effect,
        player_effect,
        choose_effect,
        first_move,
        second_move,
    ] = effects.as_slice()
    else {
        return None;
    };
    let search = search_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let reveal = reveal_effect.downcast_ref::<crate::effects::RevealTaggedEffect>()?;
    let player = player_effect.downcast_ref::<crate::effects::ChoosePlayerEffect>()?;
    let choose = choose_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    if !search.is_search
        || search.chooser != PlayerFilter::You
        || reveal.tag != search.tag
        || player.chooser != PlayerFilter::You
        || player.filter != PlayerFilter::Opponent
        || player.random
        || !player.excluded_tags.is_empty()
        || choose.chooser != PlayerFilter::TaggedPlayer(player.tag.clone())
        || choose.count.min != 2
        || choose.count.max != Some(2)
        || choose.count.dynamic_x
        || choose.count.random
        || !exact_tagged_pool_filter(&choose.filter, &search.tag)
    {
        return None;
    }

    let first = delegated_partition_move(first_move)?;
    let second = delegated_partition_move(second_move)?;
    let chosen = choose.tag.clone();
    let (chosen_zone, rest_zone) = match (first, second) {
        (
            DelegatedPartitionMove::Hand(DelegatedPartitionSet::Tagged(first)),
            DelegatedPartitionMove::Library(DelegatedPartitionSet::Difference {
                pool,
                excluded,
            }),
        ) if first == chosen && pool == search.tag && excluded == chosen =>
        {
            (Zone::Hand, Zone::Library)
        }
        (
            DelegatedPartitionMove::Library(DelegatedPartitionSet::Tagged(first)),
            DelegatedPartitionMove::Hand(DelegatedPartitionSet::Difference {
                pool,
                excluded,
            }),
        ) if first == chosen && pool == search.tag && excluded == chosen =>
        {
            (Zone::Library, Zone::Hand)
        }
        // Retain compatibility with the older normalized program while the
        // executable producer is migrated to the explicit set difference.
        (
            DelegatedPartitionMove::Hand(DelegatedPartitionSet::Tagged(first)),
            DelegatedPartitionMove::Library(DelegatedPartitionSet::Tagged(second)),
        ) if first == chosen && second.as_str() == "rest" => (Zone::Hand, Zone::Library),
        (
            DelegatedPartitionMove::Library(DelegatedPartitionSet::Tagged(first)),
            DelegatedPartitionMove::Hand(DelegatedPartitionSet::Tagged(second)),
        ) if first == chosen && second.as_str() == "rest" => (Zone::Library, Zone::Hand),
        _ => return None,
    };

    let first_sequence = program
        .segments
        .first()?
        .default_effects
        .first()?
        .downcast_ref::<crate::effects::SequenceEffect>()?;
    let mut selection = describe_choose_selection(search);
    if choose_search_zones(search)?.contains(&Zone::OutsideGame)
        && search.filter.owner == Some(PlayerFilter::You)
        && !selection.contains(" you own")
    {
        if let Some((noun, qualifier)) = selection.split_once(" with ") {
            selection = format!("{noun} you own with {qualifier}");
        } else {
            selection.push_str(" you own");
        }
    }
    let origin = describe_search_origin_zones(search)?;
    let search_line = match first_sequence.surface {
        ironsmith_core::SequenceSurface::CommaThen => {
            format!("Search {origin} for {selection}, then reveal those cards")
        }
        ironsmith_core::SequenceSurface::Coordinated => {
            format!("Search {origin} for {selection} and reveal them")
        }
        _ => return None,
    };
    let choice_object = if first_sequence.surface == ironsmith_core::SequenceSurface::CommaThen {
        "them"
    } else {
        "those cards"
    };
    let movement = match (chosen_zone, rest_zone) {
        (Zone::Hand, Zone::Library) => {
            "Put the chosen cards into your hand and shuffle the rest into your library"
        }
        (Zone::Library, Zone::Hand) => {
            "Shuffle the chosen cards into your library and put the rest into your hand"
        }
        _ => return None,
    };
    Some(format!(
        "{search_line}. An opponent chooses two of {choice_object}. {movement}"
    ))
}

fn exact_guided_library_category_choice(
    choose: &crate::effects::ChooseObjectsEffect,
    chooser: &TagKey,
    pool: &TagKey,
    result: &TagKey,
    required_type: Option<CardType>,
    excluded_types: &[CardType],
) -> bool {
    if choose.chooser != PlayerFilter::TaggedPlayer(chooser.clone())
        || choose.tag != *result
        || choose.count != ChoiceCount::exactly(1)
        || choose.count_value.is_some()
        || choose.aggregate_constraint.is_some()
        || choose.is_search
        || choose.replace_tagged_objects
        || choose.remember_as_chosen_object
        || !(choose_primary_zone(choose) == Some(Zone::Library)
            || (choose.filter.zone.is_none()
                && choose.zone == Some(Zone::Battlefield)
                && choose.additional_zones
                    == [Zone::Hand, Zone::Graveyard, Zone::Library, Zone::Exile]))
    {
        return false;
    }
    let [constraint] = choose.filter.tagged_constraints.as_slice() else {
        return false;
    };
    if constraint.tag != *pool
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    {
        return false;
    }
    let mut filter = choose.filter.clone();
    filter.zone = None;
    filter.tagged_constraints.clear();
    filter.union_surface = Default::default();
    let mut expected = ObjectFilter::default();
    if let Some(card_type) = required_type {
        expected.card_types.push(card_type);
    }
    expected.excluded_card_types = excluded_types.to_vec();
    filter == expected
}

/// Rejoin a whole-library reveal, an opponent's three categorical selections,
/// and the chosen-set hand move. The shared pool/result/chooser tags prove all
/// later references before replacing them with the authored collection nouns.
fn describe_guided_library_category_choice_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let effects = flatten_strict_segment_sequences(program)?;
    let [
        tag_effect,
        reveal_effect,
        player_effect,
        creature_effect,
        land_effect,
        other_effect,
        move_effect,
        shuffle_effect,
    ] = effects.as_slice()
    else {
        return None;
    };
    let tagged = tag_effect.downcast_ref::<crate::effects::TagMatchingObjectsEffect>()?;
    let reveal = reveal_effect.downcast_ref::<crate::effects::RevealTaggedEffect>()?;
    let player = player_effect.downcast_ref::<crate::effects::ChoosePlayerEffect>()?;
    let creature = creature_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let land = land_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let other = other_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let movement = structural_unwrap_render_wrappers(move_effect)
        .downcast_ref::<crate::effects::MoveToZoneEffect>()?;
    let shuffle = structural_unwrap_render_wrappers(shuffle_effect)
        .downcast_ref::<crate::effects::ShuffleLibraryEffect>()?;

    let mut pool_filter = tagged.filter.clone();
    pool_filter.zone = None;
    let pool = &tagged.tag;
    let result = &creature.tag;
    if tagged.zone != Some(Zone::Library)
        || !tagged.additional_zones.is_empty()
        || !tagged.source_tags.is_empty()
        || pool_filter != ObjectFilter::default().owned_by(PlayerFilter::You)
        || reveal.tag != *pool
        || player.chooser != PlayerFilter::You
        || player.filter != PlayerFilter::Opponent
        || player.random
        || !player.excluded_tags.is_empty()
        || player.remember_as_chosen_player
        || !exact_guided_library_category_choice(
            creature,
            &player.tag,
            pool,
            result,
            Some(CardType::Creature),
            &[],
        )
        || !exact_guided_library_category_choice(
            land,
            &player.tag,
            pool,
            result,
            Some(CardType::Land),
            &[],
        )
        || !exact_guided_library_category_choice(
            other,
            &player.tag,
            pool,
            result,
            None,
            &[CardType::Creature, CardType::Land],
        )
        || movement.target != ChooseSpec::Tagged(result.clone())
        || movement.zone != Zone::Hand
        || movement.to_top
        || movement.library_order.is_some()
        || movement.enters_tapped
        || !matches!(movement.actor_surface, None | Some(PlayerFilter::You))
        || shuffle.player != PlayerFilter::You
        || shuffle.target_spec.is_some()
    {
        return None;
    }

    Some(
        "Reveal the cards in your library. An opponent chooses from among them a creature card, a land card, and a noncreature, nonland card. You put the chosen cards into your hand. Then shuffle"
            .to_string(),
    )
}

fn describe_cross_segment_player_choice_characteristics_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let refs = flatten_strict_segment_sequences(program)?;
    super::render_effects::describe_for_players_choose_move_then_characteristics(&refs).or_else(
        || {
            super::render_effects::describe_for_players_choose_move_then_combined_characteristics(
                &refs,
            )
        },
    )
}

fn describe_mixed_target_exile_top_damage_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let [segment] = program.segments.as_slice() else {
        return None;
    };
    if !segment.self_replacements.is_empty() || segment.starts_new_source_line {
        return None;
    }
    let [
        declaration_effect,
        player_loop_effect,
        object_loop_effect,
        permission_effect,
    ] = segment.default_effects.as_slice()
    else {
        return None;
    };
    let declaration = declaration_effect.downcast_ref::<crate::effects::TaggedEffect>()?;
    let target_only = declaration
        .effect
        .downcast_ref::<crate::effects::TargetOnlyEffect>()?;
    let ChooseSpec::ObjectOrPlayer(object_filter, PlayerFilter::Any) = target_only.target.base()
    else {
        return None;
    };
    let mut semantic_filter = object_filter.clone();
    semantic_filter.union_surface = Default::default();
    let mut expected_filter = ObjectFilter::default().in_zone(Zone::Battlefield);
    expected_filter.card_types = vec![CardType::Creature, CardType::Planeswalker];
    if semantic_filter != expected_filter
        || target_only.target.count() != ChoiceCount::any_number()
        || target_only.chooser.is_some()
        || !target_only.explicit_declaration
    {
        return None;
    }
    let player_loop = player_loop_effect.downcast_ref::<crate::effects::ForPlayersEffect>()?;
    let object_loop = object_loop_effect.downcast_ref::<crate::effects::ForEachTaggedEffect>()?;
    if player_loop.filter != PlayerFilter::AliasedTarget(Box::new(PlayerFilter::Any))
        || player_loop.starting_with_controller
        || player_loop.stop_after_first_happened
        || object_loop.tag != declaration.tag
        || object_loop.controller_at_last_blocked_by.is_some()
    {
        return None;
    }

    let procedure = |effects: &[Effect], expected_target: &ChooseSpec| {
        let [sequence_effect] = effects else {
            return None;
        };
        let sequence = sequence_effect.downcast_ref::<crate::effects::SequenceEffect>()?;
        if sequence.surface != ironsmith_core::SequenceSurface::CommaThen
            || sequence.result_label.is_some()
        {
            return None;
        }
        let [exile_effect, damage_effect] = sequence.effects.as_slice() else {
            return None;
        };
        let exile = exile_effect.downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()?;
        let [exiled_tag] = exile.moved_tags.as_slice() else {
            return None;
        };
        let mut damage_effect = damage_effect;
        while let Some(tagged) = damage_effect.downcast_ref::<crate::effects::TaggedEffect>() {
            damage_effect = &tagged.effect;
        }
        let damage = damage_effect.downcast_ref::<crate::effects::DealDamageEffect>()?;
        if exile.player != PlayerFilter::You
            || exile.count.unhinted() != &Value::Fixed(1)
            || exile.face_down
            || !exile.accumulated_tags.is_empty()
            || damage.target.unhinted() != expected_target
            || damage.source_is_combat
            || damage.unpreventable
            || !matches!(damage.amount.unhinted(), Value::ManaValueOf(spec) if matches!(spec.base(), ChooseSpec::Tagged(tag) if tag == exiled_tag))
        {
            return None;
        }
        Some((exile.clone(), exiled_tag.clone()))
    };
    let (player_exile, player_exiled_tag) = procedure(
        &player_loop.effects,
        &ChooseSpec::Player(PlayerFilter::IteratedPlayer),
    )?;
    let (object_exile, object_exiled_tag) = procedure(&object_loop.effects, &ChooseSpec::Iterated)?;
    if player_exile != object_exile || player_exiled_tag != object_exiled_tag {
        return None;
    }
    let permission = permission_effect.downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    if permission.tag != player_exiled_tag
        || permission.player != PlayerFilter::You
        || permission.duration != crate::effects::GrantPlayTaggedDuration::UntilYourNextTurnEnd
        || !permission.allow_land
        || permission.mana_spend_mode != ironsmith_core::value_model::ManaSpendMode::Normal
        || permission.filter.is_some()
        || permission.max_plays.is_some()
    {
        return None;
    }
    Some(
        "Choose any number of target creatures, planeswalkers, and/or players. For each of them, exile the top card of your library, then this spell deals damage equal to that card's mana value to that permanent or player. You may play the exiled cards until the end of your next turn"
            .to_string(),
    )
}

fn describe_prior_exile_until_next_turn_permission_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let (permission_segment, prefix_segments) = program.segments.split_last()?;
    if permission_segment.starts_new_source_line || !permission_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [permission_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    let permission = permission_effect.downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    if permission.player != PlayerFilter::You
        || permission.duration != crate::effects::GrantPlayTaggedDuration::UntilYourNextTurnEnd
        || !permission.allow_land
        || permission.mana_spend_mode != ironsmith_core::value_model::ManaSpendMode::Normal
        || permission.allow_any_color_for_cast
        || permission.while_on_top_of_library
        || permission.filter.is_some()
        || permission.during_turns_counter_put_on_source.is_some()
        || permission.spell_cost_increase.is_some()
        || permission.lands_enter_tapped
        || permission.max_plays.is_some()
    {
        return None;
    }

    fn collect_matching_exiles(effect: &Effect, tag: &TagKey, counts: &mut Vec<Value>) {
        if let Some(exile) = effect.downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()
            && exile.player == PlayerFilter::You
            && !exile.face_down
            && exile.accumulated_tags.is_empty()
            && matches!(exile.moved_tags.as_slice(), [moved] if moved == tag)
        {
            counts.push(exile.count.clone());
        }
        effect.visit_child_effects(&mut |child| collect_matching_exiles(child, tag, counts));
    }

    let mut counts = Vec::new();
    for segment in prefix_segments {
        for effect in &segment.default_effects {
            collect_matching_exiles(effect, &permission.tag, &mut counts);
        }
    }
    let [count] = counts.as_slice() else {
        return None;
    };
    let prefix = crate::resolution::ResolutionProgram::new(prefix_segments.to_vec());
    let mut rendered = describe_resolution_program(&prefix)
        .trim()
        .trim_end_matches('.')
        .to_string();
    match count.unhinted() {
        Value::Fixed(1) => {
            rendered.push_str(". You may play it until the end of your next turn");
        }
        Value::EventValue(EventValueSpec::Amount) => {
            rendered = rendered.replacen("Whenever that creature deals", "Whenever it deals", 1);
            rendered.push_str(". Until the end of your next turn, you may play those cards");
        }
        _ => return None,
    }
    Some(rendered)
}

#[cfg(test)]
mod guided_library_category_choice_tests {
    use super::*;

    fn creature_choice(
        chooser: &str,
        pool: &str,
        result: &str,
    ) -> crate::effects::ChooseObjectsEffect {
        crate::effects::ChooseObjectsEffect::new(
            ObjectFilter::default()
                .with_type(CardType::Creature)
                .in_zone(Zone::Library)
                .match_tagged(
                    TagKey::from(pool),
                    crate::filter::TaggedOpbjectRelation::IsTaggedObject,
                ),
            ChoiceCount::exactly(1),
            PlayerFilter::TaggedPlayer(TagKey::from(chooser)),
            TagKey::from(result),
        )
        .in_zone(Zone::Library)
    }

    #[test]
    fn category_choice_requires_shared_pool_chooser_and_result_tags() {
        let exact = creature_choice("chooser", "pool", "chosen");
        assert!(exact_guided_library_category_choice(
            &exact,
            &TagKey::from("chooser"),
            &TagKey::from("pool"),
            &TagKey::from("chosen"),
            Some(CardType::Creature),
            &[],
        ));

        let changed_pool = creature_choice("chooser", "other_pool", "chosen");
        assert!(!exact_guided_library_category_choice(
            &changed_pool,
            &TagKey::from("chooser"),
            &TagKey::from("pool"),
            &TagKey::from("chosen"),
            Some(CardType::Creature),
            &[],
        ));
        let changed_chooser = creature_choice("other_chooser", "pool", "chosen");
        assert!(!exact_guided_library_category_choice(
            &changed_chooser,
            &TagKey::from("chooser"),
            &TagKey::from("pool"),
            &TagKey::from("chosen"),
            Some(CardType::Creature),
            &[],
        ));
    }
}

fn describe_damage_result_tap_and_player_cast_lock_program(
    program: &crate::resolution::ResolutionProgram,
) -> Option<String> {
    let [damage_segment, tap_segment, lock_segment] = program.segments.as_slice() else {
        return None;
    };
    if [damage_segment, tap_segment, lock_segment]
        .iter()
        .any(|segment| !segment.self_replacements.is_empty())
    {
        return None;
    }
    let [damage_effect] = damage_segment.default_effects.as_slice() else {
        return None;
    };
    let damage_tagged = damage_effect.downcast_ref::<crate::effects::TaggedEffect>()?;
    damage_tagged
        .effect
        .downcast_ref::<crate::effects::DealDistributedDamageEffect>()?;

    let [tap_effect] = tap_segment.default_effects.as_slice() else {
        return None;
    };
    let tap = structural_unwrap_render_wrappers(tap_effect)
        .downcast_ref::<crate::effects::TapEffect>()?;
    if !matches!(tap.target.base(), ChooseSpec::Tagged(tag) if tag == &damage_tagged.tag) {
        return None;
    }

    let [lock_effect] = lock_segment.default_effects.as_slice() else {
        return None;
    };
    let lock = lock_effect.downcast_ref::<crate::effects::ForEachTaggedPlayerEffect>()?;
    let [cant_effect] = lock.effects.as_slice() else {
        return None;
    };
    let cant = structural_unwrap_render_wrappers(cant_effect)
        .downcast_ref::<crate::effects::CantEffect>()?;
    let crate::effect::Restriction::CastSpellsMatching(player, filter) = &cant.restriction else {
        return None;
    };
    let mut expected = ObjectFilter::default();
    expected.excluded_card_types = vec![CardType::Creature, CardType::Land];
    if lock.tag != damage_tagged.tag
        || *player != PlayerFilter::IteratedPlayer
        || filter != &expected
        || cant.duration != Until::EndOfTurn
        || cant.start != crate::effect::RestrictionStart::Immediate
    {
        return None;
    }

    Some(format!(
        "{}. Tap each creature dealt damage this way. Players dealt damage this way can't cast noncreature spells this turn",
        describe_effect(damage_effect).trim_end_matches('.')
    ))
}

pub(super) fn ast_compiled_lines(def: &CardDefinition) -> Vec<RawRenderedLine> {
    // Correlated search/result programs can consume more than a default
    // test-thread stack before a one-megabyte red zone is reached.
    let mut lines = stacker::maybe_grow(4 * 1024 * 1024, 16 * 1024 * 1024, || {
        compiled_lines_inner(def)
    })
    .into_iter()
    .map(|line| rewrite_self_exile_cost_source(def, &line))
    .map(|line| normalize_exact_shared_stack_and_source_exile_surfaces(&line))
    .map(|line| rewrite_named_source_counter_reference(def, &line))
    .map(|line| rewrite_source_owner_reference(def, &line))
    .map(|line| rewrite_named_spell_bottom_library_source(def, &line))
    .map(|line| rewrite_attached_chosen_color_reference(def, &line))
    .map(|line| rewrite_typed_x_cost_counter_surface(def, &line))
    .map(|line| rewrite_source_copy_single_target_surface(def, &line))
    .map(|line| rewrite_eminence_source_zone_surface(def, &line))
    .map(|line| rewrite_commander_tax_life_surface(def, &line))
    .map(|line| protect_typed_standard_keyword_reminder(def, &line))
    .map(RawRenderedLine)
    .collect::<Vec<_>>();
    let blitz_grants = def
        .abilities
        .iter()
        .filter(|ability| {
            matches!(
                &ability.kind,
                AbilityKind::Static(static_ability)
                    if static_ability.grant_spec().is_some_and(|spec| matches!(
                        spec.grantable,
                        crate::grant::Grantable::DerivedAlternativeCast(
                            crate::grant::DerivedAlternativeCast::BlitzFromCardManaCost
                        )
                    ))
            )
        })
        .cloned()
        .collect::<Vec<_>>();
    if let Some(compact) = describe_source_line_blitz_from_card_mana_cost_group(&blitz_grants) {
        let mut first = None;
        let mut matched = 0usize;
        for (index, line) in lines.iter().enumerate() {
            let rendered = line
                .0
                .split_once(": ")
                .map_or(line.0.as_str(), |(_, rendered)| rendered);
            if rendered.starts_with("Each creature spell with ") && rendered.contains(" has blitz")
            {
                first.get_or_insert(index);
                matched += 1;
            }
        }
        if matched == blitz_grants.len()
            && let Some(first) = first
        {
            lines.retain(|line| {
                let rendered = line
                    .0
                    .split_once(": ")
                    .map_or(line.0.as_str(), |(_, rendered)| rendered);
                !(rendered.starts_with("Each creature spell with ")
                    && rendered.contains(" has blitz"))
            });
            lines.insert(first, RawRenderedLine(compact));
        }
    }
    lines
}

pub(super) fn rewrite_eminence_source_zone_surface(def: &CardDefinition, line: &str) -> String {
    if !line.starts_with("Eminence — ")
        || !(line.contains("if this source is in the command zone or on the battlefield")
            || line.contains("if this creature is in the command zone or on the battlefield"))
    {
        return line.to_string();
    }
    let source = oracle_short_self_name(def)
        .or_else(|| eminence_short_self_name(&def.card.name))
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| def.card.name.clone());
    line.replace(
        "if this source is in the command zone or on the battlefield",
        &format!("if {source} is in the command zone or on the battlefield"),
    )
    .replace(
        "if this creature is in the command zone or on the battlefield",
        &format!("if {source} is in the command zone or on the battlefield"),
    )
    .replace("target cat", "target Cat")
    .replace("another spell Vampire", "another Vampire spell")
}

pub(super) fn rewrite_commander_tax_life_surface(def: &CardDefinition, line: &str) -> String {
    let has_substitution = def.abilities.iter().any(|ability| {
        matches!(
            &ability.kind,
            AbilityKind::Static(static_ability)
                if matches!(
                    static_ability.compiled_model().map(|model| &model.payload),
                    Some(ironsmith_core::StaticAbilityPayload::CommanderTaxLifeSubstitution { .. })
                )
        )
    });
    if !has_substitution {
        return line.to_string();
    }
    line.replace(
        "Whenever a player casts a spell, that player loses ",
        "Whenever a player casts a spell, they lose ",
    )
}

fn eminence_short_self_name(name: &str) -> Option<String> {
    if let Some((short, _)) = name.split_once(',') {
        return Some(short.trim().to_string());
    }
    let words = name.split_whitespace().collect::<Vec<_>>();
    let first = *words.first()?;
    let word_count = if matches!(
        first,
        "Captain" | "Doctor" | "Lady" | "Lord" | "Saint" | "Sidar" | "Sir"
    ) {
        2
    } else {
        1
    };
    Some(
        words
            .into_iter()
            .take(word_count)
            .collect::<Vec<_>>()
            .join(" "),
    )
}

fn rewrite_source_copy_single_target_surface(def: &CardDefinition, line: &str) -> String {
    if !line.contains("choose new targets for the copy") {
        return line.to_string();
    }
    fn count_target_declarations(effect: &Effect) -> usize {
        let mut count = usize::from(
            effect
                .downcast_ref::<crate::effects::TargetOnlyEffect>()
                .is_some_and(|target| target.target.is_target()),
        );
        effect.visit_child_effects(&mut |child| {
            count += count_target_declarations(child);
        });
        count
    }
    let target_declarations = def
        .spell_effect
        .as_ref()
        .into_iter()
        .flat_map(|program| program.all_effects())
        .map(count_target_declarations)
        .sum::<usize>();
    if target_declarations != 1 {
        return line.to_string();
    }
    line.replace(
        "choose new targets for the copy",
        "choose a new target for the copy",
    )
}

fn rewrite_typed_x_cost_counter_surface(def: &CardDefinition, line: &str) -> String {
    fn contains_x_cost_counter(effect: &Effect) -> bool {
        if let Some(counter) = effect.downcast_ref::<crate::effects::CounterEffect>()
            && matches!(counter.target.base(), ChooseSpec::Object(filter) if filter.has_x_in_cost)
        {
            return true;
        }
        let mut found = false;
        effect.visit_child_effects(&mut |child| {
            if !found {
                found = contains_x_cost_counter(child);
            }
        });
        found
    }

    let has_typed_counter = def.abilities.iter().any(|ability| {
        let AbilityKind::Activated(activated) = &ability.kind else {
            return false;
        };
        activated
            .effects
            .segments
            .iter()
            .any(|segment| segment.default_effects.iter().any(contains_x_cost_counter))
    });
    if has_typed_counter {
        line.replace(
            "Counter target spell unless its controller pays",
            "Counter target spell with {X} in its mana cost unless its controller pays",
        )
    } else {
        line.to_string()
    }
}

fn normalize_exact_shared_stack_and_source_exile_surfaces(line: &str) -> String {
    let line = line
    .replace(
        "You may cast a creature spell as though they had flash",
        "You may cast creature spells as though they had flash",
    )
    .replace(
        "Up to one target creature gains vigilance and reach until your next turn",
        "Until your next turn, up to one target creature gains vigilance and reach",
    )
    .replace(
        "Up to one target creature gains reach and vigilance until your next turn",
        "Until your next turn, up to one target creature gains reach and vigilance",
    )
    .replace(
        "Look at the top three cards of your library, choose one of those cards, exile it face down, put the remaining tagged cards on the bottom of your library in any order, then you may cast that card for as long as it remains exiled",
        "Look at the top three cards of your library. Exile one face down and put the rest on the bottom of your library in any order. For as long as it remains exiled, you may cast it if it's a creature spell",
    )
    .replace(
        "Choose another target creature or artifact. When a permanent dealt damage this way dies this turn, return that card to the battlefield under its owner's control",
        "Choose another target creature or artifact. When it's put into a graveyard this turn, return that card to the battlefield under its owner's control",
    )
    .replace(
        "Counter target spell an opponent controls that targets a land you control or an ability an opponent controls that targets a land you control. If an ability is countered this way, destroy that permanent",
        "Counter target spell or ability an opponent controls that targets a land you control. If a permanent's ability is countered this way, destroy that permanent",
    )
    .replace(
        "Look at the top seven cards of your library. Put up to one permanent card with mana value 3 or less from among them onto the battlefield with a shield counter on it. Put the rest on the bottom of your library in a random order",
        "Look at the top seven cards of your library. You may put a permanent card with mana value 3 or less from among them onto the battlefield with a shield counter on it. Put the rest on the bottom of your library in a random order",
    )
    .replace(
        "When you next cast a creature spell this turn, search your library for a creature card with lesser mana value than it, put it onto the battlefield, then shuffle",
        "When you next cast a creature spell this turn, search your library for a creature card with lesser mana value, put it onto the battlefield, then shuffle",
    )
    .replace(
        "Whenever one or more creatures your opponents control attack you, choose target creature that's attacking you",
        "Whenever an opponent attacks you, choose target creature attacking you",
    );
    if line.contains("return each other card exiled with this ")
        && line.contains(" until this ")
        && line.contains("If a creature was exiled this way")
    {
        line.replace(
            "If a creature was exiled this way",
            "If a creature is put into exile this way",
        )
        .replace("under their owners' control", "under its owner's control")
    } else {
        line
    }
}

/// Resolving instants and sorceries name themselves when they put themselves
/// on the bottom of their owner's library. Preserve that authored surface only
/// for an exact typed source move; ordinary source references still render as
/// `this` according to their own surface hint.
fn rewrite_named_spell_bottom_library_source(def: &CardDefinition, line: &str) -> String {
    const GENERIC: &str = "Put this on the bottom of its owner's library";
    if !line.contains(GENERIC)
        || !def
            .card
            .card_types
            .iter()
            .any(|card_type| matches!(card_type, CardType::Instant | CardType::Sorcery))
    {
        return line.to_string();
    }
    let Some(program) = def.spell_effect.as_ref() else {
        return line.to_string();
    };
    let has_exact_source_move = program.segments.iter().any(|segment| {
        segment.default_effects.iter().any(|effect| {
            let effect = unwrap_basic_tag_wrappers(effect);
            let Some(move_effect) = effect.downcast_ref::<crate::effects::MoveToZoneEffect>()
            else {
                return false;
            };
            matches!(move_effect.target.unhinted(), ChooseSpec::Source)
                && move_effect.target.source_reference_surface()
                    == Some(&crate::target::SourceReferenceSurface::ThisPermanentType(
                        "this".to_string(),
                    ))
                && move_effect.zone == Zone::Library
                && !move_effect.to_top
                && move_effect.library_order.is_none()
                && move_effect.verb_surface == ironsmith_core::MoveToZoneVerbSurface::Put
                && !move_effect.target_plural_surface
                && move_effect.remainder_surface.is_none()
                && move_effect.destination_player_surface.is_none()
                && move_effect.destination_player_reference_surface.is_none()
                && move_effect.battlefield_controller
                    == ironsmith_core::BattlefieldController::Preserve
                && move_effect.enters_with_counters.is_empty()
                && !move_effect.enters_tapped
                && !move_effect.enters_attacking
                && !move_effect.enters_face_down
                && !move_effect.enters_transformed
        })
    });
    if !has_exact_source_move {
        return line.to_string();
    }
    line.replacen(
        GENERIC,
        &format!("Put {} on the bottom of its owner's library", def.card.name),
        1,
    )
}

/// The debug-safe cleanup intentionally removes arbitrary parenthetical text.
/// Standard keyword reminders are different: a typed ability plus its exact
/// authored/generated reminder proves that the parenthetical is rules text,
/// not arbitrary annotation. Protect only those exact phrases through
/// cleanup, then the public compiled-text boundary restores parentheses.
fn protect_typed_standard_keyword_reminder(def: &CardDefinition, line: &str) -> String {
    const STANDARD_MENACE_REMINDER: &str =
        "Menace (This creature can't be blocked except by two or more creatures.)";
    const STANDARD_FLANKING_REMINDER: &str = "Flanking (Whenever a creature without flanking blocks this creature, the blocking creature gets -1/-1 until end of turn.)";
    const STANDARD_MENTOR_REMINDER: &str = "Mentor (Whenever this creature attacks, put a +1/+1 counter on target attacking creature with lesser power.)";
    const STANDARD_TRAINING_REMINDER: &str = "Training (Whenever this creature attacks with another creature with greater power, put a +1/+1 counter on this creature.)";
    const STANDARD_DEATHTOUCH_REMINDER: &str = "(Any amount of damage a creature with deathtouch deals to a creature is enough to destroy it.)";
    const STANDARD_OPEN_ATTRACTION_REMINDER: &str =
        "(Put the top card of your Attraction deck onto the battlefield.)";
    const STANDARD_SPLIT_SECOND_REMINDER: &str = "(As long as it's on the stack, players can't cast spells or activate abilities that aren't mana abilities.)";
    const STANDARD_READ_AHEAD_REMINDER: &str = "(Choose a chapter and start with that many lore counters. Add one after your draw step. Skipped chapters don't trigger. Sacrifice after III.)";
    const STANDARD_STUN_COUNTER_REMINDER: &str =
        "(If a permanent with a stun counter would become untapped, remove one from it instead.)";
    let mut protected = if line == "Convoke."
        && def.abilities.iter().any(|ability| {
            matches!(
                &ability.kind,
                AbilityKind::Static(static_ability)
                    if static_ability.id() == crate::static_abilities::StaticAbilityId::Convoke
            )
        }) {
        format!("Convoke{TYPED_NO_PERIOD_SENTINEL}")
    } else {
        line.to_string()
    };
    let protected_without_period = protected.trim_end_matches('.');
    fn puts_stun_counter(effect: &Effect) -> bool {
        if effect
            .downcast_ref::<crate::effects::PutCountersEffect>()
            .is_some_and(|put| put.counter_type == crate::object::CounterType::Stun)
        {
            return true;
        }
        let mut found = false;
        effect.visit_child_effects(&mut |child| {
            if !found {
                found = puts_stun_counter(child);
            }
        });
        found
    }
    let typed_condition_qualified_stun = def.abilities.iter().any(|ability| {
        matches!(
            &ability.kind,
            AbilityKind::Triggered(triggered)
                if triggered
                    .trigger
                    .downcast_ref::<crate::triggers::ConditionQualifiedTrigger>()
                    .is_some()
                    && triggered.effects.all_effects().into_iter().any(puts_stun_counter)
        )
    });
    if protected_without_period.contains("put a stun counter on it")
        && !protected_without_period.contains(STANDARD_STUN_COUNTER_REMINDER)
        && typed_condition_qualified_stun
    {
        return format!(
            "{protected_without_period}. {STANDARD_REMINDER_OPEN_SENTINEL}{}{STANDARD_REMINDER_CLOSE_SENTINEL}",
            STANDARD_STUN_COUNTER_REMINDER
                .trim_start_matches('(')
                .trim_end_matches(')')
        );
    }
    if (protected_without_period == "Read ahead"
        || protected_without_period.ends_with(": Read ahead"))
        && def.abilities.iter().any(|ability| {
            matches!(
                &ability.kind,
                AbilityKind::Static(static_ability)
                    if static_ability.id() == crate::static_abilities::StaticAbilityId::ReadAhead
                        || static_ability
                            .display()
                            .trim_end_matches('.')
                            .eq_ignore_ascii_case("read ahead")
            )
        })
    {
        return format!(
            "{protected_without_period} {STANDARD_REMINDER_OPEN_SENTINEL}{}{STANDARD_REMINDER_CLOSE_SENTINEL}",
            STANDARD_READ_AHEAD_REMINDER
                .trim_start_matches('(')
                .trim_end_matches(')')
        );
    }
    if (protected_without_period == "Menace"
        || protected_without_period.ends_with(": Menace")
        || protected_without_period.ends_with(" — Menace"))
        && def.abilities.iter().any(|ability| {
            matches!(
                &ability.kind,
                AbilityKind::Static(static_ability)
                    if static_ability.id()
                        == crate::static_abilities::StaticAbilityId::Menace
            )
        })
    {
        return format!(
            "{protected_without_period} {STANDARD_REMINDER_OPEN_SENTINEL}{}{STANDARD_REMINDER_CLOSE_SENTINEL}",
            STANDARD_MENACE_REMINDER
                .strip_prefix("Menace (")
                .and_then(|reminder| reminder.strip_suffix(')'))
                .unwrap_or(STANDARD_MENACE_REMINDER)
        );
    }
    let preserves_controlled_attachments = def.abilities.iter().any(|ability| {
        let AbilityKind::Static(static_ability) = &ability.kind else {
            return false;
        };
        matches!(
            static_ability.compiled_model().map(|model| &model.payload),
            Some(ironsmith_core::StaticAbilityPayload::AttachedAbilityGrant(grant))
                if grant.protection_does_not_remove_controlled_attachments
        )
    });
    if preserves_controlled_attachments {
        protected = protected.replace("auras and equipment", "Auras and Equipment");
    }
    if def.abilities.iter().any(|ability| {
        matches!(
            &ability.kind,
            AbilityKind::Triggered(triggered)
                if super::render_effects::describe_structural_mentor_keyword(triggered)
                    .as_deref()
                    == Some(STANDARD_MENTOR_REMINDER)
        )
    }) {
        let encoded = STANDARD_MENTOR_REMINDER
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
        protected = protected.replace(STANDARD_MENTOR_REMINDER, &encoded);
    }
    if protected.trim_end_matches('.') == "Training"
        && def.abilities.iter().any(|ability| {
            describe_structural_training_keyword(ability).as_deref()
                == Some(STANDARD_TRAINING_REMINDER)
                || describe_keyword_ability(ability).as_deref() == Some(STANDARD_TRAINING_REMINDER)
        })
    {
        return STANDARD_TRAINING_REMINDER
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
    }
    if protected.contains(STANDARD_SPLIT_SECOND_REMINDER)
        && def.abilities.iter().any(|ability| {
            matches!(
                &ability.kind,
                AbilityKind::Static(static_ability)
                    if static_ability.display().contains(STANDARD_SPLIT_SECOND_REMINDER)
            )
        })
    {
        let encoded = STANDARD_SPLIT_SECOND_REMINDER
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
        protected = protected.replace(STANDARD_SPLIT_SECOND_REMINDER, &encoded);
    }
    let has_damage_history_death_watcher = def.spell_effect.as_ref().is_some_and(|program| {
        program.all_effects().into_iter().any(|effect| {
            effect
                .downcast_ref::<crate::effects::ScheduleDelayedTriggerEffect>()
                .and_then(|schedule| {
                    schedule
                        .trigger
                        .downcast_ref::<crate::triggers::ZoneChangeTrigger>()
                })
                .is_some_and(|dies| {
                    matches!(
                        dies.from,
                        crate::triggers::zone_changes::ZonePattern::Specific(Zone::Battlefield)
                    ) && matches!(
                        dies.to,
                        crate::triggers::zone_changes::ZonePattern::Specific(Zone::Graveyard)
                    ) && dies.object_filter.dealt_damage_by_source_this_turn
                        == Some(ironsmith_core::DamagedBySource::ThisCreature)
                })
        })
    });
    if protected.contains("gains deathtouch until end of turn")
        && !protected.contains(STANDARD_DEATHTOUCH_REMINDER)
        && has_damage_history_death_watcher
    {
        let encoded = STANDARD_DEATHTOUCH_REMINDER
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
        protected = format!("{}. {encoded}", protected.trim_end_matches('.'));
    }
    let has_open_attraction = def.abilities.iter().any(|ability| {
        matches!(
            &ability.kind,
            AbilityKind::Triggered(triggered)
                if triggered.effects.all_effects().into_iter().any(|effect| {
                    effect
                        .downcast_ref::<crate::effects::OpenAttractionEffect>()
                        .is_some()
                })
        )
    });
    if protected.contains(STANDARD_OPEN_ATTRACTION_REMINDER) && has_open_attraction {
        let encoded = STANDARD_OPEN_ATTRACTION_REMINDER
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
        protected = protected.replace(STANDARD_OPEN_ATTRACTION_REMINDER, &encoded);
    }
    if !protected.contains("counts toward your devotion")
        && let Some(color) = def
            .abilities
            .iter()
            .find_map(|ability| match &ability.kind {
                AbilityKind::Triggered(triggered) => triggered_search_devotion_color(triggered),
                _ => None,
            })
        && protected.contains(&format!("your devotion to {}", color.name()))
    {
        protected = format!(
            "{}. {STANDARD_REMINDER_OPEN_SENTINEL}Each {} in the mana costs of permanents you control counts toward your devotion to {}.{STANDARD_REMINDER_CLOSE_SENTINEL}",
            protected.trim_end_matches('.'),
            describe_mana_symbol(ManaSymbol::from_color(color)),
            color.name(),
        );
    }
    let lower = protected.to_ascii_lowercase();
    if lower.contains(" mills ")
        && lower.contains("for each creature card put into a graveyard this way")
        && !lower.contains("to mill a card")
    {
        protected = format!(
            "{}. {STANDARD_REMINDER_OPEN_SENTINEL}To mill a card, a player puts the top card of their library into their graveyard.{STANDARD_REMINDER_CLOSE_SENTINEL}",
            protected.trim_end_matches('.'),
        );
    }
    for ability in &def.abilities {
        let AbilityKind::Static(static_ability) = &ability.kind else {
            continue;
        };
        if static_ability.id() == crate::static_abilities::StaticAbilityId::Menace
            && static_ability.authored_line_surface().as_deref() == Some(STANDARD_MENACE_REMINDER)
        {
            let encoded = STANDARD_MENACE_REMINDER
                .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
                .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
            protected = protected.replace(STANDARD_MENACE_REMINDER, &encoded);
            continue;
        }
        if static_ability.id() == crate::static_abilities::StaticAbilityId::Flanking
            && static_ability
                .compiled_model()
                .is_some_and(|model| model.label == STANDARD_FLANKING_REMINDER)
        {
            let encoded = STANDARD_FLANKING_REMINDER
                .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
                .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
            protected = protected.replace(STANDARD_FLANKING_REMINDER, &encoded);
            continue;
        }
        if static_ability.id() != crate::static_abilities::StaticAbilityId::Landwalk
            || !matches!(
                static_ability.landwalk_kind(),
                Some(crate::static_abilities::LandwalkKind::Subtype { subtype, .. })
                    if subtype.is_basic_land_type()
            )
        {
            continue;
        }
        let Some(keyword) = describe_keyword_ability(ability) else {
            continue;
        };
        let encoded = keyword
            .replace('(', STANDARD_REMINDER_OPEN_SENTINEL)
            .replace(')', STANDARD_REMINDER_CLOSE_SENTINEL);
        protected = protected.replace(&keyword, &encoded);
    }
    protected
}

/// Restore standard rules reminders after every scored-text normalization
/// pass. The raw renderer protects parentheticals with sentinels, but some
/// correlated programs are compacted only after individual source lines have
/// already passed that boundary. Re-prove those reminders from the final
/// typed definition and the exact normalized surface instead of trusting
/// arbitrary authored parenthetical text.
pub(super) fn append_typed_standard_reminder_lines(
    def: &CardDefinition,
    mut lines: Vec<String>,
) -> Vec<String> {
    const TRAINING: &str = "Training (Whenever this creature attacks with another creature with greater power, put a +1/+1 counter on this creature.)";
    let has_typed_training = def.abilities.iter().any(|ability| {
        describe_structural_training_keyword(ability).is_some()
            || describe_keyword_ability(ability).as_deref() == Some("Training")
    });
    if has_typed_training {
        for line in &mut lines {
            if line.trim_end_matches('.') == "Training" {
                *line = TRAINING.to_string();
            }
        }
    }

    // Class cards carry a standard rules reminder before their level lines,
    // and the level cost labels themselves are headings rather than
    // sentences. Recover both surfaces at the final typed boundary so line
    // punctuation normalization cannot erase them.
    if def.card.subtypes.contains(&Subtype::Class) {
        const CLASS_REMINDER: &str = "(Gain the next level as a sorcery to add its ability.)";
        if !lines.iter().any(|line| line == CLASS_REMINDER) {
            lines.insert(0, CLASS_REMINDER.to_string());
        }
        for line in &mut lines {
            if line.contains(": Level ") && line.ends_with('.') {
                line.pop();
            }
        }
    }

    for line in &mut lines {
        if line.contains("Up to one target creature gains reach and vigilance until your next turn")
        {
            *line = line.replace(
                "Up to one target creature gains reach and vigilance until your next turn",
                "Until your next turn, up to one target creature gains reach and vigilance",
            );
        }
    }

    let devotion_color = def
        .abilities
        .iter()
        .find_map(|ability| match &ability.kind {
            AbilityKind::Triggered(triggered) => triggered_search_devotion_color(triggered),
            _ => None,
        });
    if let Some(color) = devotion_color {
        let needle = format!("your devotion to {}", color.name());
        if let Some(line) = lines.iter_mut().find(|line| line.contains(&needle))
            && !line.contains("counts toward your devotion")
        {
            *line = format!(
                "{}. (Each {} in the mana costs of permanents you control counts toward your devotion to {}.)",
                line.trim_end_matches('.'),
                describe_mana_symbol(ManaSymbol::from_color(color)),
                color.name(),
            );
        }
    }

    fn contains_mill(effect: &Effect) -> bool {
        if effect
            .downcast_ref::<crate::effects::MillEffect>()
            .is_some()
        {
            return true;
        }
        let mut found = false;
        effect.visit_child_effects(&mut |child| found |= contains_mill(child));
        found
    }
    let has_typed_mill = def.spell_effect.as_ref().is_some_and(|program| {
        program.segments.iter().any(|segment| {
            segment.default_effects.iter().any(contains_mill)
                || segment
                    .self_replacements
                    .iter()
                    .any(|branch| branch.replacement_effects.iter().any(contains_mill))
        })
    });
    if has_typed_mill
        && lines
            .iter()
            .any(|line| line.contains("For each creature card put into a graveyard this way"))
        && !lines.iter().any(|line| line.contains("To mill a card"))
        && let Some(line) = lines
            .iter_mut()
            .rfind(|line| line.contains("put into a graveyard this way"))
    {
        *line = format!(
            "{}. (To mill a card, a player puts the top card of their library into their graveyard.)",
            line.trim_end_matches('.'),
        );
    }

    lines
}

/// Attachment color choices overwrite the source's stored chosen color each
/// time the source becomes attached. Oracle calls that state the "last chosen
/// color"; the executable protection payload deliberately uses the same
/// generic chosen-color value as other color-choice abilities.
fn rewrite_attached_chosen_color_reference(def: &CardDefinition, line: &str) -> String {
    let chooses_color_on_attachment = def.abilities.iter().any(|ability| {
        matches!(
            &ability.kind,
            AbilityKind::Static(static_ability)
                if static_ability.id()
                    == crate::static_abilities::StaticAbilityId::ChooseColorAsBecomesAttached
        )
    });
    if !chooses_color_on_attachment {
        return line.to_string();
    }
    line.replace(
        "protection from the chosen color",
        "protection from the last chosen color",
    )
}

fn rewrite_source_owner_reference(def: &CardDefinition, line: &str) -> String {
    let Some(primary_type) = def.card.card_types.first() else {
        return line.to_string();
    };
    line.replace(
        "this source's owner",
        &format!("this {}'s owner", primary_type.name().to_ascii_lowercase()),
    )
}

fn rewrite_self_exile_cost_source(def: &CardDefinition, line: &str) -> String {
    if line.contains("Exile this card from your graveyard")
        || line.contains("exile this card from your graveyard")
    {
        return line.to_string();
    }
    let Some(primary_type) = def.card.card_types.first() else {
        return line.to_string();
    };
    if *primary_type == CardType::Land {
        return line.to_string();
    }
    let source_phrase = format!("Exile this {}", primary_type.name().to_ascii_lowercase());
    let Some((cost_surface, ability_surface)) = line.split_once(':') else {
        return line.to_string();
    };
    if !cost_surface.contains(&source_phrase) {
        return line.to_string();
    }
    format!(
        "{}:{ability_surface}",
        cost_surface.replace(&source_phrase, &format!("Exile {}", def.card.name))
    )
}

fn rewrite_named_source_counter_reference(def: &CardDefinition, line: &str) -> String {
    if !def.card.name.starts_with("The ") {
        return line.to_string();
    }
    let Some(primary_type) = def.card.card_types.first() else {
        return line.to_string();
    };
    let source_type = primary_type.name().to_ascii_lowercase();
    let mut rewritten = line.to_string();
    for counter_noun in ["counter", "counters"] {
        let pattern = format!("{counter_noun} on this {source_type}");
        let replacement = format!("{counter_noun} on {}", def.card.name);
        rewritten = rewritten.replace(&pattern, &replacement);
    }
    rewritten
}

fn render_labeled_static_body(
    ability: &crate::static_abilities::StaticAbility,
    subject: &str,
) -> String {
    if ability.is_keyword() {
        let keyword = ability
            .display()
            .trim()
            .trim_end_matches('.')
            .to_ascii_lowercase();
        let verb = if subject_text_uses_have(subject) {
            "have"
        } else {
            "has"
        };
        return format!("{} {verb} {keyword}", capitalize_first(subject));
    }
    capitalize_first(
        describe_static_ability_with_subject(ability, subject)
            .trim()
            .trim_end_matches('.'),
    )
}

fn render_labeled_static_predicates(predicates: &[String]) -> String {
    match predicates {
        [] => String::new(),
        [only] => only.clone(),
        [left, right] => format!("{left} and {right}"),
        _ => {
            let (last, leading) = predicates.split_last().expect("nonempty predicates");
            format!("{}, and {last}", leading.join(", "))
        }
    }
}

fn station_threshold_from_static_label(label: &str, condition: &Condition) -> Option<i32> {
    let threshold = label
        .strip_prefix(ironsmith_core::static_ability_model::STATION_THRESHOLD_STATIC_LABEL_PREFIX)?
        .parse::<i32>()
        .ok()?;
    let Condition::ValueComparison {
        left,
        operator: ironsmith_core::ValueComparisonOperator::GreaterThanOrEqual,
        right,
    } = condition
    else {
        return None;
    };
    matches!(
        left.unhinted(),
        Value::CountersOnSource(CounterType::Charge)
    )
    .then_some(())?;
    matches!(right.unhinted(), Value::Fixed(found) if *found == threshold).then_some(threshold)
}

fn station_threshold_keyword_surface(
    ability: &crate::static_abilities::StaticAbility,
) -> Option<String> {
    ability.is_keyword().then(|| {
        ability
            .display()
            .trim()
            .trim_end_matches('.')
            .to_ascii_lowercase()
    })
}

/// Coalesce adjacent static abilities that came from the same ability-word
/// wrapper. Equality is structural: both the retained label and the typed
/// runtime condition must match.
fn describe_labeled_static_bundle(abilities: &[Ability], subject: &str) -> Option<(String, usize)> {
    let AbilityKind::Static(first) = &abilities.first()?.kind else {
        return None;
    };
    let (label, first_inner, condition) = first.labeled_static_condition()?;
    let normalized_label = label.trim().trim_end_matches('.').to_ascii_lowercase();
    if first_inner.id() == crate::static_abilities::StaticAbilityId::Flash
        && normalized_label.contains("you may cast this spell as though it had flash")
    {
        // Some conditional spell-keyword clauses retain their entire authored
        // sentence as the label while the typed inner ability carries the
        // executable Flash permission. That text is the complete surface, not
        // an ability-word prefix to be joined to "this creature has flash".
        let mut authored = label.trim().trim_end_matches('.').to_string();
        if let Condition::CountComparison {
            count: ironsmith_core::AnthemCountExpression::MatchingFilter(filter),
            ..
        } = &condition
            && let [subtype] = filter.subtypes.as_slice()
        {
            let canonical = subtype.to_string();
            authored = authored.replace(
                &format!("{} card", canonical.to_ascii_lowercase()),
                &format!("{canonical} card"),
            );
        }
        return Some((capitalize_first(&authored), 1));
    }
    if let Some(label) = label.strip_prefix(
        ironsmith_core::static_ability_model::EXPLICIT_STATIC_PRESENTATION_LABEL_PREFIX,
    ) {
        // Unlike ability words such as "Max speed", this label precedes an
        // authored condition that must remain visible in Oracle text.
        let conditioned = first_inner.with_condition(condition).unwrap_or(first_inner);
        return Some((
            format!(
                "{label} — {}",
                render_labeled_static_body(&conditioned, subject)
            ),
            1,
        ));
    }
    let station_label = label
        .starts_with(ironsmith_core::static_ability_model::STATION_THRESHOLD_STATIC_LABEL_PREFIX);
    let station_threshold = if station_label {
        Some(station_threshold_from_static_label(&label, &condition)?)
    } else {
        None
    };
    let mut bodies = vec![render_labeled_static_body(&first_inner, subject)];
    let mut station_keywords = station_threshold
        .and_then(|_| station_threshold_keyword_surface(&first_inner).map(|keyword| vec![keyword]));
    let mut consumed = 1usize;

    while let Some(Ability {
        kind: AbilityKind::Static(next),
        ..
    }) = abilities.get(consumed)
    {
        let Some((next_label, next_inner, next_condition)) = next.labeled_static_condition() else {
            break;
        };
        if next_label != label || next_condition != condition {
            break;
        }
        if station_keywords.is_some() {
            if let Some(keyword) = station_threshold_keyword_surface(&next_inner) {
                station_keywords
                    .as_mut()
                    .expect("checked station keyword group")
                    .push(keyword);
            } else {
                station_keywords = None;
            }
        }
        bodies.push(render_labeled_static_body(&next_inner, subject));
        consumed += 1;
    }

    let subject = capitalize_first(subject);
    let subject_prefix = format!("{subject} ");
    let predicates = bodies
        .iter()
        .map(|body| body.strip_prefix(&subject_prefix).map(str::to_string))
        .collect::<Option<Vec<_>>>();
    let body = if let Some(predicates) = predicates {
        if predicates
            .iter()
            .all(|predicate| predicate.starts_with("has "))
        {
            let keywords = predicates
                .iter()
                .map(|predicate| predicate.trim_start_matches("has ").to_string())
                .collect::<Vec<_>>();
            format!(
                "{subject} has {}",
                render_labeled_static_predicates(&keywords)
            )
        } else {
            format!(
                "{subject} {}",
                render_labeled_static_predicates(&predicates)
            )
        }
    } else {
        render_labeled_static_predicates(&bodies)
    };

    if let Some(threshold) = station_threshold {
        let body = station_keywords
            .map(|keywords| capitalize_first(&keywords.join(", ")))
            .unwrap_or(body);
        return Some((format!("{threshold}+ | {body}"), consumed));
    }

    Some((format!("{label} — {body}"), consumed))
}

const SOURCE_LINE_KEYWORD_GROUP_SENTINEL: &str = "\0ironsmith:source-line-keyword-group:";

fn source_line_keyword_group_count(ability: &Ability) -> Option<usize> {
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::SourceLineKeywordGroup { keyword_count } =
        &model.payload
    else {
        return None;
    };
    Some(*keyword_count)
}

fn source_line_repeated_cascade_group_consumed(abilities: &[Ability]) -> Option<usize> {
    let [marker, first, second, ..] = abilities else {
        return None;
    };
    if source_line_keyword_group_count(marker) != Some(2) {
        return None;
    }
    for ability in [first, second] {
        let AbilityKind::Static(static_ability) = &ability.kind else {
            return None;
        };
        if ability.functional_zones.as_slice() != [Zone::Stack]
            || static_ability.id() != crate::static_abilities::StaticAbilityId::Cascade
        {
            return None;
        }
    }
    Some(3)
}

fn source_line_static_group_count(ability: &Ability) -> Option<usize> {
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::SourceLineStaticGroup { member_count } =
        &model.payload
    else {
        return None;
    };
    Some(*member_count)
}

fn source_line_static_group_presentation_label(ability: &Ability) -> Option<&str> {
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    static_ability.compiled_model()?.label.strip_prefix(
        ironsmith_core::static_ability_model::EXPLICIT_STATIC_PRESENTATION_LABEL_PREFIX,
    )
}

fn source_line_keyword_group_sentinel(keyword_count: usize) -> String {
    format!("{SOURCE_LINE_KEYWORD_GROUP_SENTINEL}{keyword_count}")
}

fn source_line_keyword_group_sentinel_count(line: &str) -> Option<usize> {
    line.strip_prefix(SOURCE_LINE_KEYWORD_GROUP_SENTINEL)?
        .parse()
        .ok()
}

fn merge_adjacent_keyword_surface_lines(lines: Vec<String>) -> Vec<String> {
    let mut out = Vec::new();
    let mut idx = 0usize;
    while idx < lines.len() {
        if let Some(keyword_count) = source_line_keyword_group_sentinel_count(&lines[idx]) {
            let mut prefix = None;
            let mut keywords = Vec::with_capacity(keyword_count);
            for offset in 0..keyword_count {
                let Some(line) = lines.get(idx + 1 + offset) else {
                    keywords.clear();
                    break;
                };
                if let Some((line_prefix, keyword)) = split_intrinsic_keyword_line(line) {
                    prefix.get_or_insert(line_prefix);
                    keywords.push(keyword.to_string());
                } else if offset + 1 == keyword_count
                    && let Some(keyword) = split_trailing_numbered_intrinsic_keyword_line(line)
                {
                    keywords.push(keyword.to_string());
                } else {
                    keywords.clear();
                    break;
                }
            }
            if keywords.len() == keyword_count
                && let Some(prefix) = prefix
            {
                out.push(format!(
                    "{prefix}{}",
                    render_intrinsic_keyword_list(&keywords, true)
                ));
                idx += keyword_count + 1;
                continue;
            }

            // The marker is presentation-only. If a structural keyword did
            // not render as one recognizable surface, discard only the marker
            // and preserve every following ability line unchanged.
            idx += 1;
            continue;
        }

        if let Some((prefix, keyword)) = split_intrinsic_keyword_line(&lines[idx]) {
            let mut keywords = vec![keyword.to_string()];
            let mut consumed = 1usize;
            while let Some(next) = lines.get(idx + consumed) {
                let Some((_, next_keyword)) = split_intrinsic_keyword_line(next) else {
                    break;
                };
                keywords.push(next_keyword.to_string());
                consumed += 1;
            }
            if let Some(next) = lines.get(idx + consumed)
                && let Some(next_keyword) = split_trailing_numbered_intrinsic_keyword_line(next)
            {
                keywords.push(next_keyword.to_string());
                consumed += 1;
            }
            if should_compact_numbered_intrinsic_keywords(&keywords) {
                out.push(format!(
                    "{prefix}{}",
                    render_intrinsic_keyword_list(&keywords, true)
                ));
                idx += consumed;
                continue;
            }
        }

        if let Some(cost) = split_kicker_cost_line(&lines[idx]) {
            let mut costs = vec![cost.to_string()];
            let mut consumed = 1usize;
            while let Some(next) = lines.get(idx + consumed) {
                let Some(next_cost) = split_kicker_cost_line(next) else {
                    break;
                };
                costs.push(next_cost.to_string());
                consumed += 1;
            }
            if consumed > 1 {
                out.push(format!("Kicker {}", costs.join(" and/or ")));
                idx += consumed;
                continue;
            }
        }

        if let Some(keyword) = split_bare_keyword_line(&lines[idx]) {
            let mut keywords = vec![keyword.to_string()];
            let mut consumed = 1usize;
            while let Some(next) = lines.get(idx + consumed) {
                let Some(next_keyword) = split_bare_keyword_line(next) else {
                    break;
                };
                keywords.push(next_keyword.to_string());
                consumed += 1;
            }
            if consumed > 1 {
                out.push(render_bare_keyword_list(&keywords));
                idx += consumed;
                continue;
            }
        }

        if let Some((label, subject, verb, keyword)) =
            split_static_granted_keyword_line(&lines[idx])
        {
            if let Some((label, color, base_subject, keyword)) =
                split_color_static_granted_keyword_line(&lines[idx])
            {
                let mut clauses = vec![(keyword.to_string(), color)];
                let mut consumed = 1usize;
                while let Some(next) = lines.get(idx + consumed) {
                    let Some((_, next_color, next_base_subject, next_keyword)) =
                        split_color_static_granted_keyword_line(next)
                    else {
                        break;
                    };
                    if next_base_subject != base_subject {
                        break;
                    }
                    clauses.push((next_keyword.to_string(), next_color));
                    consumed += 1;
                }
                // This compact conditional surface represents the single
                // five-arm WUBRG clause used by cards such as Scion of Draco.
                // A shorter adjacent run can instead be independent authored
                // source lines (for example, Righteous War), so preserve those
                // line boundaries rather than inventing one conditional.
                if clauses
                    .iter()
                    .map(|(_, color)| *color)
                    .eq(["white", "blue", "black", "red", "green"])
                {
                    out.push(render_color_conditional_keyword_grants(
                        label,
                        base_subject,
                        &clauses,
                    ));
                    idx += consumed;
                    continue;
                }
            }

            let mut keywords = vec![keyword.to_string()];
            let mut consumed = 1usize;
            while let Some(next) = lines.get(idx + consumed) {
                let Some((_, next_subject, next_verb, next_keyword)) =
                    split_static_granted_keyword_line(next)
                else {
                    break;
                };
                if next_subject != subject || next_verb != verb {
                    break;
                }
                keywords.push(next_keyword.to_string());
                consumed += 1;
            }
            if consumed > 1 {
                out.push(format!(
                    "{label}{subject} {verb} {}",
                    render_keyword_list(&keywords, false)
                ));
                idx += consumed;
                continue;
            }
        }

        out.push(lines[idx].clone());
        idx += 1;
    }
    out
}

fn split_kicker_cost_line(line: &str) -> Option<&str> {
    let trimmed = line.trim().trim_end_matches('.');
    let cost = trimmed.strip_prefix("Kicker ")?.trim();
    (!cost.is_empty()).then_some(cost)
}

fn split_keyword_ability_line(line: &str) -> Option<(&str, &str)> {
    let (prefix, keyword) = line.split_once(": ")?;
    if !prefix.starts_with("Keyword ability ") || !is_mergeable_keyword_surface(keyword) {
        return None;
    }
    Some((&line[..prefix.len() + 2], keyword.trim_end_matches('.')))
}

fn split_bare_keyword_line(line: &str) -> Option<&str> {
    let keyword = line.trim().trim_end_matches('.');
    if keyword.contains(':') || !is_mergeable_keyword_surface(keyword) {
        return None;
    }
    Some(keyword)
}

fn split_static_intrinsic_keyword_line(line: &str) -> Option<(&str, &str)> {
    let (prefix, keyword) = line.split_once(": ")?;
    if !prefix.starts_with("Static ability ") || !is_mergeable_keyword_surface(keyword) {
        return None;
    }
    Some((&line[..prefix.len() + 2], keyword.trim_end_matches('.')))
}

fn split_intrinsic_keyword_line(line: &str) -> Option<(&str, &str)> {
    split_keyword_ability_line(line).or_else(|| split_static_intrinsic_keyword_line(line))
}

/// A numbered intrinsic can finish an ordinary keyword list even when it is
/// kept out of the general mergeable-keyword set. Keeping this trailing-only
/// avoids treating a standalone parameterized ability as a list anchor.
fn split_trailing_numbered_intrinsic_keyword_line(line: &str) -> Option<&str> {
    let (prefix, keyword) = line.split_once(": ")?;
    if !prefix.starts_with("Keyword ability ")
        && !prefix.starts_with("Static ability ")
        && !prefix.starts_with("Triggered ability ")
    {
        return None;
    }
    let keyword = keyword.trim_end_matches('.');
    let lower = keyword.to_ascii_lowercase();
    lower
        .strip_prefix("annihilator ")
        .or_else(|| lower.strip_prefix("firebending "))?
        .parse::<u32>()
        .ok()?;
    Some(keyword)
}

fn should_compact_numbered_intrinsic_keywords(keywords: &[String]) -> bool {
    if keywords.len() < 2 {
        return false;
    }
    // Cascade is frequently authored as its own physical ability line. An
    // actual inline keyword group carries the explicit source-line sentinel
    // handled above; without it, keep Cascade's boundary instead of merging a
    // neighboring Flash/Reach run merely because it has three members.
    if keywords.iter().any(|keyword| {
        keyword
            .trim_end_matches('.')
            .eq_ignore_ascii_case("cascade")
    }) {
        return false;
    }
    // A two-ability run is also the exact AST shape produced by adjacent
    // authored keyword lines (for example, Reach followed by Daybound), so
    // keep those top-level boundaries. Longer runs are conventional inline
    // keyword lists. A homogeneous protection run is one decomposed
    // protection surface ("from black and from red"), not separate lines.
    keywords.len() > 2
        || keywords.iter().all(|keyword| {
            keyword
                .trim_end_matches('.')
                .to_ascii_lowercase()
                .starts_with("protection from ")
        })
}

fn split_static_granted_keyword_line(line: &str) -> Option<(&str, &str, &str, &str)> {
    let (label, text) = line.split_once(": ")?;
    if !label.starts_with("Static ability ") {
        return None;
    }
    let keyword = text.trim_end_matches('.');
    let (subject, verb, keyword) = if let Some((subject, keyword)) = keyword.split_once(" have ") {
        (subject, "have", keyword)
    } else if let Some((subject, keyword)) = keyword.split_once(" has ") {
        (subject, "has", keyword)
    } else {
        return None;
    };
    if !is_mergeable_keyword_surface(keyword) {
        return None;
    }
    Some((&line[..label.len() + 2], subject, verb, keyword))
}

fn split_color_static_granted_keyword_line(line: &str) -> Option<(&str, &'static str, &str, &str)> {
    let (label, text) = line.split_once(": ")?;
    if !label.starts_with("Static ability ") {
        return None;
    }
    let text = text.trim_end_matches('.');
    let (subject, keyword) = text.split_once(" have ")?;
    if !is_mergeable_keyword_surface(keyword) {
        return None;
    }
    let (color, base_subject) = subject.split_once(' ')?;
    let color = match color.to_ascii_lowercase().as_str() {
        "white" => "white",
        "blue" => "blue",
        "black" => "black",
        "red" => "red",
        "green" => "green",
        _ => return None,
    };
    Some((&line[..label.len() + 2], color, base_subject, keyword))
}

fn render_color_conditional_keyword_grants(
    label: &str,
    base_subject: &str,
    clauses: &[(String, &'static str)],
) -> String {
    let clauses = clauses
        .iter()
        .map(|(keyword, color)| {
            format!(
                "{} if it's {color}",
                keyword.trim_end_matches('.').to_ascii_lowercase()
            )
        })
        .collect::<Vec<_>>();
    let subject = if base_subject.eq_ignore_ascii_case("creatures you control") {
        "Each creature you control has".to_string()
    } else {
        format!("{base_subject} have")
    };
    format!("{label}{subject} {}", join_english_list(&clauses))
}

fn ability_level_range_prefix(ability: &Ability) -> Option<String> {
    let AbilityKind::Activated(activated) = &ability.kind else {
        return None;
    };
    level_range_activation_prefix(activated)
}

fn ability_has_level_tiers(ability: &Ability) -> bool {
    matches!(
        &ability.kind,
        AbilityKind::Static(static_ability)
            if static_ability.level_abilities().is_some_and(|levels| !levels.is_empty())
    )
}

fn level_tier_header_range(line: &str) -> Option<String> {
    let (_, text) = line.split_once(": ")?;
    let range = text.trim().trim_end_matches('.');
    range.starts_with("Level ").then(|| range.to_string())
}

fn interleave_level_range_activations(
    lines: Vec<String>,
    abilities: &[Ability],
    subject: &str,
    rewrite_it_deals: bool,
) -> Vec<String> {
    let mut out = Vec::new();
    let mut active_range: Option<String> = None;
    for line in lines {
        if let Some(next_range) = level_tier_header_range(&line) {
            flush_level_range_activations(
                &mut out,
                active_range.as_deref(),
                abilities,
                subject,
                rewrite_it_deals,
            );
            active_range = Some(next_range);
        }
        out.push(line);
    }
    flush_level_range_activations(
        &mut out,
        active_range.as_deref(),
        abilities,
        subject,
        rewrite_it_deals,
    );
    out
}

fn flush_level_range_activations(
    out: &mut Vec<String>,
    range: Option<&str>,
    abilities: &[Ability],
    subject: &str,
    rewrite_it_deals: bool,
) {
    let Some(range) = range else {
        return;
    };
    let range_prefix = format!("{range}. ");
    for (idx, ability) in abilities.iter().enumerate() {
        if ability_level_range_prefix(ability).as_deref() != Some(range) {
            continue;
        }
        for line in describe_ability(idx + 1, ability, subject, rewrite_it_deals) {
            out.push(
                line.strip_prefix(&range_prefix)
                    .unwrap_or(line.as_str())
                    .to_string(),
            );
        }
    }
}

fn is_mergeable_keyword_surface(keyword: &str) -> bool {
    let keyword = keyword.trim_end_matches('.');
    let lower = keyword.to_ascii_lowercase();
    // Partner-with carries a structurally modeled card-name payload. Keep it
    // on its own line so the ordinary intrinsic-keyword list renderer does
    // not lowercase that payload or absorb a following keyword.
    let carries_named_partner = lower.starts_with("partner with ");
    let is_numbered_firebending = lower
        .strip_prefix("firebending ")
        .is_some_and(|amount| amount.parse::<u32>().is_ok());
    (is_keyword_phrase(keyword) && lower != "changeling" && !carries_named_partner)
        || lower == "cascade"
        || is_numbered_firebending
        || matches!(
            lower.as_str(),
            "flying"
                | "first strike"
                | "double strike"
                | "vigilance"
                | "trample"
                | "haste"
                | "lifelink"
                | "deathtouch"
                | "menace"
                | "reach"
                | "hexproof"
                | "indestructible"
                | "shroud"
                | "fear"
                | "soulbond"
                | "ward pay 3 life"
        )
}

fn render_keyword_list(keywords: &[String], capitalize: bool) -> String {
    render_keyword_list_with_separator(keywords, capitalize, KeywordListSeparator::EnglishAnd)
}

#[derive(Clone, Copy)]
enum KeywordListSeparator {
    Comma,
    EnglishAnd,
}

fn render_intrinsic_keyword_list(keywords: &[String], capitalize: bool) -> String {
    render_keyword_list_with_separator(keywords, capitalize, KeywordListSeparator::Comma)
}

fn render_keyword_list_with_separator(
    keywords: &[String],
    capitalize: bool,
    separator: KeywordListSeparator,
) -> String {
    let mut items = Vec::new();
    let mut protections = Vec::new();
    for keyword in keywords {
        let lower = keyword.trim_end_matches('.').to_ascii_lowercase();
        if let Some(from) = lower.strip_prefix("protection from ") {
            protections.push(from.to_string());
        } else {
            items.push(lower);
        }
    }
    if !protections.is_empty() {
        let protection = if protections.len() == 1 {
            format!("protection from {}", protections[0])
        } else {
            format!(
                "protection from {}",
                join_english_list(
                    &protections
                        .iter()
                        .enumerate()
                        .map(|(idx, value)| {
                            if idx == 0 {
                                value.clone()
                            } else {
                                format!("from {value}")
                            }
                        })
                        .collect::<Vec<_>>()
                )
            )
        };
        items.push(protection);
    }
    let rendered = match separator {
        KeywordListSeparator::Comma => items.join(", "),
        KeywordListSeparator::EnglishAnd => join_english_list(&items),
    };
    if capitalize {
        capitalize_first(&rendered)
    } else {
        rendered
    }
}

fn render_bare_keyword_list(keywords: &[String]) -> String {
    let mut items = Vec::new();
    for keyword in keywords {
        let lower = keyword.trim_end_matches('.').to_ascii_lowercase();
        if !items.iter().any(|existing| existing == &lower) {
            items.push(lower);
        }
    }
    capitalize_first(&items.join(", "))
}

fn join_english_list(items: &[String]) -> String {
    match items {
        [] => String::new(),
        [one] => one.clone(),
        [first, second] => format!("{first} and {second}"),
        _ => {
            let (last, rest) = items.split_last().expect("nonempty");
            format!("{}, and {}", rest.join(", "), last)
        }
    }
}

fn modeled_source_keyword_grant(
    ability: &Ability,
) -> Option<(crate::static_abilities::StaticAbilityId, String, &Condition)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    if let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: granted,
        condition,
    } = &model.payload
    {
        let keyword = crate::static_abilities::StaticAbility::from_model(granted.as_ref().clone());
        if !keyword.is_keyword() {
            return None;
        }
        let keyword_text = keyword
            .display()
            .trim()
            .trim_end_matches('.')
            .to_ascii_lowercase();
        if !is_mergeable_keyword_surface(&keyword_text) {
            return None;
        }
        return Some((keyword.id(), keyword_text, condition));
    }
    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) = &model.payload
    else {
        return None;
    };
    if grant.filter != ObjectFilter::source()
        || !grant.additional_abilities.is_empty()
        || grant.set_quantifier_surface.is_some()
        || grant.ability.functional_zones.as_slice() != [Zone::Battlefield]
    {
        return None;
    }
    let ironsmith_core::AbilityKind::Static(granted) = &grant.ability.kind else {
        return None;
    };
    let keyword = crate::static_abilities::StaticAbility::from_model(granted.clone());
    if !keyword.is_keyword() {
        return None;
    }
    let keyword_text = keyword
        .display()
        .trim()
        .trim_end_matches('.')
        .to_ascii_lowercase();
    if !is_mergeable_keyword_surface(&keyword_text) {
        return None;
    }
    Some((keyword.id(), keyword_text, grant.condition.as_ref()?))
}

fn modeled_object_static_grant(
    ability: &Ability,
) -> Option<(
    &ObjectFilter,
    Option<&Condition>,
    crate::static_abilities::StaticAbility,
)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) = &model.payload
    else {
        return None;
    };
    if !grant.additional_abilities.is_empty()
        || grant.set_quantifier_surface.is_some()
        || grant.ability.functional_zones.as_slice() != [Zone::Battlefield]
    {
        return None;
    }
    let ironsmith_core::AbilityKind::Static(granted) = &grant.ability.kind else {
        return None;
    };
    Some((
        &grant.filter,
        grant.condition.as_ref(),
        crate::static_abilities::StaticAbility::from_model(granted.clone()),
    ))
}

/// Read an unquantified object grant through either runtime grant payload.
/// Parser families use `GrantObjectAbilityForFilter` for executable object
/// grants and `GrantAbility` for modeled static rules, but adjacent authored
/// grants can legitimately contain one of each.
fn modeled_unquantified_object_static_grant(
    ability: &Ability,
) -> Option<(
    &ObjectFilter,
    Option<&Condition>,
    crate::static_abilities::StaticAbility,
)> {
    if let Some(grant) = modeled_object_static_grant(ability) {
        return Some(grant);
    }
    let (filter, condition, quantifier, granted) = modeled_filter_static_grant(ability)?;
    quantifier.is_none().then_some((filter, condition, granted))
}

fn modeled_filter_static_grant(
    ability: &Ability,
) -> Option<(
    &ObjectFilter,
    Option<&Condition>,
    Option<&ironsmith_core::SetQuantifierSurface>,
    crate::static_abilities::StaticAbility,
)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::GrantAbility(grant) = &model.payload else {
        return None;
    };
    if grant.ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let ironsmith_core::AbilityKind::Static(granted) = &grant.ability.kind else {
        return None;
    };
    Some((
        &grant.filter,
        grant.condition.as_ref(),
        grant.set_quantifier_surface.as_ref(),
        crate::static_abilities::StaticAbility::from_model(granted.clone()),
    ))
}

fn is_can_block_additional_each_combat_rule(
    ability: &crate::static_abilities::StaticAbility,
) -> bool {
    ability.compiled_model().is_some_and(|model| {
        matches!(
            model.payload,
            ironsmith_core::StaticAbilityPayload::CanBlockAdditionalCreatureEachCombat(_)
        )
    })
}

/// Rejoin the two independently executable Cascade grants produced by an
/// authored `"Cascade, cascade."` clause.  The two abilities remain separate
/// in the model so the spell cascades twice; matching the complete affected
/// spell filter keeps cast-origin and mana-value restrictions correlated.
fn describe_structural_repeated_cascade_grant_pair(
    abilities: &[Ability],
) -> Option<(String, usize)> {
    let [first, second, ..] = abilities else {
        return None;
    };
    let (first_filter, first_condition, first_granted) = modeled_object_static_grant(first)?;
    let (second_filter, second_condition, second_granted) = modeled_object_static_grant(second)?;
    if first_filter != second_filter
        || first_condition.is_some()
        || second_condition.is_some()
        || first_filter.stack_kind != Some(crate::filter::StackObjectKind::Spell)
        || first_granted.id() != crate::static_abilities::StaticAbilityId::Cascade
        || second_granted.id() != crate::static_abilities::StaticAbilityId::Cascade
    {
        return None;
    }

    let AbilityKind::Static(first_static) = &first.kind else {
        return None;
    };
    let AbilityKind::Static(second_static) = &second.kind else {
        return None;
    };
    let first_display = first_static.display();
    let second_display = second_static.display();
    let (subject, first_tail, verb) =
        split_static_predicate_with_verb(&first_display, &[" has ", " have "])?;
    let (second_subject, second_tail, second_verb) =
        split_static_predicate_with_verb(&second_display, &[" has ", " have "])?;
    if subject != second_subject
        || verb != second_verb
        || !first_tail.trim().eq_ignore_ascii_case("cascade")
        || !second_tail.trim().eq_ignore_ascii_case("cascade")
    {
        return None;
    }

    Some((format!("{subject} {verb} \"Cascade, cascade.\""), 2))
}

#[cfg(test)]
mod repeated_cascade_grant_tests {
    use super::*;

    fn cascade_grant(filter: ObjectFilter) -> Ability {
        let cascade: crate::static_abilities::CompiledStaticAbility =
            ironsmith_core::StaticAbility::cascade();
        let granted = ironsmith_core::Ability {
            kind: ironsmith_core::AbilityKind::Static(cascade),
            functional_zones: vec![Zone::Battlefield],
        };
        let model: crate::static_abilities::CompiledStaticAbility =
            ironsmith_core::StaticAbility::new(ironsmith_core::GrantObjectAbilityForFilter::new(
                filter, granted, "Cascade",
            ));
        Ability::static_ability(crate::static_abilities::StaticAbility::from_model(model))
    }

    #[test]
    fn compacts_only_equal_spell_filters_with_two_cascade_grants() {
        let mut from_hand = ObjectFilter::spell()
            .cast_by(PlayerFilter::You)
            .in_zone(Zone::Hand);
        from_hand.colorless = true;
        from_hand.mana_value = Some(crate::filter::Comparison::GreaterThanOrEqual(7));
        from_hand.has_mana_cost = true;

        let equal = [
            cascade_grant(from_hand.clone()),
            cascade_grant(from_hand.clone()),
        ];
        assert_eq!(
            describe_structural_repeated_cascade_grant_pair(&equal),
            Some((
                "Colorless spells you cast from your hand with mana value 7 or greater have \"Cascade, cascade.\""
                    .to_string(),
                2,
            ))
        );

        let mut from_exile = from_hand.clone();
        from_exile.zone = Some(Zone::Exile);
        let changed_origin = [cascade_grant(from_hand), cascade_grant(from_exile)];
        assert!(describe_structural_repeated_cascade_grant_pair(&changed_origin).is_none());

        let permanents = [
            cascade_grant(ObjectFilter::creature()),
            cascade_grant(ObjectFilter::creature()),
        ];
        assert!(describe_structural_repeated_cascade_grant_pair(&permanents).is_none());
    }
}

/// Render complete nonkeyword static abilities granted to the same filtered
/// object set as quoted ability text. The executable grants stay independent;
/// this only restores the single authored `have "..." and "..."` surface.
fn describe_structural_quoted_static_grant_bundle(
    abilities: &[Ability],
) -> Option<(String, usize)> {
    let first = abilities.first()?;
    let (filter, condition, set_quantifier, first_granted) = modeled_filter_static_grant(first)?;
    if condition.is_some()
        || first_granted.is_keyword()
        || is_can_block_additional_each_combat_rule(&first_granted)
    {
        return None;
    }
    let AbilityKind::Static(first_static) = &first.kind else {
        return None;
    };
    let first_display = first_static.display();
    let (subject, _, verb) =
        split_static_predicate_with_verb(&first_display, &[" has ", " have "])?;
    let self_subject = granted_ability_self_subject_for_filter(filter);

    let mut quoted = Vec::new();
    let mut consumed = 0usize;
    for ability in abilities {
        let Some((next_filter, next_condition, next_quantifier, granted)) =
            modeled_filter_static_grant(ability)
        else {
            break;
        };
        if next_filter != filter
            || next_condition != condition
            || next_quantifier != set_quantifier
            || granted.is_keyword()
            || is_can_block_additional_each_combat_rule(&granted)
        {
            break;
        }
        let AbilityKind::Static(next_static) = &ability.kind else {
            break;
        };
        let next_display = next_static.display();
        let Some((next_subject, _, next_verb)) =
            split_static_predicate_with_verb(&next_display, &[" has ", " have "])
        else {
            break;
        };
        if next_subject != subject || next_verb != verb {
            break;
        }

        let rendered = describe_static_ability_with_subject(&granted, self_subject);
        let rendered = rendered.trim().trim_end_matches('.');
        if rendered.is_empty() {
            break;
        }
        quoted.push(rendered.to_string());
        consumed += 1;
    }
    if quoted.is_empty() {
        return None;
    }

    let last = quoted.len().saturating_sub(1);
    let quoted = quoted
        .into_iter()
        .enumerate()
        .map(|(idx, mut ability)| {
            if idx == last && !ability.ends_with(['!', '?']) {
                ability.push('.');
            }
            format!("\"{ability}\"")
        })
        .collect::<Vec<_>>();
    Some((
        format!("{subject} {verb} {}", join_english_list(&quoted)),
        consumed,
    ))
}

#[derive(Debug)]
enum AttachedGrantSurface {
    Keyword(String),
    Quoted(String),
}

fn capitalize_quoted_grant_instruction(text: &str) -> String {
    if let Some((cost, instruction)) = text.split_once(": ") {
        format!("{cost}: {}", capitalize_first(instruction))
    } else {
        capitalize_first(text)
    }
}

fn modeled_attached_grant_surface(ability: &Ability) -> Option<(String, AttachedGrantSurface)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let (authored_tail, granted) = match &model.payload {
        ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant)
            if grant.condition.is_none()
                && grant.additional_abilities.is_empty()
                && grant.set_quantifier_surface.is_none() =>
        {
            (
                grant.display.as_str(),
                crate::static_abilities::StaticAbilityModelInterpreter::ability_from_model(
                    &grant.ability,
                ),
            )
        }
        ironsmith_core::StaticAbilityPayload::AttachedAbilityGrant(grant)
            if grant.condition.is_none() && grant.additional_abilities.is_empty() =>
        {
            let display = grant.display.trim().trim_end_matches('.');
            let (_, tail, _) = split_static_predicate_with_verb(display, &[" has ", " have "])?;
            (
                tail,
                crate::static_abilities::StaticAbilityModelInterpreter::ability_from_model(
                    &grant.ability,
                ),
            )
        }
        _ => return None,
    };

    let display = static_ability.display();
    let display = display.trim().trim_end_matches('.');
    let (subject, _, _) = split_static_predicate_with_verb(display, &[" has ", " have "])?;
    let normalized_subject = subject.to_ascii_lowercase();
    if !matches!(
        normalized_subject.as_str(),
        "enchanted creature" | "equipped creature"
    ) {
        return None;
    }

    let surface = match &granted.kind {
        AbilityKind::Static(granted_static) if granted_static.is_keyword() => {
            AttachedGrantSurface::Keyword(
                granted_static
                    .display()
                    .trim()
                    .trim_end_matches('.')
                    .to_ascii_lowercase(),
            )
        }
        AbilityKind::Triggered(triggered) if describe_annihilator_keyword(triggered).is_some() => {
            AttachedGrantSurface::Keyword(lowercase_first(&describe_annihilator_keyword(
                triggered,
            )?))
        }
        AbilityKind::Activated(_) | AbilityKind::Triggered(_) | AbilityKind::Static(_) => {
            let tail = authored_tail
                .strip_prefix('"')
                .and_then(|body| body.strip_suffix('"'))
                .unwrap_or(authored_tail)
                .trim()
                .trim_end_matches('.');
            if tail.is_empty() {
                return None;
            }
            AttachedGrantSurface::Quoted(capitalize_quoted_grant_instruction(tail))
        }
    };
    Some((normalized_subject, surface))
}

fn render_attached_grant_surfaces(surfaces: &[AttachedGrantSurface]) -> Option<String> {
    if surfaces.is_empty()
        || !surfaces
            .iter()
            .any(|surface| matches!(surface, AttachedGrantSurface::Quoted(_)))
    {
        return None;
    }

    let last = surfaces.len() - 1;
    let mut rendered = Vec::with_capacity(surfaces.len());
    for (idx, surface) in surfaces.iter().enumerate() {
        let is_last = idx == last;
        let use_serial_comma = surfaces.len() > 2 && !is_last;
        let item = match surface {
            AttachedGrantSurface::Keyword(keyword) => {
                if use_serial_comma {
                    format!("{},", keyword.trim_end_matches([',', '.']))
                } else {
                    keyword.trim_end_matches([',', '.']).to_string()
                }
            }
            AttachedGrantSurface::Quoted(text) => {
                let text = text.trim_end_matches([',', '.']);
                let punctuation = if is_last {
                    "."
                } else if use_serial_comma {
                    ","
                } else {
                    ""
                };
                format!("\"{text}{punctuation}\"")
            }
        };
        rendered.push(item);
    }
    let final_item = rendered.pop()?;
    Some(if rendered.is_empty() {
        final_item
    } else {
        format!("{} and {final_item}", rendered.join(" "))
    })
}

/// Render authored attached-object grants from their typed payloads. Lowering
/// intentionally emits one continuous effect per granted ability, while a
/// mixed authored surface is one keyword/quoted-ability list.
fn describe_structural_attached_mixed_grant_bundle(
    abilities: &[Ability],
) -> Option<(String, usize)> {
    let (subject, first_surface) = modeled_attached_grant_surface(abilities.first()?)?;
    let mut surfaces = vec![first_surface];
    let mut consumed = 1usize;

    while let Some(ability) = abilities.get(consumed) {
        let Some((next_subject, next_surface)) = modeled_attached_grant_surface(ability) else {
            break;
        };
        if next_subject != subject {
            break;
        }
        surfaces.push(next_surface);
        consumed += 1;
    }

    Some((
        format!(
            "{} has {}",
            capitalize_first(&subject),
            render_attached_grant_surfaces(&surfaces)?
        ),
        consumed,
    ))
}

#[cfg(test)]
mod quoted_static_grant_bundle_tests {
    use super::*;

    #[test]
    fn complete_static_rules_granted_to_one_filter_render_as_quoted_abilities() {
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Static Grant Probe",
        )
        .card_types(vec![CardType::Enchantment])
        .parse_text(
            "Commander creatures you own have \"This creature enters with an additional +1/+1 counter on it\" and \"Other creatures you control enter with an additional +1/+1 counter on them.\"",
        )
        .expect("quoted static grant bundle should compile");

        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            vec![
                "Commander creatures you own have \"This creature enters with an additional +1/+1 counter on it\" and \"Other creatures you control enter with an additional +1/+1 counter on them.\""
                    .to_string()
            ]
        );
    }

    #[test]
    fn keyword_grants_remain_unquoted() {
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Keyword Grant Probe",
        )
        .card_types(vec![CardType::Enchantment])
        .parse_text("Creatures you control have flying.")
        .expect("keyword grant should compile");

        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            vec!["Creatures you control have flying.".to_string()]
        );
    }

    #[test]
    fn attached_mixed_keyword_and_quoted_grants_restore_one_authored_list() {
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Attached Grant Probe",
        )
        .card_types(vec![CardType::Artifact])
        .parse_text(
            "Equipped creature has reach, \"{2}, {T}: Tap target artifact or creature,\" and \"{8}, {T}: Discover 10.\"",
        )
        .expect("mixed attached grants should compile");
        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            vec![
                "Equipped creature has reach, \"{2}, {T}: Tap target artifact or creature,\" and \"{8}, {T}: Discover 10.\""
                    .to_string()
            ]
        );
    }
}

/// Render a granted blocking-capacity rule as the direct rule text it
/// represents instead of treating the rule as a keyword-like noun.
///
/// The generic grant display is intentionally phrased as
/// `"<objects> have <ability>"`, which is appropriate for keywords and quoted
/// abilities. `CanBlockAdditionalCreatureEachCombat` is a rules sentence,
/// though: its authored surface is `"<objects> can block ..."`. Keeping this
/// distinction typed also prevents a separately authored vigilance line from
/// being merged into the blocking rule as one synthetic trait list.
fn describe_structural_can_block_additional_grant(ability: &Ability) -> Option<String> {
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let (condition, granted) =
        if let Some((_, condition, _, granted)) = modeled_filter_static_grant(ability) {
            (condition, granted)
        } else {
            let (_, condition, granted) = modeled_object_static_grant(ability)?;
            (condition, granted)
        };
    if condition.is_some() || !is_can_block_additional_each_combat_rule(&granted) {
        return None;
    }

    let display = static_ability.display();
    let display = display.trim().trim_end_matches('.');
    let (subject, _, _) = split_static_predicate_with_verb(display, &[" has ", " have "])?;
    let rule = granted.display();
    let rule = rule.trim().trim_end_matches('.');
    Some(format!("{subject} {}", lowercase_first(rule)))
}

#[cfg(test)]
mod can_block_additional_grant_tests {
    use super::*;

    #[test]
    fn both_typed_grant_families_render_block_capacity_as_a_direct_rule() {
        let filter = ObjectFilter::creature().you_control();
        let blocking_model: crate::static_abilities::CompiledStaticAbility =
            ironsmith_core::StaticAbility {
                id: Some(
                    crate::static_abilities::StaticAbilityId::CanBlockAdditionalCreatureEachCombat,
                ),
                label: "can block additional creature".to_string(),
                payload: ironsmith_core::StaticAbilityPayload::CanBlockAdditionalCreatureEachCombat(
                    1,
                ),
            };
        let granted = ironsmith_core::Ability {
            kind: ironsmith_core::AbilityKind::Static(blocking_model),
            functional_zones: vec![Zone::Battlefield],
        };
        let grant_ability_model: crate::static_abilities::CompiledStaticAbility =
            ironsmith_core::StaticAbility::new(ironsmith_core::GrantAbility::new(
                filter.clone(),
                granted.clone(),
            ));
        let grant_object_model: crate::static_abilities::CompiledStaticAbility =
            ironsmith_core::StaticAbility::new(ironsmith_core::GrantObjectAbilityForFilter::new(
                filter,
                granted,
                "Can block an additional creature each combat",
            ));
        let grants = [
            crate::static_abilities::StaticAbility::from_model(grant_ability_model),
            crate::static_abilities::StaticAbility::from_model(grant_object_model),
        ];

        for grant in grants {
            let definition = crate::cards::builders::CardDefinitionBuilder::new(
                crate::ids::CardId::new(),
                "Blocking Capacity Grant Probe",
            )
            .card_types(vec![CardType::Enchantment])
            .with_ability(Ability::static_ability(grant))
            .build();

            assert_eq!(
                crate::compiled_text::compiled_text_lines(&definition),
                vec![
                    "Creatures you control can block an additional creature each combat."
                        .to_string()
                ]
            );
        }
    }
}

/// Recombine adjacent, independently executable grants from an authored
/// "has [keywords] and can't be blocked by more than N creatures" clause.
/// Matching the typed affected filter and condition prevents a restriction on
/// the source from being folded into an attachment grant.
fn describe_structural_keyword_maximum_blocker_bundle(
    abilities: &[Ability],
) -> Option<(String, usize)> {
    let first = abilities.first()?;
    let (filter, condition, first_granted) = modeled_unquantified_object_static_grant(first)?;
    if !first_granted.is_keyword() {
        return None;
    }
    let AbilityKind::Static(first_static) = &first.kind else {
        return None;
    };
    let first_display = first_static.display();
    let (subject, _, verb) =
        split_static_predicate_with_verb(&first_display, &[" has ", " have "])?;
    let has_verb = if verb == "have" { "have" } else { "has" };

    let mut keywords = Vec::new();
    let mut consumed = 0usize;
    for ability in abilities {
        let (next_filter, next_condition, granted) =
            modeled_unquantified_object_static_grant(ability)?;
        if next_filter != filter || next_condition != condition {
            return None;
        }
        if granted.is_keyword() {
            let keyword = granted
                .display()
                .trim()
                .trim_end_matches('.')
                .to_ascii_lowercase();
            if !is_mergeable_keyword_surface(&keyword) {
                return None;
            }
            keywords.push(keyword);
            consumed += 1;
            continue;
        }
        let model = granted.compiled_model()?;
        let ironsmith_core::StaticAbilityPayload::CantBeBlockedByMoreThan(maximum) = &model.payload
        else {
            return None;
        };
        if keywords.is_empty() {
            return None;
        }
        consumed += 1;
        let maximum = small_number_word(*maximum as u32).unwrap_or_else(|| maximum.to_string());
        let creature = if maximum == "one" {
            "creature"
        } else {
            "creatures"
        };
        return Some((
            capitalize_first(&format!(
                "{subject} {has_verb} {} and can't be blocked by more than {maximum} {creature}",
                render_keyword_list(&keywords, false)
            )),
            consumed,
        ));
    }
    None
}

/// Render one conditional keyword granted to the source from its typed model.
/// Keeping the condition out of the grammatical subject avoids plural nouns in
/// the condition (for example, "three artifacts") selecting `have` for the
/// singular source.
fn describe_structural_conditional_source_keyword_grant(
    ability: &Ability,
    subject: &str,
) -> Option<String> {
    let (_, keyword, condition) = modeled_source_keyword_grant(ability)?;
    if matches!(
        condition,
        Condition::ActivationTiming(crate::ability::ActivationTiming::DuringYourTurn)
    ) {
        return Some(format!("During your turn, {subject} has {keyword}"));
    }
    let prefix_surface = matches!(
        condition,
        Condition::Not(inner)
            if matches!(inner.as_ref(), Condition::PlayerCastSpellsThisTurnOrMore { .. })
    ) || matches!(
        condition,
        Condition::PlayerLifeAtMostHalfStartingLifeTotal { .. }
    ) || matches!(
        condition,
        Condition::ValueComparison { left, .. }
            if matches!(left.unhinted(), Value::MaxDiceRolledThisTurn(_))
    ) || matches!(
        condition,
        Condition::TurnHistory(
            ironsmith_core::TurnHistoryCondition::PlayerVisitedAttractionThisTurn(_)
        )
    ) || matches!(
        condition,
        Condition::CountComparison {
            count: ironsmith_core::AnthemCountExpression::CountersAmong(_, _),
            ..
        }
    );
    let condition = describe_condition(condition);
    let condition = condition
        .strip_prefix("this permanent")
        .map(|rest| format!("{}{rest}", lowercase_first(subject)))
        .unwrap_or(condition);
    if prefix_surface {
        Some(format!("As long as {condition}, {subject} has {keyword}"))
    } else {
        Some(format!("{subject} has {keyword} as long as {condition}"))
    }
}

fn modeled_conditioned_source_anthem(ability: &Ability) -> Option<(i32, i32, &Condition)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    if static_ability.id() != crate::static_abilities::StaticAbilityId::Anthem {
        return None;
    }
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::Anthem(anthem) = &model.payload else {
        return None;
    };
    if anthem.filter.is_some()
        || anthem.set_quantifier_surface.is_some()
        || anthem.count_uses_where_x
        || anthem.additional_surface
        || anthem.replacement_surface.is_some()
    {
        return None;
    }
    let (ironsmith_core::AnthemValue::Fixed(power), ironsmith_core::AnthemValue::Fixed(toughness)) =
        (&anthem.power, &anthem.toughness)
    else {
        return None;
    };
    if (*power, *toughness) == (0, 0) {
        return None;
    }
    Some((*power, *toughness, anthem.condition.as_ref()?))
}

fn modeled_direct_conditional_source_rule(
    ability: &Ability,
    expected_id: crate::static_abilities::StaticAbilityId,
) -> Option<&Condition> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: inner,
        condition,
    } = &model.payload
    else {
        return None;
    };
    (inner.id == Some(expected_id)
        && matches!(&inner.payload, ironsmith_core::StaticAbilityPayload::None))
    .then_some(condition)
}

fn delirium_condition_surface(condition: &Condition) -> Option<&'static str> {
    matches!(
        condition,
        Condition::PlayerHasCardTypesInGraveyardOrMore {
            player: PlayerFilter::You,
            count: 4,
        }
    )
    .then_some("there are four or more card types among cards in your graveyard")
}

/// Render source-relative counter thresholds from their executable values.
/// Named counter predicates lower through `CountComparison`, while Oracle's
/// untyped "counters on it" form uses `ValueComparison::CountersOn`.
fn source_counter_threshold_condition_surface(
    condition: &Condition,
    source_subject: &str,
) -> Option<String> {
    let (counter_type, source_surface, comparison, object_pronoun) = match condition {
        Condition::CountComparison {
            count: ironsmith_core::AnthemCountExpression::CountersOnSource(counter_type),
            comparison,
            ..
        } => (Some(*counter_type), None, *comparison, "it"),
        Condition::CountComparison {
            count:
                ironsmith_core::AnthemCountExpression::CountersOnSourceWithSurface {
                    counter_type,
                    surface,
                },
            comparison,
            ..
        } => (
            Some(*counter_type),
            Some(surface.display_text()),
            *comparison,
            "it",
        ),
        Condition::CountComparison {
            count:
                ironsmith_core::AnthemCountExpression::CountersOnSourceWithPronoun {
                    counter_type,
                    pronoun,
                },
            comparison,
            ..
        } => (
            Some(*counter_type),
            None,
            *comparison,
            pronoun.object_pronoun(),
        ),
        Condition::CountComparison {
            count: ironsmith_core::AnthemCountExpression::MatchingFilter(filter),
            comparison,
            ..
        } => {
            let Some(ironsmith_core::CounterConstraint::Typed(counter_type)) = filter.with_counter
            else {
                return None;
            };
            if filter != &ObjectFilter::source().with_counter_type(counter_type) {
                return None;
            }
            (Some(counter_type), None, *comparison, "it")
        }
        Condition::ValueComparison {
            left,
            operator,
            right,
        } => {
            let Value::CountersOn(spec, counter_type) = left.unhinted() else {
                return None;
            };
            if !matches!(spec.base(), ChooseSpec::Source) {
                return None;
            }
            let Value::Fixed(threshold) = right.unhinted() else {
                return None;
            };
            let comparison = match operator {
                ironsmith_core::ValueComparisonOperator::GreaterThan => {
                    Comparison::GreaterThan(*threshold)
                }
                ironsmith_core::ValueComparisonOperator::GreaterThanOrEqual => {
                    Comparison::GreaterThanOrEqual(*threshold)
                }
                ironsmith_core::ValueComparisonOperator::Equal => Comparison::Equal(*threshold),
                ironsmith_core::ValueComparisonOperator::LessThan => {
                    Comparison::LessThan(*threshold)
                }
                ironsmith_core::ValueComparisonOperator::LessThanOrEqual => {
                    Comparison::LessThanOrEqual(*threshold)
                }
                ironsmith_core::ValueComparisonOperator::NotEqual => {
                    Comparison::NotEqual(*threshold)
                }
            };
            (
                *counter_type,
                spec.source_reference_surface()
                    .map(|surface| surface.display_text()),
                comparison,
                "it",
            )
        }
        _ => return None,
    };

    let typed_counter = counter_type.map(CounterType::description);
    let singular_counter = typed_counter
        .as_deref()
        .map(|counter| format!("{counter} counter"))
        .unwrap_or_else(|| "counter".to_string());
    let plural_counters = typed_counter
        .as_deref()
        .map(|counter| format!("{counter} counters"))
        .unwrap_or_else(|| "counters".to_string());
    let quantity = match comparison {
        Comparison::Equal(0) | Comparison::LessThanOrEqual(0) | Comparison::LessThan(1) => {
            format!("no {plural_counters}")
        }
        Comparison::GreaterThanOrEqual(1) => format!("a {singular_counter}"),
        Comparison::GreaterThanOrEqual(threshold) if threshold > 1 => {
            let threshold = u32::try_from(threshold)
                .ok()
                .and_then(small_number_word)
                .unwrap_or_else(|| threshold.to_string());
            format!("{threshold} or more {plural_counters}")
        }
        _ => return None,
    };
    Some(format!(
        "{} has {quantity} on {object_pronoun}",
        source_surface.as_deref().unwrap_or(source_subject),
    ))
}

/// Extract one counter-threshold static predicate without consulting display
/// text for its condition. This covers source P/T modifiers, source keyword
/// grants, filtered keyword grants (for example, an equipped creature), and
/// direct conditional rules such as attacking despite defender.
fn modeled_source_counter_threshold_static_predicate<'a>(
    ability: &'a Ability,
    source_subject: &str,
) -> Option<(String, String, &'a Condition)> {
    if let Some((power, toughness, condition)) = modeled_conditioned_source_anthem(ability)
        && source_counter_threshold_condition_surface(condition, source_subject).is_some()
    {
        return Some((
            source_subject.to_string(),
            format!("gets {}", describe_fixed_anthem_modifier(power, toughness)),
            condition,
        ));
    }

    if let Some((_, keyword, condition)) = modeled_source_keyword_grant(ability)
        && source_counter_threshold_condition_surface(condition, source_subject).is_some()
    {
        return Some((
            source_subject.to_string(),
            format!("has {keyword}"),
            condition,
        ));
    }

    if let Some((filter, Some(condition), granted)) = modeled_object_static_grant(ability)
        && source_counter_threshold_condition_surface(condition, source_subject).is_some()
        && granted.is_keyword()
    {
        let keyword = granted
            .display()
            .trim()
            .trim_end_matches('.')
            .to_ascii_lowercase();
        if !is_mergeable_keyword_surface(&keyword) {
            return None;
        }
        let (grant_subject, _) =
            crate::static_abilities::grant_subject_with_set_quantifier(filter, None);
        return Some((
            lowercase_first(&grant_subject),
            format!("has {keyword}"),
            condition,
        ));
    }

    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: inner,
        condition,
    } = &model.payload
    else {
        return None;
    };
    if source_counter_threshold_condition_surface(condition, source_subject).is_none() {
        return None;
    }
    if let ironsmith_core::StaticAbilityPayload::SetLandSubtypes { filter, subtypes } =
        &inner.payload
    {
        if subtypes.is_empty() {
            return None;
        }
        let mut subject_filter = filter.clone();
        subject_filter.zone = None;
        let (subject, singular) =
            crate::static_abilities::grant_subject_with_set_quantifier(&subject_filter, None);
        if singular {
            return None;
        }
        let subtype_surface =
            join_english_list(&subtypes.iter().map(ToString::to_string).collect::<Vec<_>>());
        return Some((
            lowercase_first(&subject),
            format!("are {}", pluralize_noun_phrase(&subtype_surface)),
            condition,
        ));
    }
    if !matches!(&inner.payload, ironsmith_core::StaticAbilityPayload::None) {
        return None;
    }
    let inner = crate::static_abilities::StaticAbility::from_model(inner.as_ref().clone());
    let predicate = inner.display().trim().trim_end_matches('.').to_string();
    (!predicate.is_empty()).then(|| {
        (
            source_subject.to_string(),
            lowercase_first(&predicate),
            condition,
        )
    })
}

/// Rejoin adjacent layer-correct predicates that share the exact same typed
/// source-counter threshold, then place that condition in Oracle's leading
/// `As long as ...` position.
fn describe_structural_source_counter_threshold_static_bundle(
    abilities: &[Ability],
    source_subject: &str,
) -> Option<(String, usize)> {
    let (body_subject, first_predicate, condition) =
        modeled_source_counter_threshold_static_predicate(abilities.first()?, source_subject)?;
    let condition_surface = source_counter_threshold_condition_surface(condition, source_subject)?;
    let mut predicates = vec![first_predicate];
    let mut consumed = 1usize;
    while let Some(ability) = abilities.get(consumed) {
        let Some((next_subject, predicate, next_condition)) =
            modeled_source_counter_threshold_static_predicate(ability, source_subject)
        else {
            break;
        };
        if next_subject != body_subject || next_condition != condition {
            break;
        }
        predicates.push(predicate);
        consumed += 1;
    }

    let predicate_surface = if predicates
        .iter()
        .all(|predicate| predicate.starts_with("has "))
    {
        let granted = predicates
            .iter()
            .map(|predicate| predicate.trim_start_matches("has ").to_string())
            .collect::<Vec<_>>();
        format!("has {}", join_english_list(&granted))
    } else {
        join_english_list(&predicates)
    };
    let body_subject = if body_subject == source_subject {
        "it"
    } else {
        body_subject.as_str()
    };
    Some((
        format!("As long as {condition_surface}, {body_subject} {predicate_surface}"),
        consumed,
    ))
}

/// Recombine the layer-correct static siblings emitted for a conditioned
/// source P/T modifier plus a keyword grant. The two executable payloads stay
/// independent; this only restores their single authored condition surface
/// after proving that the source, zone, and typed condition are identical.
fn describe_structural_conditioned_source_anthem_keyword_bundle(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let [anthem_ability, keyword_ability, ..] = abilities else {
        return None;
    };
    let (power, toughness, condition) = modeled_conditioned_source_anthem(anthem_ability)?;
    let (_, keyword, keyword_condition) = modeled_source_keyword_grant(keyword_ability)?;
    if keyword_condition != condition {
        return None;
    }

    let modifier = describe_fixed_anthem_modifier(power, toughness);
    let has_matching_must_attack = abilities.get(2).is_some_and(|ability| {
        modeled_direct_conditional_source_rule(
            ability,
            crate::static_abilities::StaticAbilityId::MustAttack,
        ) == Some(condition)
    });
    if has_matching_must_attack && let Some(condition) = delirium_condition_surface(condition) {
        return Some((
            format!(
                "Delirium — As long as {condition}, {subject} gets {modifier}, has {keyword}, and attacks each combat if able"
            ),
            3,
        ));
    }
    if let Some(label) = threshold_graveyard_presentation_label(condition) {
        if has_matching_must_attack {
            return Some((
                format!(
                    "{label} — As long as there are seven or more cards in your graveyard, {subject} gets {modifier}, has {keyword}, and attacks each combat if able"
                ),
                3,
            ));
        }
        return Some((
            format!(
                "{label} — As long as there are seven or more cards in your graveyard, {subject} gets {modifier} and has {keyword}"
            ),
            2,
        ));
    }
    if matches!(
        condition,
        Condition::ActivationTiming(crate::ability::ActivationTiming::DuringYourTurn)
    ) {
        return Some((
            format!("During your turn, {subject} gets {modifier} and has {keyword}"),
            2,
        ));
    }

    let prefix_surface = matches!(
        condition,
        Condition::Not(inner)
            if matches!(inner.as_ref(), Condition::PlayerCastSpellsThisTurnOrMore { .. })
    ) || matches!(
        condition,
        Condition::ValueComparison { left, .. }
            if matches!(left.unhinted(), Value::MaxDiceRolledThisTurn(_))
    );
    let condition = describe_condition(condition);
    let condition = condition
        .strip_prefix("this permanent")
        .map(|rest| format!("{}{rest}", lowercase_first(subject)))
        .unwrap_or(condition);
    let text = if prefix_surface {
        format!("As long as {condition}, {subject} gets {modifier} and has {keyword}")
    } else {
        format!("{subject} gets {modifier} and has {keyword} as long as {condition}")
    };
    Some((text, 2))
}

/// A lone source keyword grant gated on the seven-card graveyard condition
/// restores its authored ability-word surface: "Threshold — As long as there
/// are seven or more cards in your graveyard, this creature has flying."
fn describe_structural_threshold_source_keyword_grant(
    ability: &Ability,
    subject: &str,
) -> Option<String> {
    let (_, keyword, condition) = modeled_source_keyword_grant(ability)?;
    let label = threshold_graveyard_presentation_label(condition)?;
    Some(format!(
        "{label} — As long as there are seven or more cards in your graveyard, {subject} has {keyword}"
    ))
}

/// Recombine a labeled conditional source animation (type add + base P/T +
/// subtype) with its sibling keyword and activated grants under the same
/// condition: "Celebration — As long as ..., Goddric is a Dragon with base
/// power and toughness 4/4, flying, and \"...\"" (Goddric, Cloaked Reveler).
fn describe_structural_labeled_animation_grant_bundle(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let [
        types_ability,
        pt_ability,
        subtypes_ability,
        keyword_ability,
        granted_ability,
        ..,
    ] = abilities
    else {
        return None;
    };
    let AbilityKind::Static(types_static) = &types_ability.kind else {
        return None;
    };
    let types_model = types_static.compiled_model()?;
    let label = types_model.label.strip_prefix(
        ironsmith_core::static_ability_model::EXPLICIT_STATIC_PRESENTATION_LABEL_PREFIX,
    )?;
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: types_inner,
        condition,
    } = &types_model.payload
    else {
        return None;
    };
    if types_inner.id != Some(crate::static_abilities::StaticAbilityId::AddCardTypes) {
        return None;
    }

    let AbilityKind::Static(pt_static) = &pt_ability.kind else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: pt_inner,
        condition: pt_condition,
    } = &pt_static.compiled_model()?.payload
    else {
        return None;
    };
    if pt_condition != condition {
        return None;
    }
    let ironsmith_core::StaticAbilityPayload::SetBasePowerToughness {
        power, toughness, ..
    } = &pt_inner.payload
    else {
        return None;
    };

    let AbilityKind::Static(subtypes_static) = &subtypes_ability.kind else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: subtypes_inner,
        condition: subtypes_condition,
    } = &subtypes_static.compiled_model()?.payload
    else {
        return None;
    };
    if subtypes_condition != condition {
        return None;
    }
    let ironsmith_core::StaticAbilityPayload::SetCreatureSubtypes { subtypes, .. } =
        &subtypes_inner.payload
    else {
        return None;
    };
    let [subtype] = subtypes.as_slice() else {
        return None;
    };

    let (_, keyword, keyword_condition) = modeled_source_keyword_grant(keyword_ability)?;
    if keyword_condition != condition {
        return None;
    }

    let AbilityKind::Static(granted_static) = &granted_ability.kind else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) =
        &granted_static.compiled_model()?.payload
    else {
        return None;
    };
    if grant.condition.as_ref() != Some(condition)
        || grant.filter != ObjectFilter::source()
        || !matches!(
            &grant.ability.kind,
            ironsmith_core::AbilityKind::Activated(_)
        )
    {
        return None;
    }
    let granted = granted_static.source_granted_inline_abilities();
    let [granted] = granted.as_slice() else {
        return None;
    };
    let mut granted_text = describe_inline_ability_with_self_subject(granted, subject)
        .trim()
        .trim_end_matches('.')
        .to_string();
    if granted_text.is_empty() {
        return None;
    }
    if !granted_text.ends_with('!') && !granted_text.ends_with('?') {
        granted_text.push('.');
    }

    Some((
        format!(
            "{label} — As long as {}, {subject} is a {subtype:?} with base power and toughness {power}/{toughness}, {keyword}, and \"{granted_text}\"",
            describe_condition(condition)
        ),
        5,
    ))
}

/// Recombine a Threshold source P/T modifier with its sibling attack
/// requirement when both statics carry the same seven-card graveyard gate.
fn describe_structural_threshold_anthem_must_attack_bundle(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let [anthem_ability, attack_ability, ..] = abilities else {
        return None;
    };
    let (power, toughness, condition) = modeled_conditioned_source_anthem(anthem_ability)?;
    if modeled_direct_conditional_source_rule(
        attack_ability,
        crate::static_abilities::StaticAbilityId::MustAttack,
    ) != Some(condition)
    {
        return None;
    }
    let label = threshold_graveyard_presentation_label(condition)?;
    let modifier = describe_fixed_anthem_modifier(power, toughness);
    Some((
        format!(
            "{label} — As long as there are seven or more cards in your graveyard, {subject} gets {modifier} and attacks each combat if able"
        ),
        2,
    ))
}

/// Recombine a Threshold source color change with its sibling activated-ability
/// grant when both statics carry the same seven-card graveyard gate.
fn describe_structural_threshold_color_grant_bundle(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let [color_ability, grant_ability, ..] = abilities else {
        return None;
    };
    if color_ability.functional_zones.as_slice() != [Zone::Battlefield]
        || grant_ability.functional_zones != color_ability.functional_zones
    {
        return None;
    }
    let AbilityKind::Static(color_static) = &color_ability.kind else {
        return None;
    };
    let AbilityKind::Static(grant_static) = &grant_ability.kind else {
        return None;
    };
    let color_model = color_static.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: inner_color,
        condition,
    } = &color_model.payload
    else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::SetColors {
        filter: color_filter,
        colors,
    } = &inner_color.payload
    else {
        return None;
    };
    if inner_color.id != Some(crate::static_abilities::StaticAbilityId::SetColors) {
        return None;
    }
    let color_name = [
        crate::color::Color::White,
        crate::color::Color::Blue,
        crate::color::Color::Black,
        crate::color::Color::Red,
        crate::color::Color::Green,
    ]
    .into_iter()
    .find_map(|color| {
        (*colors == crate::color::ColorSet::from_color(color)).then(|| color.name())
    })?;
    let label = threshold_graveyard_presentation_label(condition)?;

    let grant_model = grant_static.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) =
        &grant_model.payload
    else {
        return None;
    };
    if color_filter != &grant.filter
        || grant.filter != ObjectFilter::source()
        || grant.condition.as_ref() != Some(condition)
        || !grant.additional_abilities.is_empty()
        || grant.set_quantifier_surface.is_some()
        || grant.ability.functional_zones.as_slice() != [Zone::Battlefield]
        || !matches!(
            &grant.ability.kind,
            ironsmith_core::AbilityKind::Activated(_)
        )
    {
        return None;
    }
    let granted = grant_static.source_granted_inline_abilities();
    let [granted] = granted.as_slice() else {
        return None;
    };
    if !matches!(&granted.kind, AbilityKind::Activated(_)) {
        return None;
    }
    let mut granted_text = describe_inline_ability_with_self_subject(granted, subject)
        .trim()
        .trim_end_matches('.')
        .to_string();
    if granted_text.is_empty() {
        return None;
    }
    if !granted_text.ends_with('!') && !granted_text.ends_with('?') {
        granted_text.push('.');
    }

    Some((
        format!(
            "{label} — As long as there are seven or more cards in your graveyard, {subject} is {color_name} and has \"{granted_text}\""
        ),
        2,
    ))
}

/// Recombine a layer-correct source animation and its granted annihilator
/// ability when all three executable static models carry the same condition.
/// The compiler intentionally keeps type addition, base P/T, and the granted
/// attack trigger independent; this restores their single authored surface
/// only after proving the source filter, condition, zone, and granted keyword.
fn describe_structural_conditioned_source_animation_annihilator_bundle(
    abilities: &[Ability],
) -> Option<(String, usize)> {
    let [type_ability, pt_ability, grant_ability, ..] = abilities else {
        return None;
    };
    if type_ability.functional_zones.as_slice() != [Zone::Battlefield]
        || pt_ability.functional_zones != type_ability.functional_zones
        || grant_ability.functional_zones != type_ability.functional_zones
    {
        return None;
    }

    let AbilityKind::Static(type_static) = &type_ability.kind else {
        return None;
    };
    let AbilityKind::Static(pt_static) = &pt_ability.kind else {
        return None;
    };
    let AbilityKind::Static(grant_static) = &grant_ability.kind else {
        return None;
    };
    if type_static.id() != crate::static_abilities::StaticAbilityId::AddCardTypes
        || pt_static.id()
            != crate::static_abilities::StaticAbilityId::SetBasePowerToughnessForFilter
        || grant_static.id()
            != crate::static_abilities::StaticAbilityId::GrantObjectAbilityForFilter
    {
        return None;
    }

    let (type_model, type_condition) = unwrapped_static_model(type_static)?;
    let (pt_model, pt_condition) = unwrapped_static_model(pt_static)?;
    let condition = type_condition?;
    if pt_condition != Some(condition) {
        return None;
    }
    let ironsmith_core::StaticAbilityPayload::AddCardTypes {
        filter: type_filter,
        card_types,
    } = &type_model.payload
    else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::SetBasePowerToughness {
        filter: pt_filter,
        power,
        toughness,
    } = &pt_model.payload
    else {
        return None;
    };
    if type_filter != &ObjectFilter::source() || pt_filter != type_filter || card_types.is_empty() {
        return None;
    }

    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) =
        &grant_static.compiled_model()?.payload
    else {
        return None;
    };
    if &grant.filter != type_filter
        || grant.condition.as_ref() != Some(condition)
        || !grant.additional_abilities.is_empty()
        || grant.set_quantifier_surface.is_some()
    {
        return None;
    }
    let granted = grant_static.source_granted_inline_abilities();
    let [granted] = granted.as_slice() else {
        return None;
    };
    let AbilityKind::Triggered(triggered) = &granted.kind else {
        return None;
    };
    let keyword = lowercase_first(&describe_annihilator_keyword(triggered)?);

    let type_phrase = card_types
        .iter()
        .map(|card_type| card_type.name().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(" ");
    // A numeric power/toughness prefix is adjectival here, so the generic
    // noun-phrase helper intentionally leaves it articleless. Animation
    // surfaces still require the authored "a 3/3 creature" form.
    let animated = format!("a {power}/{toughness} {type_phrase}");
    Some((
        format!(
            "As long as {}, it's {animated} in addition to its other types and it has {keyword}",
            describe_condition(condition),
        ),
        3,
    ))
}

fn threshold_graveyard_presentation_label(condition: &Condition) -> Option<&'static str> {
    // Threshold is an ability word with no rules meaning. This exact typed
    // gate is therefore safe presentation provenance without consulting a
    // card name, Oracle text, or a rendered condition string.
    matches!(
        condition,
        Condition::ValueComparison {
            left: Value::CardsInGraveyard(PlayerFilter::You),
            operator: ironsmith_core::ValueComparisonOperator::GreaterThanOrEqual,
            right: Value::Fixed(7),
        }
    )
    .then_some("Threshold")
}

/// Recombine the layer-correct static siblings emitted for a Threshold source
/// modifier. Every semantic fact is proven from compiled payloads: the source
/// gets exactly +1/+1, becomes black, and gains exactly one activated ability
/// under the same seven-card graveyard gate.
fn describe_structural_threshold_source_modifier_bundle(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let [anthem_ability, color_ability, grant_ability, ..] = abilities else {
        return None;
    };
    if anthem_ability.functional_zones.as_slice() != [Zone::Battlefield]
        || color_ability.functional_zones != anthem_ability.functional_zones
        || grant_ability.functional_zones != anthem_ability.functional_zones
    {
        return None;
    }

    let AbilityKind::Static(anthem_static) = &anthem_ability.kind else {
        return None;
    };
    let AbilityKind::Static(color_static) = &color_ability.kind else {
        return None;
    };
    let AbilityKind::Static(grant_static) = &grant_ability.kind else {
        return None;
    };
    if anthem_static.id() != crate::static_abilities::StaticAbilityId::Anthem
        || color_static.id() != crate::static_abilities::StaticAbilityId::SetColors
        || grant_static.id()
            != crate::static_abilities::StaticAbilityId::GrantObjectAbilityForFilter
    {
        return None;
    }

    let ironsmith_core::StaticAbilityPayload::Anthem(anthem) =
        &anthem_static.compiled_model()?.payload
    else {
        return None;
    };
    let (ironsmith_core::AnthemValue::Fixed(power), ironsmith_core::AnthemValue::Fixed(toughness)) =
        (&anthem.power, &anthem.toughness)
    else {
        return None;
    };
    if anthem.filter.is_some()
        || (*power, *toughness) != (1, 1)
        || anthem.set_quantifier_surface.is_some()
        || anthem.count_uses_where_x
        || anthem.additional_surface
        || anthem.replacement_surface.is_some()
    {
        return None;
    }
    let condition = anthem.condition.as_ref()?;
    let presentation_label = threshold_graveyard_presentation_label(condition)?;

    let color_model = color_static.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::Conditional {
        ability: inner_color,
        condition: color_condition,
    } = &color_model.payload
    else {
        return None;
    };
    let ironsmith_core::StaticAbilityPayload::SetColors {
        filter: color_filter,
        colors,
    } = &inner_color.payload
    else {
        return None;
    };
    if inner_color.id != Some(crate::static_abilities::StaticAbilityId::SetColors)
        || *colors != crate::color::ColorSet::BLACK
        || color_condition != condition
    {
        return None;
    }

    let grant_model = grant_static.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::GrantObjectAbilityForFilter(grant) =
        &grant_model.payload
    else {
        return None;
    };
    if color_filter != &grant.filter
        || grant.filter != ObjectFilter::source()
        || grant.condition.as_ref() != Some(condition)
        || !grant.additional_abilities.is_empty()
        || grant.set_quantifier_surface.is_some()
        || grant.ability.functional_zones.as_slice() != [Zone::Battlefield]
        || !matches!(
            &grant.ability.kind,
            ironsmith_core::AbilityKind::Activated(_)
        )
    {
        return None;
    }

    let granted = grant_static.source_granted_inline_abilities();
    let [granted] = granted.as_slice() else {
        return None;
    };
    if !matches!(&granted.kind, AbilityKind::Activated(_)) {
        return None;
    }
    let mut granted_text = describe_inline_ability_with_self_subject(granted, subject)
        .trim()
        .trim_end_matches('.')
        .to_string();
    if granted_text.is_empty() {
        return None;
    }
    if !granted_text.ends_with('!') && !granted_text.ends_with('?') {
        granted_text.push('.');
    }

    Some((
        format!(
            "{presentation_label} — As long as there are seven or more cards in your graveyard, {subject} gets +1/+1, is black, and has \"{granted_text}\""
        ),
        3,
    ))
}

fn modeled_keyword_count_condition(
    condition: &Condition,
    keyword: crate::static_abilities::StaticAbilityId,
) -> Option<(ObjectFilter, &str)> {
    let Condition::CountComparison {
        count: ironsmith_core::AnthemCountExpression::MatchingFilter(filter),
        comparison: Comparison::GreaterThanOrEqual(1),
        display: Some(display),
    } = condition
    else {
        return None;
    };
    if filter.static_abilities.as_slice() != [keyword]
        || !filter.excluded_static_abilities.is_empty()
        || !filter.ability_markers.is_empty()
        || !filter.excluded_ability_markers.is_empty()
    {
        return None;
    }
    let mut basis = filter.clone();
    basis.static_abilities.clear();
    Some((basis, display.trim()))
}

fn modeled_removed_draft_keyword_condition(
    condition: &Condition,
    keyword: crate::static_abilities::StaticAbilityId,
) -> Option<(PlayerFilter, ObjectFilter, &str)> {
    let Condition::PlayerRemovedDraftCardMatching {
        player,
        filter,
        with_cards_named,
    } = condition
    else {
        return None;
    };
    if filter.static_abilities.as_slice() != [keyword]
        || !filter.excluded_static_abilities.is_empty()
        || !filter.ability_markers.is_empty()
        || !filter.excluded_ability_markers.is_empty()
    {
        return None;
    }
    let mut basis = filter.clone();
    basis.static_abilities.clear();
    Some((player.clone(), basis, with_cards_named.trim()))
}

/// Render a structurally complete removed-from-draft keyword family using the
/// authored "The same is true" surface. Every grant remains independently
/// executable; this only rejoins adjacent grants proven to share provenance.
fn describe_structural_removed_draft_keyword_ladder(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let mut keywords = Vec::new();
    let mut shared_player = None;
    let mut shared_filter_basis: Option<ObjectFilter> = None;
    let mut shared_group_name: Option<String> = None;
    let mut first_condition = None;
    let mut consumed = 0usize;

    for ability in abilities {
        let Some((keyword_id, keyword, condition)) = modeled_source_keyword_grant(ability) else {
            break;
        };
        let Some((player, filter_basis, group_name)) =
            modeled_removed_draft_keyword_condition(condition, keyword_id)
        else {
            break;
        };
        if let Some(expected) = shared_player.as_ref() {
            if expected != &player {
                break;
            }
        } else {
            shared_player = Some(player.clone());
            shared_filter_basis = Some(filter_basis.clone());
            shared_group_name = Some(group_name.to_string());
            first_condition = Some(describe_condition(condition));
        }
        if shared_filter_basis.as_ref() != Some(&filter_basis)
            || shared_group_name.as_deref() != Some(group_name)
        {
            break;
        }
        keywords.push(keyword);
        consumed += 1;
    }

    if consumed < 3 {
        return None;
    }
    Some((
        format!(
            "If {}, {subject} has {}. The same is true for {}",
            first_condition?,
            keywords[0],
            render_keyword_list(&keywords[1..], false),
        ),
        consumed,
    ))
}

fn normalize_same_true_condition_statement(condition: &str, keyword: &str) -> String {
    let condition = condition.trim().trim_end_matches('.');
    if let Some(existence) = condition.strip_prefix("there is ") {
        let keyword_suffix = format!(" with {keyword}");
        if let Some(subject) = existence.strip_suffix(&keyword_suffix) {
            return format!("{subject} has {keyword}");
        }
        if let Some(subject) = existence.strip_suffix(" in a graveyard")
            && subject.ends_with(&keyword_suffix)
        {
            return format!("{subject} is in a graveyard");
        }
    }
    if let Some(subject) = condition.strip_prefix("your opponents control ") {
        return format!("an opponent controls {subject}");
    }
    condition.to_string()
}

/// Render a structurally complete family of source keyword grants whose
/// conditions differ only by requiring the same keyword on matching cards.
///
/// This is the executable shape behind "The same is true for ..." ladders.
/// Requiring one independent typed grant and one independent matching-filter
/// condition per keyword prevents a malformed, concatenated condition from
/// being made to look complete by the renderer.
fn describe_structural_keyword_same_is_true_ladder(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let mut keywords = Vec::new();
    let mut shared_condition_basis: Option<ObjectFilter> = None;
    let mut first_condition = None;
    let mut consumed = 0usize;

    for ability in abilities {
        let Some((keyword_id, keyword, condition)) = modeled_source_keyword_grant(ability) else {
            break;
        };
        let Some((condition_basis, condition_surface)) =
            modeled_keyword_count_condition(condition, keyword_id)
        else {
            break;
        };
        if let Some(shared) = &shared_condition_basis {
            if shared != &condition_basis {
                break;
            }
        } else {
            shared_condition_basis = Some(condition_basis);
            first_condition = Some(condition_surface.to_string());
        }
        keywords.push(keyword);
        consumed += 1;
    }

    if consumed < 3 {
        return None;
    }
    let first_keyword = &keywords[0];
    let condition =
        normalize_same_true_condition_statement(first_condition.as_deref()?, first_keyword);
    Some((
        format!(
            "As long as {condition}, {subject} has {first_keyword}. The same is true for {}",
            render_keyword_list(&keywords[1..], false),
        ),
        consumed,
    ))
}

fn modeled_all_subtypes_of_family_surface(
    ability: &Ability,
) -> Option<(&ObjectFilter, ironsmith_core::SubtypeFamily, String)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::AddAllSubtypesOfFamily { filter, family } =
        &model.payload
    else {
        return None;
    };
    let display = static_ability.display();
    let (subject, predicate, _) = split_static_predicate_with_verb(&display, &[" is ", " are "])?;
    if predicate != format!("every {}", family.type_phrase()) {
        return None;
    }
    Some((filter, *family, subject.to_string()))
}

fn owned_nonbattlefield_card_union_subject(filter: &ObjectFilter) -> Option<String> {
    ironsmith_core::filter_model::describe_owned_nonbattlefield_card_union(filter)
}

/// Rejoin the typed battlefield/spell/nonbattlefield-card scopes of a shared
/// all-subtypes grant. The three filters retain distinct runtime zones while
/// the identical subtype family proves the "same is true" relationship.
fn describe_structural_all_subtypes_scope_ladder(abilities: &[Ability]) -> Option<(String, usize)> {
    let [battlefield, stack, nonbattlefield, ..] = abilities else {
        return None;
    };
    let (battlefield_filter, family, battlefield_subject) =
        modeled_all_subtypes_of_family_surface(battlefield)?;
    let (stack_filter, stack_family, stack_subject) =
        modeled_all_subtypes_of_family_surface(stack)?;
    let (nonbattlefield_filter, nonbattlefield_family, _) =
        modeled_all_subtypes_of_family_surface(nonbattlefield)?;
    if family != stack_family
        || family != nonbattlefield_family
        || battlefield_filter.zone != Some(Zone::Battlefield)
        || battlefield_filter.controller != Some(PlayerFilter::You)
        || stack_filter.zone != Some(Zone::Stack)
        || stack_filter.controller != Some(PlayerFilter::You)
        || stack_filter.stack_kind != Some(crate::filter::StackObjectKind::Spell)
        || battlefield_filter.card_types != stack_filter.card_types
    {
        return None;
    }
    let nonbattlefield_subject = owned_nonbattlefield_card_union_subject(nonbattlefield_filter)?;
    let first = format!("{battlefield_subject} are every {}", family.type_phrase());
    Some((
        format!(
            "{first}. The same is true for {} and {}",
            lowercase_first(&stack_subject),
            lowercase_first(&nonbattlefield_subject),
        ),
        3,
    ))
}

#[cfg(test)]
mod all_subtypes_scope_ladder_tests {
    use super::*;

    #[test]
    fn battlefield_spell_and_owned_card_scopes_rejoin_with_same_is_true() {
        let oracle = "Creatures you control are every creature type. The same is true for creature spells you control and creature cards you own that aren't on the battlefield.";
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "All Subtypes Scope Probe",
        )
        .card_types(vec![CardType::Artifact])
        .parse_text(oracle)
        .expect("all-subtypes scope ladder should compile");

        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            vec![oracle.to_string()]
        );
    }
}

fn modeled_static_variant_copy(
    ability: &Ability,
) -> Option<&ironsmith_core::CopyStaticAbilityVariants> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    let ironsmith_core::StaticAbilityPayload::CopyStaticAbilityVariants(copy) = &model.payload
    else {
        return None;
    };
    Some(copy)
}

fn static_variant_selector_keyword(
    selector: ironsmith_core::StaticAbilityVariantSelector,
) -> Option<&'static str> {
    use crate::static_abilities::StaticAbilityId::*;
    use ironsmith_core::StaticAbilityVariantSelector::{Any, ProtectionFromColor};

    match selector {
        Any(Flying) => Some("flying"),
        Any(Fear) => Some("fear"),
        Any(FirstStrike) => Some("first strike"),
        Any(DoubleStrike) => Some("double strike"),
        Any(Deathtouch) => Some("deathtouch"),
        Any(Haste) => Some("haste"),
        Any(Landwalk) => Some("landwalk"),
        Any(Lifelink) => Some("lifelink"),
        Any(Protection) => Some("protection"),
        ProtectionFromColor => Some("protection from any color"),
        Any(Reach) => Some("reach"),
        Any(Trample) => Some("trample"),
        Any(Shroud) => Some("shroud"),
        Any(Vigilance) => Some("vigilance"),
        Any(Hexproof) | Any(HexproofFrom) => Some("hexproof"),
        Any(Indestructible) => Some("indestructible"),
        Any(Menace) => Some("menace"),
        Any(Shadow) => Some("shadow"),
        Any(Skulk) => Some("skulk"),
        _ => None,
    }
}

/// Rejoin a leading conditional keyword grant with the payload-preserving
/// variant-copy carrier for the remaining "The same is true" branches.
///
/// Delve-linked exile is executable provenance: the leading grant and every
/// copied variant must inspect the same source-exiled object filter, and the
/// source must actually have delve. This avoids collapsing unrelated keyword
/// grants that merely happen to be adjacent.
fn describe_structural_delve_keyword_variant_ladder(
    abilities: &[Ability],
    subject: &str,
    source_has_delve: bool,
) -> Option<(String, usize)> {
    if !source_has_delve {
        return None;
    }
    let [leading, variants, ..] = abilities else {
        return None;
    };
    let (leading_id, leading_keyword, condition) = modeled_source_keyword_grant(leading)?;
    let (condition_basis, _) = modeled_keyword_count_condition(condition, leading_id)?;
    let copy = modeled_static_variant_copy(variants)?;
    if !copy.exclude_source_id
        || copy.filter != condition_basis
        || !copy.filter.tagged_constraints.iter().any(|constraint| {
            constraint.tag.as_str() == crate::tag::SOURCE_EXILED_TAG
                && constraint.relation == crate::filter::TaggedOpbjectRelation::IsTaggedObject
        })
        || !copy
            .display
            .to_ascii_lowercase()
            .contains("the same is true for")
    {
        return None;
    }

    let mut trailing_keywords = Vec::new();
    for selector in &copy.selectors {
        let keyword = static_variant_selector_keyword(*selector)?.to_string();
        if keyword != leading_keyword && !trailing_keywords.contains(&keyword) {
            trailing_keywords.push(keyword);
        }
    }
    if trailing_keywords.len() < 2 {
        return None;
    }

    let mut noun_filter = copy.filter.clone();
    noun_filter.zone = None;
    noun_filter.tagged_constraints.retain(|constraint| {
        constraint.tag.as_str() != crate::tag::SOURCE_EXILED_TAG
            || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    });
    let noun_description = noun_filter.description();
    let noun = strip_leading_article(&noun_description);
    Some((
        format!(
            "If {} with {leading_keyword} was exiled with {subject}'s delve ability, {subject} has {leading_keyword}. The same is true for {}",
            with_indefinite_article(noun),
            render_keyword_list(&trailing_keywords, false),
        ),
        2,
    ))
}

fn modeled_basic_land_count_condition(condition: &Condition) -> Option<(Subtype, &str)> {
    let Condition::CountComparison {
        count: ironsmith_core::AnthemCountExpression::MatchingFilter(filter),
        comparison: Comparison::GreaterThanOrEqual(1),
        display: Some(display),
    } = condition
    else {
        return None;
    };
    let [subtype] = filter.subtypes.as_slice() else {
        return None;
    };
    if filter.controller != Some(PlayerFilter::You)
        || !matches!(
            subtype,
            Subtype::Plains
                | Subtype::Island
                | Subtype::Swamp
                | Subtype::Mountain
                | Subtype::Forest
        )
    {
        return None;
    }
    let mut basis = filter.clone();
    basis.controller = None;
    basis.subtypes.clear();
    if basis != ObjectFilter::default() {
        return None;
    }
    Some((*subtype, display.trim()))
}

fn modeled_basic_land_source_modifier(ability: &Ability) -> Option<(Subtype, String)> {
    if ability.functional_zones.as_slice() != [Zone::Battlefield] {
        return None;
    }
    let AbilityKind::Static(static_ability) = &ability.kind else {
        return None;
    };
    let model = static_ability.compiled_model()?;
    if let ironsmith_core::StaticAbilityPayload::Anthem(anthem) = &model.payload {
        if anthem.filter.is_some()
            || anthem.set_quantifier_surface.is_some()
            || anthem.count_uses_where_x
            || anthem.additional_surface
            || anthem.replacement_surface.is_some()
        {
            return None;
        }
        let (
            ironsmith_core::AnthemValue::Fixed(power),
            ironsmith_core::AnthemValue::Fixed(toughness),
        ) = (&anthem.power, &anthem.toughness)
        else {
            return None;
        };
        if *power == 0 && *toughness == 0 {
            return None;
        }
        let (subtype, condition) = modeled_basic_land_count_condition(anthem.condition.as_ref()?)?;
        return Some((
            subtype,
            format!("gets {power:+}/{toughness:+} as long as {condition}"),
        ));
    }

    let (_, keyword, condition) = modeled_source_keyword_grant(ability)?;
    let (subtype, condition) = modeled_basic_land_count_condition(condition)?;
    Some((subtype, format!("has {keyword} as long as {condition}")))
}

/// Combine the full five-basic-land source-modifier ladder while retaining
/// each independent typed condition and executable modifier.
fn describe_structural_five_basic_land_modifier_ladder(
    abilities: &[Ability],
    subject: &str,
) -> Option<(String, usize)> {
    let mut items = Vec::new();
    for ability in abilities.iter().take(6) {
        let Some(item) = modeled_basic_land_source_modifier(ability) else {
            break;
        };
        items.push(item);
    }
    if items.len() != 5 {
        return None;
    }
    for required in [
        Subtype::Plains,
        Subtype::Island,
        Subtype::Swamp,
        Subtype::Mountain,
        Subtype::Forest,
    ] {
        if items
            .iter()
            .filter(|(subtype, _)| *subtype == required)
            .count()
            != 1
        {
            return None;
        }
    }
    let predicates = items
        .iter()
        .map(|(_, predicate)| predicate.clone())
        .collect::<Vec<_>>();
    Some((
        format!(
            "{} {}",
            capitalize_first(subject),
            join_english_list(&predicates)
        ),
        5,
    ))
}

#[derive(Clone, Copy)]
enum CrossSegmentResultEffect<'a> {
    If(&'a crate::effects::IfEffect),
    Reflexive(&'a crate::effects::ReflexiveTriggerEffect),
    ForPlayers(&'a crate::effects::ForPlayersEffect),
}

fn cross_segment_result_effect(effect: &Effect) -> Option<CrossSegmentResultEffect<'_>> {
    if let Some(if_effect) = effect.downcast_ref::<crate::effects::IfEffect>() {
        return Some(CrossSegmentResultEffect::If(if_effect));
    }
    if let Some(reflexive) = effect.downcast_ref::<crate::effects::ReflexiveTriggerEffect>() {
        return Some(CrossSegmentResultEffect::Reflexive(reflexive));
    }
    if let Some(for_players) = effect.downcast_ref::<crate::effects::ForPlayersEffect>() {
        return Some(CrossSegmentResultEffect::ForPlayers(for_players));
    }
    effect
        .downcast_ref::<crate::effects::WithIdEffect>()?
        .effect
        .downcast_ref::<crate::effects::IfEffect>()
        .map(CrossSegmentResultEffect::If)
}

/// Rejoin an optional source transformation with the graveyard return that
/// follows it when authored sentence preservation placed the two instructions
/// in adjacent resolution segments. The established flat specialist validates
/// every sticker, Aura, choice-tag, return, and attachment relationship.
fn describe_cross_segment_optional_sticker_aura_return_attach_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [transform_segment, return_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !transform_segment.self_replacements.is_empty()
        || !return_segment.self_replacements.is_empty()
    {
        return None;
    }

    let [tag_triggering, may_transform] = transform_segment.default_effects.as_slice() else {
        return None;
    };
    tag_triggering.downcast_ref::<crate::effects::TagTriggeringObjectEffect>()?;
    may_transform.downcast_ref::<crate::effects::MayEffect>()?;

    let [return_sequence] = return_segment.default_effects.as_slice() else {
        return None;
    };
    let return_sequence = return_sequence.downcast_ref::<crate::effects::SequenceEffect>()?;
    if !matches!(
        return_sequence.surface,
        ironsmith_core::SequenceSurface::Coordinated
    ) {
        return None;
    }

    let mut effects = vec![tag_triggering, may_transform];
    effects.extend(return_sequence.effects.iter());
    let rendered = describe_optional_sticker_aura_return_attach_sequence(&effects)?;
    Some((rendered, 2))
}

/// Rejoin a returned permanent with the one-shot ETB watcher registered by
/// the following sentence. The structural matcher retains the exact result
/// tag and rejects broader delayed triggers, plural returns, and unrelated
/// payloads.
fn describe_cross_segment_return_then_linked_enter_return_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [return_segment, delayed_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !return_segment.self_replacements.is_empty()
        || !delayed_segment.self_replacements.is_empty()
        || return_segment.starts_new_source_line
        || delayed_segment.starts_new_source_line
    {
        return None;
    }
    let [return_effect] = return_segment.default_effects.as_slice() else {
        return None;
    };
    let [delayed_effect] = delayed_segment.default_effects.as_slice() else {
        return None;
    };
    describe_return_then_linked_enter_return_pair(return_effect, delayed_effect)
        .map(|rendered| (rendered, 2))
}

#[cfg(test)]
mod linked_return_enter_window_tests {
    use super::*;

    fn permanent_card_filter(owner: PlayerFilter, enters_under_controller: bool) -> ObjectFilter {
        let mut filter = ObjectFilter::default();
        filter.zone = Some(Zone::Graveyard);
        filter.owner = Some(owner);
        filter.card_types = vec![
            CardType::Artifact,
            CardType::Creature,
            CardType::Enchantment,
            CardType::Land,
            CardType::Planeswalker,
            CardType::Battle,
        ];
        filter.set_explicit_card_noun(true);
        filter.set_enters_under_controller_surface(enters_under_controller);
        filter
    }

    fn linked_return_segments(
        watched_tag: &str,
        enters_under_controller: bool,
        payload_count: ChoiceCount,
    ) -> Vec<crate::resolution::ResolutionSegment> {
        let returned_tag = crate::TagKey::from("returned_0");
        let returned = Effect::new(crate::effects::ReturnFromGraveyardToBattlefieldEffect::new(
            ChooseSpec::target(ChooseSpec::Object(permanent_card_filter(
                PlayerFilter::Opponent,
                enters_under_controller,
            ))),
            false,
        ))
        .tag(returned_tag.clone());

        let mut payload_filter = permanent_card_filter(PlayerFilter::You, false);
        payload_filter
            .tagged_constraints
            .push(crate::filter::TaggedObjectConstraint {
                tag: returned_tag,
                relation: crate::filter::TaggedOpbjectRelation::ManaValueLteTagged,
            });
        let payload = Effect::new(crate::effects::ReturnFromGraveyardToBattlefieldEffect::new(
            ChooseSpec::target(ChooseSpec::Object(payload_filter)).with_count(payload_count),
            false,
        ))
        .tag("returned_1");
        let trigger = crate::triggers::Trigger::new(
            crate::triggers::ZoneChangeTrigger::new()
                .to(Zone::Battlefield)
                .this()
                .this_surface(crate::target::SourceReferenceSurface::ThisPermanentType(
                    "that permanent".to_string(),
                ))
                .this_subject_number(ironsmith_core::trigger_model::TriggerSubjectNumber::Singular),
        );
        let mut delayed = crate::effects::ScheduleDelayedTriggerEffect::from_tag(
            trigger,
            vec![payload],
            true,
            watched_tag,
            PlayerFilter::You,
        );
        delayed.leading_duration_surface = true;

        vec![
            crate::resolution::ResolutionSegment::from_effects(vec![returned]),
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::new(delayed)]),
        ]
    }

    #[test]
    fn exact_linked_return_window_restores_authored_etb_sentence() {
        let segments = linked_return_segments("returned_0", true, ChoiceCount::up_to(1));
        assert_eq!(
            describe_cross_segment_return_then_linked_enter_return_window(&segments, 0),
            Some((
                "Return target permanent card in an opponent's graveyard to the battlefield under their control. When that permanent enters, return up to one target permanent card with equal or lesser mana value from your graveyard to the battlefield".to_string(),
                2,
            ))
        );
        assert_eq!(
            describe_resolution_program(&crate::resolution::ResolutionProgram::new(segments)),
            "Return target permanent card in an opponent's graveyard to the battlefield under their control. When that permanent enters, return up to one target permanent card with equal or lesser mana value from your graveyard to the battlefield"
        );
    }

    #[test]
    fn linked_return_window_rejects_provenance_surface_and_cardinality_near_misses() {
        for segments in [
            linked_return_segments("other_return", true, ChoiceCount::up_to(1)),
            linked_return_segments("returned_0", false, ChoiceCount::up_to(1)),
            linked_return_segments("returned_0", true, ChoiceCount::exactly(1)),
        ] {
            assert_eq!(
                describe_cross_segment_return_then_linked_enter_return_window(&segments, 0),
                None
            );
        }
    }
}

/// Rejoin an authored player choice and its immediately linked action when
/// lowering preserves their sentence boundary as adjacent resolution
/// segments. The structural helper still verifies that the action's actor is
/// the exact player tag produced by the choice.
fn describe_cross_segment_distinct_player_choice_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [choice_segment, action_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !choice_segment.self_replacements.is_empty() || !action_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [choice] = choice_segment.default_effects.as_slice() else {
        return None;
    };
    let [action] = action_segment.default_effects.as_slice() else {
        return None;
    };
    let effects = [choice.clone(), action.clone()];
    describe_distinct_player_choice_with_linked_action(&effects).map(|rendered| (rendered, 2))
}

/// Preserve the authored sentence boundary for a random choice from the
/// source's persistent exile pool followed by the linked owner-hand move.
///
/// The ordinary flat choice/move renderer is intentionally broader and
/// conjoins these effects. This matcher accepts only an exact random-one
/// `SOURCE_EXILED_TAG` selection and a bare move of that same choice tag to
/// its owner's hand, so unrelated two-step choices keep their canonical
/// rendering.
fn describe_cross_segment_random_source_exiled_owner_hand_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [choice_segment, move_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !choice_segment.self_replacements.is_empty() || !move_segment.self_replacements.is_empty() {
        return None;
    }
    let [choice_effect] = choice_segment.default_effects.as_slice() else {
        return None;
    };
    let [move_effect] = move_segment.default_effects.as_slice() else {
        return None;
    };
    let choose = choice_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let move_to_hand = move_effect.downcast_ref::<crate::effects::MoveToZoneEffect>()?;

    let mut expected_filter = ObjectFilter::default().in_zone(Zone::Exile);
    expected_filter.set_explicit_card_noun(true);
    expected_filter
        .tagged_constraints
        .push(crate::filter::TaggedObjectConstraint {
            tag: crate::tag::SOURCE_EXILED_TAG.into(),
            relation: crate::filter::TaggedOpbjectRelation::IsTaggedObject,
        });
    let mut expected_choose = crate::effects::ChooseObjectsEffect::new(
        expected_filter,
        ChoiceCount::exactly(1),
        PlayerFilter::You,
        choose.tag.clone(),
    )
    .in_zone(Zone::Exile);
    expected_choose.count.random = true;
    if choose != &expected_choose {
        return None;
    }

    let expected_move = crate::effects::MoveToZoneEffect::new(
        ChooseSpec::Tagged(choose.tag.clone()),
        Zone::Hand,
        false,
    )
    .with_verb_surface(ironsmith_core::MoveToZoneVerbSurface::Put);
    if move_to_hand != &expected_move {
        return None;
    }

    Some((
        format!(
            "Choose a card at random that was {}. Put that card into its owner's hand",
            crate::compiled_text::source_exiled_with_phrase(&choose.filter),
        ),
        2,
    ))
}

#[cfg(test)]
mod random_source_exiled_owner_hand_window_tests {
    use super::*;

    fn matching_segments() -> Vec<crate::resolution::ResolutionSegment> {
        let mut filter = ObjectFilter::default().in_zone(Zone::Exile);
        filter.set_explicit_card_noun(true);
        filter
            .tagged_constraints
            .push(crate::filter::TaggedObjectConstraint {
                tag: crate::tag::SOURCE_EXILED_TAG.into(),
                relation: crate::filter::TaggedOpbjectRelation::IsTaggedObject,
            });
        let mut count = ChoiceCount::exactly(1);
        count.random = true;
        let choose = crate::effects::ChooseObjectsEffect::new(
            filter,
            count,
            PlayerFilter::You,
            "skyship_choice",
        )
        .in_zone(Zone::Exile);
        let move_to_hand = crate::effects::MoveToZoneEffect::new(
            ChooseSpec::Tagged(TagKey::from("skyship_choice")),
            Zone::Hand,
            false,
        )
        .with_verb_surface(ironsmith_core::MoveToZoneVerbSurface::Put);
        vec![
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::new(choose)]),
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::new(move_to_hand)]),
        ]
    }

    #[test]
    fn random_source_exiled_choice_keeps_owner_hand_as_a_new_sentence() {
        let segments = matching_segments();
        assert_eq!(
            describe_cross_segment_random_source_exiled_owner_hand_window(&segments, 0),
            Some((
                "Choose a card at random that was exiled with this source. Put that card into its owner's hand"
                    .to_string(),
                2,
            )),
        );

        let program = crate::resolution::ResolutionProgram::new(segments);
        assert_eq!(
            describe_resolution_program(&program),
            "Choose a card at random that was exiled with this source. Put that card into its owner's hand"
        );
    }

    #[test]
    fn nonrandom_or_mismatched_choices_do_not_use_the_specialist() {
        let mut nonrandom = matching_segments();
        let choose = nonrandom[0].default_effects[0]
            .downcast_ref::<crate::effects::ChooseObjectsEffect>()
            .expect("choice effect")
            .clone();
        let mut choose = choose;
        choose.count.random = false;
        nonrandom[0].default_effects[0] = Effect::new(choose);
        assert_eq!(
            describe_cross_segment_random_source_exiled_owner_hand_window(&nonrandom, 0),
            None,
        );

        let mut mismatched = matching_segments();
        mismatched[1].default_effects[0] = Effect::new(
            crate::effects::MoveToZoneEffect::new(
                ChooseSpec::Tagged(TagKey::from("other_choice")),
                Zone::Hand,
                false,
            )
            .with_verb_surface(ironsmith_core::MoveToZoneVerbSurface::Put),
        );
        assert_eq!(
            describe_cross_segment_random_source_exiled_owner_hand_window(&mismatched, 0),
            None,
        );
    }

    #[test]
    fn parsed_source_linked_choice_keeps_typed_program_and_exact_surface() {
        let oracle = "When Skyship Weatherlight enters, search your library for any number of artifact and/or creature cards, exile them, then shuffle.\n{4}, {T}: Choose a card at random that was exiled with Skyship Weatherlight. Put that card into its owner's hand.";
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Skyship Weatherlight",
        )
        .supertypes(vec![Supertype::Legendary])
        .card_types(vec![CardType::Artifact])
        .parse_text(oracle)
        .expect("source-linked random exile choice should compile");
        let activated = definition
            .abilities
            .iter()
            .find_map(|ability| match &ability.kind {
                AbilityKind::Activated(activated) => Some(activated),
                _ => None,
            })
            .expect("activated ability");
        let [choose_segment, move_segment] = activated.effects.segments.as_slice() else {
            panic!("expected the authored two-sentence program");
        };
        let [choose_effect] = choose_segment.default_effects.as_slice() else {
            panic!("expected one choice effect");
        };
        let choose = choose_effect
            .downcast_ref::<crate::effects::ChooseObjectsEffect>()
            .expect("typed choice effect");
        assert!(choose.count.random);
        assert_eq!(choose.count.min, 1);
        assert_eq!(choose.count.max, Some(1));
        assert!(choose.filter.tagged_constraints.iter().any(|constraint| {
            constraint.tag.as_str() == crate::tag::SOURCE_EXILED_TAG
                && constraint.relation == crate::filter::TaggedOpbjectRelation::IsTaggedObject
        }));
        let [move_effect] = move_segment.default_effects.as_slice() else {
            panic!("expected one owner-hand move");
        };
        let move_to_hand = move_effect
            .downcast_ref::<crate::effects::MoveToZoneEffect>()
            .expect("typed move effect");
        assert!(matches!(
            move_to_hand.target.base(),
            ChooseSpec::Tagged(tag) if tag == &choose.tag
        ));
        assert_eq!(move_to_hand.zone, Zone::Hand);

        let rendered = crate::compiled_text::compiled_text_lines(&definition);
        assert_eq!(
            rendered.last().map(String::as_str),
            Some(
                "{4}, {T}: Choose a card at random that was exiled with Skyship Weatherlight. Put that card into its owner's hand."
            )
        );
    }
}

/// Rejoin a per-opponent bottom-library exile with its following persistent
/// look/cast permission when authored sentence preservation split the two
/// clauses into adjacent resolution segments. The established flat matcher
/// remains the semantic authority for the exact player, tag, zone, duration,
/// permanent-spell filter, face-down, and mana-spend relationships.
fn describe_cross_segment_bottom_library_exile_look_cast_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [exile_segment, permission_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !exile_segment.self_replacements.is_empty()
        || !permission_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [for_players_effect] = exile_segment.default_effects.as_slice() else {
        return None;
    };
    let [look_effect, grant_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    let for_players = for_players_effect.downcast_ref::<crate::effects::ForPlayersEffect>()?;
    let look = look_effect.downcast_ref::<crate::effects::LookAtObjectsEffect>()?;
    let grant = grant_effect.downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    describe_for_players_bottom_library_exile_then_look_cast(for_players, look, grant)
        .map(|rendered| (rendered, 2))
}

#[cfg(test)]
mod bottom_library_exile_look_cast_window_tests {
    use super::*;

    fn segments_with_tags(
        collection_tag: TagKey,
        permission_tag: TagKey,
    ) -> Vec<crate::resolution::ResolutionSegment> {
        let library_filter = ObjectFilter::default().in_zone(Zone::Library);
        let choose = crate::effects::ChooseObjectsEffect::new(
            library_filter,
            ChoiceCount::exactly(1),
            PlayerFilter::IteratedPlayer,
            collection_tag.clone(),
        )
        .in_zone(Zone::Library)
        .bottom_only();
        let exile = Effect::new(
            crate::effects::ExileEffect::with_spec(ChooseSpec::Tagged(collection_tag.clone()))
                .with_face_down(true),
        )
        .tag(collection_tag.clone());
        let for_players = Effect::new(crate::effects::ForPlayersEffect::new(
            PlayerFilter::Opponent,
            vec![Effect::new(choose), exile],
        ));

        let look_filter = ObjectFilter::default()
            .in_zone(Zone::Exile)
            .controlled_by(PlayerFilter::You)
            .match_tagged(
                collection_tag,
                crate::filter::TaggedOpbjectRelation::IsTaggedObject,
            );
        let look = Effect::new(crate::effects::LookAtObjectsEffect::new(
            look_filter,
            PlayerFilter::You,
            PlayerFilter::You,
        ));
        let mut permanent_spells = ObjectFilter::default();
        permanent_spells.card_types = vec![
            CardType::Artifact,
            CardType::Creature,
            CardType::Enchantment,
            CardType::Planeswalker,
            CardType::Battle,
        ];
        let grant = Effect::new(
            crate::effects::GrantPlayTaggedEffect::new(
                permission_tag,
                PlayerFilter::You,
                crate::effects::GrantPlayTaggedDuration::ForAsLongAsExiled,
                false,
                true,
            )
            .with_filter(permanent_spells),
        );

        vec![
            crate::resolution::ResolutionSegment::from_effects(vec![for_players]),
            crate::resolution::ResolutionSegment::from_effects(vec![look, grant]),
        ]
    }

    #[test]
    fn rejoins_exact_bottom_library_collection_and_plural_permission() {
        let tag = TagKey::from("exiled_collection");
        let segments = segments_with_tags(tag.clone(), tag);

        assert_eq!(
            describe_cross_segment_bottom_library_exile_look_cast_window(&segments, 0),
            Some((
                "Exile the bottom card of each opponent's library face down. For as long as those cards remain exiled, you may look at them, you may cast permanent spells from among them, and you may spend mana as though it were mana of any color to cast those spells".to_string(),
                2,
            ))
        );
        let program = crate::resolution::ResolutionProgram::new(segments);
        assert_eq!(
            describe_resolution_program(&program),
            "Exile the bottom card of each opponent's library face down. For as long as those cards remain exiled, you may look at them, you may cast permanent spells from among them, and you may spend mana as though it were mana of any color to cast those spells"
        );
    }

    #[test]
    fn rejects_mismatched_permission_tag_and_replacement_bearing_window() {
        let collection_tag = TagKey::from("exiled_collection");
        let wrong_tag = TagKey::from("unrelated_collection");
        let mismatched = segments_with_tags(collection_tag.clone(), wrong_tag);
        assert_eq!(
            describe_cross_segment_bottom_library_exile_look_cast_window(&mismatched, 0),
            None
        );

        let mut replacement_bearing = segments_with_tags(collection_tag.clone(), collection_tag);
        replacement_bearing[1].self_replacements.push(
            crate::resolution::SelfReplacementBranch::new(Condition::YourTurn, Vec::new()),
        );
        assert_eq!(
            describe_cross_segment_bottom_library_exile_look_cast_window(&replacement_bearing, 0,),
            None
        );
    }
}

fn describe_cross_segment_look_optional_payment_disposition_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let first_segment = segments.get(start)?;
    if !first_segment.self_replacements.is_empty() {
        return None;
    }
    let (look_effect, payment_effect, accepted_effect, declined_effect, consumed) = if let [
        look_effect,
        payment_effect,
        accepted_effect,
        declined_effect,
    ] =
        first_segment.default_effects.as_slice()
    {
        (
            look_effect,
            payment_effect,
            accepted_effect,
            declined_effect,
            1,
        )
    } else {
        let [
            look_segment,
            payment_segment,
            accepted_segment,
            declined_segment,
        ] = segments.get(start..start + 4)?
        else {
            return None;
        };
        if [
            look_segment,
            payment_segment,
            accepted_segment,
            declined_segment,
        ]
        .iter()
        .any(|segment| !segment.self_replacements.is_empty())
        {
            return None;
        }
        let [look_effect] = look_segment.default_effects.as_slice() else {
            return None;
        };
        let [payment_effect] = payment_segment.default_effects.as_slice() else {
            return None;
        };
        let [accepted_effect] = accepted_segment.default_effects.as_slice() else {
            return None;
        };
        let [declined_effect] = declined_segment.default_effects.as_slice() else {
            return None;
        };
        (
            look_effect,
            payment_effect,
            accepted_effect,
            declined_effect,
            4,
        )
    };

    let look = unwrap_basic_render_wrapper(look_effect)
        .downcast_ref::<crate::effects::LookAtTopCardsEffect>()?;
    if look.player != PlayerFilter::You
        || look.reveal
        || !matches!(look.count.unhinted(), Value::Fixed(count) if *count >= 2)
    {
        return None;
    }

    let payment_with_id = payment_effect.downcast_ref::<crate::effects::WithIdEffect>()?;
    let may = payment_with_id
        .effect
        .downcast_ref::<crate::effects::MayEffect>()?;
    if may.fallback != crate::decision::FallbackStrategy::Decline
        || !matches!(may.decider.as_ref(), None | Some(PlayerFilter::You))
    {
        return None;
    }

    fn result_if(effect: &Effect) -> Option<&crate::effects::IfEffect> {
        unwrap_basic_render_wrapper(effect).downcast_ref::<crate::effects::IfEffect>()
    }

    let accepted = result_if(accepted_effect)?;
    let declined = result_if(declined_effect)?;
    if accepted.condition != payment_with_id.id
        || declined.condition != payment_with_id.id
        || accepted.predicate != EffectPredicate::Happened
        || !matches!(
            declined.predicate,
            EffectPredicate::DidNotHappen | EffectPredicate::WasDeclined
        )
        || !accepted.else_.is_empty()
        || !declined.else_.is_empty()
    {
        return None;
    }

    fn exact_one_looked_move<'a>(
        effects: &'a [Effect],
        looked_tag: &TagKey,
        zone: Zone,
    ) -> Option<&'a crate::effects::MoveToZoneEffect> {
        let [effect] = effects else {
            return None;
        };
        let move_to_zone = unwrap_basic_render_wrapper(effect)
            .downcast_ref::<crate::effects::MoveToZoneEffect>()?;
        let ChooseSpec::WithCount(target, count) = move_to_zone.target.unhinted() else {
            return None;
        };
        (move_to_zone.zone == zone
            && !move_to_zone.to_top
            && *count == ChoiceCount::exactly(1)
            && matches!(target.base(), ChooseSpec::Tagged(tag) if tag == looked_tag)
            && matches!(
                move_to_zone.actor_surface.as_ref(),
                None | Some(PlayerFilter::You)
            )
            && matches!(
                move_to_zone.destination_player_surface.as_ref(),
                None | Some(PlayerFilter::You)
            ))
        .then_some(move_to_zone)
    }

    exact_one_looked_move(&accepted.then, &look.tag, Zone::Hand)?;
    exact_one_looked_move(&declined.then, &look.tag, Zone::Library)?;

    let look_text = capitalize_first(describe_effect(look_effect).trim().trim_end_matches('.'));
    let payment_text =
        capitalize_first(describe_effect(payment_effect).trim().trim_end_matches('.'));
    Some((
        format!(
            "{look_text}. {payment_text}. If you do, put one of those cards into your hand. If you don't, put one of those cards on the bottom of your library"
        ),
        consumed,
    ))
}

/// Rejoin a will-of-the-council vote with its option conditionals when
/// sentence lowering placed each result sentence in its own resolution
/// segment. The named-vote helper still proves every option/condition edge.
fn describe_cross_segment_named_vote_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let first = segments.get(start)?;
    if !first.self_replacements.is_empty() {
        return None;
    }
    let [vote_effect] = first.default_effects.as_slice() else {
        return None;
    };
    vote_effect.downcast_ref::<crate::effects::VoteEffect>()?;

    let mut effects: Vec<&Effect> = vec![vote_effect];
    let mut end = start + 1;
    while let Some(segment) = segments.get(end) {
        if !segment.self_replacements.is_empty() || segment.default_effects.is_empty() {
            break;
        }
        let all_vote_conditionals = segment.default_effects.iter().all(|effect| {
            effect
                .downcast_ref::<crate::effects::ConditionalEffect>()
                .is_some_and(|conditional| {
                    matches!(
                        &conditional.condition,
                        Condition::VoteOptionGetsMoreVotes(_)
                            | Condition::VoteOptionGetsMoreVotesOrTied(_)
                    )
                })
        });
        if !all_vote_conditionals {
            break;
        }
        effects.extend(segment.default_effects.iter());
        end += 1;
    }
    if end == start + 1 {
        return None;
    }
    let rendered =
        crate::compiled_text::render_effects::describe_planeswalk_chaos_vote_sequence(&effects)
            .or_else(|| {
                crate::compiled_text::render_effects::describe_named_vote_conditional_sequence(
                    &effects,
                )
            })?;
    Some((rendered, end - start))
}

/// Rejoin an authored discard-hand/add-mana/draw sequence when sentence
/// lowering preserved its result references but split the actions into
/// adjacent resolution segments.
fn describe_cross_segment_discard_hand_add_mana_draw_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    // Sentence preservation can keep the authored mana-and-draw clause as a
    // two-child sequence in the segment after the discard. Flatten only that
    // proven shape: continuing the generic three-effect scan would otherwise
    // pull the following vote into this window without ever exposing the
    // sequence's children to the typed renderer.
    if let [discard_segment, mana_draw_segment] = segments.get(start..start + 2)?
        && discard_segment.self_replacements.is_empty()
        && mana_draw_segment.self_replacements.is_empty()
        && let [discard_effect] = discard_segment.default_effects.as_slice()
        && let [sequence_effect] = mana_draw_segment.default_effects.as_slice()
        && let Some(sequence) = sequence_effect.downcast_ref::<crate::effects::SequenceEffect>()
        && let [mana_effect, draw_effect] = sequence.effects.as_slice()
    {
        let effects = [discard_effect, mana_effect, draw_effect];
        if let Some(rendered) =
            crate::compiled_text::render_effects::describe_discard_hand_add_mana_draw_sequence(
                &effects,
            )
        {
            return Some((rendered, 2));
        }
    }

    let mut effects = Vec::with_capacity(3);
    let mut end = start;
    while effects.len() < 3 {
        let segment = segments.get(end)?;
        if !segment.self_replacements.is_empty()
            || segment.default_effects.is_empty()
            || effects.len() + segment.default_effects.len() > 3
        {
            return None;
        }
        effects.extend(segment.default_effects.iter());
        end += 1;
    }
    if end == start + 1 {
        return None;
    }
    let rendered =
        crate::compiled_text::render_effects::describe_discard_hand_add_mana_draw_sequence(
            &effects,
        )?;
    Some((rendered, end - start))
}

fn describe_cross_segment_roll_choose_destroy_create_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [roll_segment, destroy_segment, create_segment] = segments.get(start..start + 3)? else {
        return None;
    };
    if [roll_segment, destroy_segment, create_segment]
        .iter()
        .any(|segment| !segment.self_replacements.is_empty())
    {
        return None;
    }
    let [roll_effect] = roll_segment.default_effects.as_slice() else {
        return None;
    };
    let [destroy_effect] = destroy_segment.default_effects.as_slice() else {
        return None;
    };
    let [create_effect] = create_segment.default_effects.as_slice() else {
        return None;
    };
    let create_effect = create_effect
        .downcast_ref::<crate::effects::SequenceEffect>()
        .and_then(|sequence| {
            let [only] = sequence.effects.as_slice() else {
                return None;
            };
            Some(only)
        })
        .unwrap_or(create_effect);
    let effects = [
        roll_effect.clone(),
        destroy_effect.clone(),
        create_effect.clone(),
    ];
    describe_roll_choose_destroy_create_structural(&effects).map(|rendered| (rendered, 3))
}

fn describe_cross_segment_secret_choice_match_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let choice_segment = segments.get(start)?;
    if !choice_segment.self_replacements.is_empty() {
        return None;
    }
    let (choice_effect, conditional_effect, consumed) =
        if let [choice_effect, conditional_effect] = choice_segment.default_effects.as_slice() {
            (choice_effect, conditional_effect, 1)
        } else {
            let conditional_segment = segments.get(start + 1)?;
            if !conditional_segment.self_replacements.is_empty() {
                return None;
            }
            let [choice_effect] = choice_segment.default_effects.as_slice() else {
                return None;
            };
            let [conditional_effect] = conditional_segment.default_effects.as_slice() else {
                return None;
            };
            (choice_effect, conditional_effect, 2)
        };
    let effects = [choice_effect.clone(), conditional_effect.clone()];
    describe_secret_choice_match_sequence(&effects).map(|rendered| (rendered, consumed))
}

fn unwrap_singleton_sentence_boundary(effect: &Effect) -> Option<&Effect> {
    let sequence = effect.downcast_ref::<crate::effects::SequenceEffect>()?;
    if sequence.surface != ironsmith_core::SequenceSurface::SentenceLeadingThen {
        return None;
    }
    let [effect] = sequence.effects.as_slice() else {
        return None;
    };
    Some(effect)
}

