#[cfg(test)]
mod graveyard_exile_copy_cast_window_tests {
    use super::*;

    fn segments(
        exile_tag: &TagKey,
        cast_tag: &TagKey,
    ) -> Vec<crate::resolution::ResolutionSegment> {
        let mut filter = ObjectFilter::default().in_zone(Zone::Graveyard);
        filter.card_types = vec![CardType::Instant, CardType::Sorcery];
        let exile = Effect::new(crate::effects::ExileEffect::target(ChooseSpec::Object(
            filter,
        )))
        .tag(exile_tag.clone());
        let cast = Effect::new(
            crate::effects::CastTaggedEffect::new(cast_tag.clone(), PlayerFilter::You)
                .without_paying_mana_cost()
                .as_copy(),
        );
        let may_cast = Effect::new(crate::effects::MayEffect::new(vec![cast]));
        vec![
            crate::resolution::ResolutionSegment::from_effects(vec![
                Effect::new(crate::effects::TagTriggeringObjectEffect::new("triggering")),
                exile,
            ]),
            crate::resolution::ResolutionSegment::from_effects(vec![may_cast]),
        ]
    }

    #[test]
    fn graveyard_exile_copy_cast_window_requires_shared_exile_provenance() {
        let exile_tag = TagKey::from("__sentence_helper_exiled_l0_s0_e40");
        let matching = segments(&exile_tag, &exile_tag);
        assert_eq!(
            describe_cross_segment_graveyard_exile_copy_cast_window(&matching, 0),
            Some((
                "Exile target instant or sorcery card from a graveyard and copy it. You may cast the copy without paying its mana cost".to_string(),
                2,
            ))
        );

        let unrelated = TagKey::from("__sentence_helper_exiled_l0_s41_e80");
        assert_eq!(
            describe_cross_segment_graveyard_exile_copy_cast_window(
                &segments(&exile_tag, &unrelated),
                0,
            ),
            None,
            "an unrelated copy-cast permission must not fold into the graveyard exile"
        );
    }

    #[test]
    fn public_attack_route_keeps_prowess_and_one_copy_clause() {
        let oracle = "Creatures you control have prowess.\nWhenever Narset attacks, exile target noncreature, nonland card with mana value less than Narset's power from a graveyard and copy it. You may cast the copy without paying its mana cost.";
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Narset, Enlightened Exile",
        )
        .card_types(vec![CardType::Creature])
        .power_toughness(crate::card::PowerToughness::fixed(3, 4))
        .parse_text(oracle)
        .expect("prowess grant and graveyard copy/cast trigger should parse");

        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            oracle.lines().map(str::to_string).collect::<Vec<_>>()
        );
    }

    #[test]
    fn public_crime_trigger_keeps_copy_cast_and_if_you_do_in_one_semantic_program() {
        let oracle = "Whenever you commit a crime, exile up to one target black card from your graveyard and copy it. You may cast the copy. If you do, you lose 2 life.";
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Crime Copy-Cast Probe",
        )
        .card_types(vec![CardType::Creature])
        .power_toughness(crate::card::PowerToughness::fixed(3, 3))
        .parse_text(oracle)
        .expect("crime-triggered graveyard copy/cast sequence should parse");

        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition),
            [oracle]
        );
        let debug = format!("{:#?}", definition.abilities);
        assert_eq!(debug.matches("CopySpellEffect").count(), 0, "{debug}");
        assert!(
            debug.contains("CastTaggedEffect") && debug.contains("as_copy: true"),
            "{debug}"
        );
        assert!(
            debug.contains("IfEffect") && debug.contains("LoseLifeEffect"),
            "{debug}"
        );
    }

    #[test]
    fn result_window_requires_the_optional_cast_result_id() {
        let exile_tag = TagKey::from("__sentence_helper_exiled_l0_s0_e40");
        let mut fixture = segments(&exile_tag, &exile_tag);
        let may = fixture[1].default_effects[0].clone();
        fixture[1].default_effects[0] = Effect::with_id(7, may);
        fixture.push(crate::resolution::ResolutionSegment::from_effects(vec![
            Effect::if_then(
                crate::effect::EffectId(7),
                crate::effect::EffectPredicate::Happened,
                vec![Effect::lose_life(2)],
            ),
        ]));
        assert_eq!(
            describe_cross_segment_graveyard_exile_copy_cast_result_window(&fixture, 0),
            Some((
                "Exile target instant or sorcery card from a graveyard and copy it. You may cast the copy without paying its mana cost. If you do, you lose 2 life"
                    .to_string(),
                3,
            ))
        );

        let wrong = Effect::if_then(
            crate::effect::EffectId(8),
            crate::effect::EffectPredicate::Happened,
            vec![Effect::lose_life(2)],
        );
        fixture[2].default_effects[0] = wrong;
        assert_eq!(
            describe_cross_segment_graveyard_exile_copy_cast_result_window(&fixture, 0),
            None
        );
    }
}

fn describe_cross_segment_observation_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let mut effects = Vec::new();
    for segment in segments[start..].iter().take(5) {
        if !segment.self_replacements.is_empty() {
            break;
        }
        let [effect] = segment.default_effects.as_slice() else {
            break;
        };
        effects.push(effect);
    }
    if effects.len() < 2 {
        return None;
    }
    let (rendered, consumed) = describe_immediate_observation_conditionals(&effects)?;
    (consumed >= 2 && consumed <= effects.len()).then_some((rendered, consumed))
}

fn describe_cross_segment_wrapped_search_two_split_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [partition_segment, suffix_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !partition_segment.self_replacements.is_empty()
        || !suffix_segment.self_replacements.is_empty()
    {
        return None;
    }

    let [sequence_effect] = partition_segment.default_effects.as_slice() else {
        return None;
    };
    let sequence = sequence_effect.downcast_ref::<crate::effects::SequenceEffect>()?;
    let suffix_effects = match suffix_segment.default_effects.as_slice() {
        [suffix_effect]
            if suffix_effect
                .downcast_ref::<crate::effects::SequenceEffect>()
                .is_some_and(|suffix| {
                    suffix.surface == ironsmith_core::SequenceSurface::CommaThen
                }) =>
        {
            &suffix_effect
                .downcast_ref::<crate::effects::SequenceEffect>()?
                .effects
        }
        effects => effects,
    };
    if sequence.surface != ironsmith_core::SequenceSurface::Coordinated
        || sequence.effects.len() != 5
        || !matches!(suffix_effects.len(), 1 | 2)
    {
        return None;
    }

    // Lowering keeps the coordinated search/reveal/split sentence inside one
    // sequence, then starts a new resolution segment for shuffle and scry;
    // that suffix may itself retain its authored comma-then sequence.
    // Rejoin only that exact boundary; the established matcher still proves
    // every tag, count, destination, player, and optional-search invariant.
    let mut flattened = Vec::with_capacity(sequence.effects.len() + suffix_effects.len());
    flattened.extend(sequence.effects.iter());
    flattened.extend(suffix_effects.iter());
    let rendered = describe_search_two_split_hand_graveyard_sequence(&flattened)?;
    Some((rendered, 2))
}

fn describe_cross_segment_search_move_shuffle_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    if let Some([search_segment, followup_segment]) = segments.get(start..start + 2)
        && search_segment.self_replacements.is_empty()
        && followup_segment.self_replacements.is_empty()
        && let Some(choose) = cross_segment_search_choose(search_segment)
        && let Some(followup_effects) =
            flattened_cross_segment_effects(std::slice::from_ref(followup_segment))
        && let [reveal_effect, move_effect, shuffle_effect] = followup_effects.as_slice()
        && let Some(reveal) = reveal_effect.downcast_ref::<crate::effects::RevealTaggedEffect>()
        && let Some(move_to_zone) = move_effect.downcast_ref::<crate::effects::MoveToZoneEffect>()
        && let Some(shuffle) = shuffle_effect.downcast_ref::<crate::effects::ShuffleLibraryEffect>()
        && let Some(rendered) =
            describe_search_choose_then_move(choose, Some(reveal), move_to_zone, Some(shuffle))
    {
        return Some((rendered, 2));
    }

    let [search_segment, move_segment, shuffle_segment] = segments.get(start..start + 3)? else {
        return None;
    };
    if [search_segment, move_segment, shuffle_segment]
        .iter()
        .any(|segment| !segment.self_replacements.is_empty())
    {
        return None;
    }

    let choose = cross_segment_search_choose(search_segment)?;

    let [move_effect] = move_segment.default_effects.as_slice() else {
        return None;
    };
    let tagged_move = move_effect.downcast_ref::<crate::effects::TaggedEffect>()?;
    let move_to_zone = tagged_move
        .effect
        .downcast_ref::<crate::effects::MoveToZoneEffect>()?;
    if move_to_zone.zone != Zone::Battlefield
        || !matches!(
            move_to_zone.target.base(),
            ChooseSpec::Tagged(tag) if tag.as_str() == choose.tag.as_str()
        )
    {
        return None;
    }

    let [shuffle_effect] = shuffle_segment.default_effects.as_slice() else {
        return None;
    };
    // Sentence lowering may preserve the authored `Then` boundary by wrapping
    // its sole executable effect in a one-item sequence. That wrapper carries
    // no extra semantics, so accept either representation here.
    let shuffle_effect = shuffle_effect
        .downcast_ref::<crate::effects::SequenceEffect>()
        .and_then(|sequence| match sequence.effects.as_slice() {
            [shuffle] => Some(shuffle),
            _ => None,
        })
        .unwrap_or(shuffle_effect);
    let shuffle = shuffle_effect.downcast_ref::<crate::effects::ShuffleLibraryEffect>()?;
    let rendered = describe_search_choose_then_move(choose, None, move_to_zone, Some(shuffle))?;
    let rendered = if choose.count.max == Some(1) {
        rendered
            .replacen(", put it ", ". Put that card ", 1)
            .replacen(", then ", ". Then ", 1)
    } else {
        rendered
            .replacen(", put ", ". Put ", 1)
            .replacen(", then ", ". Then ", 1)
    };
    Some((rendered, 3))
}

fn cross_segment_search_choose(
    search_segment: &crate::resolution::ResolutionSegment,
) -> Option<&crate::effects::ChooseObjectsEffect> {
    match search_segment.default_effects.as_slice() {
        [search_effect] => {
            Some(search_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?)
        }
        [target_effect, search_effect] => {
            let target_only = target_effect.downcast_ref::<crate::effects::TargetOnlyEffect>()?;
            let choose = search_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
            let ChooseSpec::Player(target_player) = target_only.target.base() else {
                return None;
            };
            let search_owner = choose.filter.owner.as_ref().unwrap_or(&choose.chooser);
            if !same_search_player_filter(target_player, search_owner) {
                return None;
            }
            Some(choose)
        }
        _ => return None,
    }
}

fn count_damage_controller_references_to_tag(effect: &Effect, tag: &TagKey) -> usize {
    let mut count = effect
        .downcast_ref::<crate::effects::DealDamageEffect>()
        .is_some_and(|damage| {
            matches!(
                damage.target.base(),
                ChooseSpec::Player(PlayerFilter::ControllerOf(
                    crate::target::ObjectRef::Tagged(reference),
                )) if reference == tag
            )
        }) as usize;
    effect.visit_child_effects(&mut |child| {
        count += count_damage_controller_references_to_tag(child, tag);
    });
    count
}

fn tagged_object_filter(effect: &Effect) -> Option<(&TagKey, &ObjectFilter)> {
    let tagged = effect.downcast_ref::<crate::effects::TaggedEffect>()?;
    let filter = if let Some(destroy) = tagged
        .effect
        .downcast_ref::<crate::effects::DestroyEffect>()
    {
        exact_single_target_object_filter(&destroy.spec)?
    } else if let Some(target_only) = tagged
        .effect
        .downcast_ref::<crate::effects::TargetOnlyEffect>()
    {
        exact_single_target_object_filter(&target_only.target)?
    } else if let Some(counter) = tagged
        .effect
        .downcast_ref::<crate::effects::CounterEffect>()
    {
        exact_single_target_object_filter(&counter.target)?
    } else if let Some(unless_pays) = tagged
        .effect
        .downcast_ref::<crate::effects::UnlessPaysEffect>()
    {
        let [counter_effect] = unless_pays.effects.as_slice() else {
            return None;
        };
        let counter = counter_effect.downcast_ref::<crate::effects::CounterEffect>()?;
        exact_single_target_object_filter(&counter.target)?
    } else {
        return None;
    };
    Some((&tagged.tag, filter))
}

fn collect_tagged_object_filters(effect: &Effect, filters: &mut Vec<(TagKey, ObjectFilter)>) {
    if let Some((tag, filter)) = tagged_object_filter(effect) {
        filters.push((tag.clone(), filter.clone()));
    }
    effect.visit_child_effects(&mut |child| {
        collect_tagged_object_filters(child, filters);
    });
}

fn effect_tree_has_tagged_destroy(effect: &Effect, tag: &TagKey) -> bool {
    if let Some(tagged) = effect.downcast_ref::<crate::effects::TaggedEffect>()
        && tagged.tag == *tag
        && tagged
            .effect
            .downcast_ref::<crate::effects::DestroyEffect>()
            .is_some()
    {
        return true;
    }
    let mut found = false;
    effect.visit_child_effects(&mut |child| {
        if !found && effect_tree_has_tagged_destroy(child, tag) {
            found = true;
        }
    });
    found
}

/// Rejoin an authored mass tap with the locked continuous untap restriction
/// on that exact set. The plural pronoun is proven by `All`, while `other`
/// plus the explicit single card-type noun supplies the source noun without
/// relying on a card name or ambient definition context.
fn describe_cross_segment_locked_set_tap_untap_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [tap_segment, restriction_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !tap_segment.self_replacements.is_empty()
        || !restriction_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [tap_effect] = tap_segment.default_effects.as_slice() else {
        return None;
    };
    let tap = tap_effect.downcast_ref::<crate::effects::TapEffect>()?;
    let ChooseSpec::All(tapped_filter) = tap.target.base() else {
        return None;
    };

    let [card_type] = tapped_filter.card_types.as_slice() else {
        return None;
    };
    let mut exact_filter = ObjectFilter::default()
        .with_type(*card_type)
        .in_zone(Zone::Battlefield);
    exact_filter.other = true;
    exact_filter.set_explicit_card_type_noun(Some(*card_type));
    if tapped_filter != &exact_filter {
        return None;
    }

    let [restriction_effect] = restriction_segment.default_effects.as_slice() else {
        return None;
    };
    let apply = restriction_effect.downcast_ref::<crate::effects::ApplyContinuousEffect>()?;
    let crate::continuous::EffectTarget::Filter(restricted_filter) = &apply.target else {
        return None;
    };
    if restricted_filter != tapped_filter
        || apply.target_spec.is_some()
        || !matches!(
            apply.modification.as_ref(),
            Some(crate::continuous::Modification::DoesntUntap)
        )
        || !apply.additional_modifications.is_empty()
        || !apply.runtime_modifications.is_empty()
        || apply.until != Until::SourceUntaps
        || apply.condition != Some(Condition::SourceIsTapped)
        || apply.source_type.is_some()
        || apply.set_quantifier_surface.is_some()
        || apply.type_retention_surface.is_some()
        || apply.animation_pt_surface.is_some()
        || apply.animation_duration_surface.is_some()
        || !apply.lock_filter_at_resolution
        || apply.resolve_set_pt_values_at_resolution
        || apply.require_creature_target
    {
        return None;
    }

    let mut noun_filter = tapped_filter.clone();
    noun_filter.zone = None;
    noun_filter.other = false;
    let noun_description = noun_filter.description();
    let noun = strip_indefinite_article(&noun_description);
    let typed_source = format!("this {noun}");
    let source = match apply.source_reference_surface.as_ref() {
        None => typed_source,
        Some(crate::target::SourceReferenceSurface::ThisPermanentType(surface))
            if surface.eq_ignore_ascii_case(&typed_source) =>
        {
            surface.clone()
        }
        Some(
            crate::target::SourceReferenceSurface::FullName(surface)
            | crate::target::SourceReferenceSurface::ShortName(surface),
        ) => surface.clone(),
        Some(crate::target::SourceReferenceSurface::ThisPermanentType(_)) => return None,
    };
    let tap_text = describe_effect(tap_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    Some((
        format!(
            "{tap_text}. They don't untap during their controllers' untap steps for as long as {source} remains tapped"
        ),
        2,
    ))
}

#[cfg(test)]
mod locked_set_tap_untap_window_tests {
    use super::*;

    fn other_artifacts() -> ObjectFilter {
        let mut filter = ObjectFilter::default()
            .with_type(CardType::Artifact)
            .in_zone(Zone::Battlefield);
        filter.other = true;
        filter.set_explicit_card_type_noun(Some(CardType::Artifact));
        filter
    }

    fn program_with_apply(
        apply: crate::effects::ApplyContinuousEffect,
    ) -> crate::resolution::ResolutionProgram {
        let filter = other_artifacts();
        crate::resolution::ResolutionProgram::new(vec![
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::tap_all(filter)]),
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::new(apply)]),
        ])
    }

    fn exact_apply(filter: ObjectFilter) -> crate::effects::ApplyContinuousEffect {
        crate::effects::ApplyContinuousEffect::new(
            crate::continuous::EffectTarget::Filter(filter),
            crate::continuous::Modification::DoesntUntap,
            Until::SourceUntaps,
        )
        .with_condition(Condition::SourceIsTapped)
        .lock_filter_at_resolution()
    }

    #[test]
    fn direct_mass_tap_locked_set_keeps_its_plural_pronoun() {
        let program = program_with_apply(exact_apply(other_artifacts()));
        assert_eq!(
            describe_resolution_program(&program),
            "Tap all other artifacts. They don't untap during their controllers' untap steps for as long as this artifact remains tapped"
        );
    }

    #[test]
    fn direct_mass_tap_compactor_requires_locked_equal_filter_and_typed_source_noun() {
        let expected =
            describe_resolution_program(&program_with_apply(exact_apply(other_artifacts())));

        let unlocked = crate::effects::ApplyContinuousEffect::new(
            crate::continuous::EffectTarget::Filter(other_artifacts()),
            crate::continuous::Modification::DoesntUntap,
            Until::SourceUntaps,
        )
        .with_condition(Condition::SourceIsTapped);
        assert_ne!(
            describe_resolution_program(&program_with_apply(unlocked)),
            expected
        );

        let mut different_filter = other_artifacts();
        different_filter.tapped = true;
        assert_ne!(
            describe_resolution_program(&program_with_apply(exact_apply(different_filter))),
            expected
        );

        let mut no_typed_noun = other_artifacts();
        no_typed_noun.set_explicit_card_type_noun(None);
        let no_typed_noun_program = crate::resolution::ResolutionProgram::new(vec![
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::tap_all(
                no_typed_noun.clone(),
            )]),
            crate::resolution::ResolutionSegment::from_effects(vec![Effect::new(exact_apply(
                no_typed_noun,
            ))]),
        ]);
        assert_ne!(
            describe_resolution_program(&no_typed_noun_program),
            expected
        );
    }
}

fn describe_cross_segment_tagged_tap_untap_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [tap_segment, restriction_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !tap_segment.self_replacements.is_empty()
        || !restriction_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [tagged_effect] = tap_segment.default_effects.as_slice() else {
        return None;
    };
    let tagged = tagged_effect.downcast_ref::<crate::effects::TaggedEffect>()?;
    let tap = tagged.effect.downcast_ref::<crate::effects::TapEffect>()?;
    let ChooseSpec::Object(tapped_filter) = tap.target.base() else {
        return None;
    };
    if tap.target.count().is_single() {
        return None;
    }

    let [restriction_effect] = restriction_segment.default_effects.as_slice() else {
        return None;
    };
    let cant = restriction_effect.downcast_ref::<crate::effects::CantEffect>()?;
    let crate::effect::Restriction::Untap(restricted_filter) = &cant.restriction else {
        return None;
    };
    let [constraint] = restricted_filter.tagged_constraints.as_slice() else {
        return None;
    };
    if constraint.tag != tagged.tag
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    {
        return None;
    }
    let mut untagged_filter = restricted_filter.clone();
    untagged_filter.tagged_constraints.clear();
    let mut selected_filter = tapped_filter.clone();
    if untagged_filter.controller.is_none() {
        selected_filter.controller = None;
    }
    if untagged_filter.owner.is_none() {
        selected_filter.owner = None;
    }
    if untagged_filter != ObjectFilter::default() && untagged_filter != selected_filter {
        return None;
    }

    let tapped_text = describe_effect(tagged_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    let mut referent_filter = tapped_filter.clone();
    referent_filter.controller = None;
    referent_filter.owner = None;
    let subject = pluralize_noun_phrase(
        referent_filter
            .description()
            .trim_start_matches("a ")
            .trim_start_matches("an "),
    );
    let restriction_text = match cant.duration {
        Until::ControllersNextUntapStep => {
            format!("Those {subject} don't untap during their controller's next untap step")
        }
        Until::YouStopControllingThis => format!(
            "Those {subject} don't untap during their controllers' untap steps {}",
            describe_until(&cant.duration)
        ),
        _ => return None,
    };
    Some((format!("{tapped_text}. {restriction_text}"), 2))
}

#[cfg(test)]
mod tagged_tap_untap_window_tests {
    use super::*;

    fn shipbreaker_shape(restriction_tag: &str) -> crate::resolution::ResolutionProgram {
        let target = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature()))
            .with_count(crate::effect::ChoiceCount::up_to(4));
        let tapped_tag = TagKey::from("tapped_group");
        let tap = Effect::tap(target).tag(tapped_tag);
        let restricted = ObjectFilter::default().match_tagged(
            restriction_tag,
            crate::filter::TaggedOpbjectRelation::IsTaggedObject,
        );
        let cant = Effect::cant_until(
            crate::effect::Restriction::Untap(restricted),
            Until::YouStopControllingThis,
        );
        crate::resolution::ResolutionProgram::new(vec![
            crate::resolution::ResolutionSegment::from_effects(vec![tap]),
            crate::resolution::ResolutionSegment::from_effects(vec![cant]),
        ])
    }

    #[test]
    fn tag_only_restriction_keeps_plural_tapped_set_surface() {
        let rendered = describe_resolution_program(&shipbreaker_shape("tapped_group"));
        assert!(
            rendered.starts_with(
                "Tap up to four target creatures. Those creatures don't untap during their controllers' untap steps"
            ),
            "{rendered}"
        );
    }

    #[test]
    fn different_restriction_tag_does_not_claim_plural_tapped_set_surface() {
        let rendered = describe_resolution_program(&shipbreaker_shape("different_group"));
        assert!(
            !rendered.contains("Those creatures don't untap"),
            "{rendered}"
        );
    }
}

fn describe_cross_segment_conditional_tagged_tap_untap_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [conditional_segment, restriction_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !conditional_segment.self_replacements.is_empty()
        || !restriction_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [conditional_effect] = conditional_segment.default_effects.as_slice() else {
        return None;
    };
    let conditional = conditional_effect.downcast_ref::<crate::effects::ConditionalEffect>()?;
    let [tag_effect, tap_effect] = conditional.if_true.as_slice() else {
        return None;
    };
    if !conditional.if_false.is_empty()
        || conditional.surface != ironsmith_core::ConditionalSurface::LeadingIf
    {
        return None;
    }
    let tag = tag_effect.downcast_ref::<crate::effects::TagMatchingObjectsEffect>()?;
    let tap = tap_effect.downcast_ref::<crate::effects::TapEffect>()?;
    let ChooseSpec::All(tapped_filter) = tap.target.base() else {
        return None;
    };
    if tag.filter != *tapped_filter || !tag.additional_zones.is_empty() || tag.zone.is_some() {
        return None;
    }

    let [restriction_effect] = restriction_segment.default_effects.as_slice() else {
        return None;
    };
    let cant = restriction_effect.downcast_ref::<crate::effects::CantEffect>()?;
    if cant.duration != Until::ControllersNextUntapStep {
        return None;
    }
    let crate::effect::Restriction::Untap(restricted_filter) = &cant.restriction else {
        return None;
    };
    let [constraint] = restricted_filter.tagged_constraints.as_slice() else {
        return None;
    };
    if constraint.tag != tag.tag
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    {
        return None;
    }
    let mut untagged_filter = restricted_filter.clone();
    untagged_filter.tagged_constraints.clear();
    let mut selected_filter = tapped_filter.clone();
    if !untagged_filter.attacking {
        selected_filter.attacking = false;
    }
    if untagged_filter != selected_filter {
        return None;
    }

    let condition_text = describe_condition(&conditional.condition);
    let label = matches!(
        &conditional.condition,
        Condition::ValueComparison {
            left: Value::LifeTotal(PlayerFilter::You),
            operator: crate::effect::ValueComparisonOperator::LessThanOrEqual,
            right: Value::Fixed(5),
        }
    )
    .then_some("Fateful hour — ")
    .unwrap_or_default();
    let tap_text = lowercase_first(describe_effect(tap_effect).trim().trim_end_matches('.'));
    let subject = pluralize_noun_phrase(
        untagged_filter
            .description()
            .trim_start_matches("a ")
            .trim_start_matches("an "),
    );
    Some((
        format!(
            "{label}If {condition_text}, {tap_text}. Those {subject} don't untap during their controller's next untap step"
        ),
        2,
    ))
}

fn describe_cross_segment_typed_controller_damage_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [producer_segment, damage_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !producer_segment.self_replacements.is_empty()
        || !damage_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [damage_effect] = damage_segment.default_effects.as_slice() else {
        return None;
    };
    let mut tagged_filters = Vec::new();
    for effect in &producer_segment.default_effects {
        collect_tagged_object_filters(effect, &mut tagged_filters);
    }
    let candidates = tagged_filters
        .iter()
        .filter(|(tag, _)| count_damage_controller_references_to_tag(damage_effect, tag) == 1)
        .collect::<Vec<_>>();
    let [(tag, filter)] = candidates.as_slice() else {
        return None;
    };
    let noun = if filter.stack_kind == Some(crate::filter::StackObjectKind::Spell) {
        "spell"
    } else if !filter.subtypes.is_empty()
        && filter.subtypes.iter().all(crate::Subtype::is_land_subtype)
    {
        "land"
    } else {
        match filter.card_types.as_slice() {
            [CardType::Land] => "land",
            [CardType::Artifact] => "artifact",
            [CardType::Creature] => "creature",
            [CardType::Enchantment] => "enchantment",
            [CardType::Planeswalker] => "planeswalker",
            [CardType::Battle] => "battle",
            [CardType::Artifact, CardType::Enchantment]
            | [CardType::Enchantment, CardType::Artifact] => "permanent",
            _ => return None,
        }
    };
    if count_damage_controller_references_to_tag(damage_effect, tag) != 1 {
        return None;
    }
    let producer_text = describe_effect_list(&producer_segment.default_effects)
        .trim()
        .trim_end_matches('.')
        .to_string();
    let mut damage_text = describe_effect(damage_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    let existing_controller_reference = [
        "that object's controller",
        "that permanent's controller",
        "that artifact's controller",
        "that creature's controller",
        "that enchantment's controller",
        "that land's controller",
        "that planeswalker's controller",
        "that battle's controller",
        "that spell's controller",
    ]
    .into_iter()
    .find(|candidate| damage_text.matches(candidate).count() == 1)?;
    damage_text = damage_text.replace(
        existing_controller_reference,
        &format!("that {noun}'s controller"),
    );
    if producer_segment
        .default_effects
        .iter()
        .any(|effect| effect_tree_has_tagged_destroy(effect, tag))
        && let Some(conditional) = damage_effect.downcast_ref::<crate::effects::ConditionalEffect>()
    {
        let Condition::TaggedObjectMatches(condition_tag, condition_filter) =
            &conditional.condition
        else {
            return None;
        };
        let mut semantic_condition_filter = condition_filter.clone();
        semantic_condition_filter.set_demonstrative_antecedent_surface(None);
        let [true_effect] = conditional.if_true.as_slice() else {
            return None;
        };
        if condition_tag != tag
            || semantic_condition_filter != ObjectFilter::default()
            || !conditional.if_false.is_empty()
            || conditional.surface != ironsmith_core::ConditionalSurface::LeadingIf
        {
            return None;
        }
        let true_text = describe_effect(true_effect)
            .trim()
            .trim_end_matches('.')
            .to_string();
        let controller = "that object's controller";
        let (source, amount) = true_text
            .strip_suffix(controller)
            .and_then(|prefix| prefix.rsplit_once(" deals damage "))?;
        damage_text = format!(
            "If that {noun} is put into a graveyard this way, {source} deals damage to that {noun}'s controller {}",
            amount.trim_end_matches(" to ")
        );
    }
    if noun == "land" {
        damage_text = damage_text.replace(
            "If it was a nonbasic permanent, ",
            "If that land was nonbasic, ",
        );
    } else if noun == "creature" {
        damage_text =
            damage_text.replace("If it was attacking, ", "If that creature was attacking, ");
        if damage_effect
            .downcast_ref::<crate::effects::ConditionalEffect>()
            .is_some_and(|conditional| {
                matches!(
                    &conditional.condition,
                    Condition::TaggedObjectMatches(condition_tag, condition_filter)
                        if condition_tag == tag && condition_filter.attacking
                )
            })
        {
            damage_text = damage_text.replace(
                "If that creature was attacking, ",
                "If that creature is attacking, ",
            );
        }
    }
    Some((
        format!("{producer_text}. {}", capitalize_first(&damage_text)),
        2,
    ))
}

fn describe_cross_segment_chain_copy_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [antecedent_segment, enabling_segment, conditional_segment] =
        segments.get(start..start + 3)?
    else {
        return None;
    };
    if [antecedent_segment, enabling_segment, conditional_segment]
        .iter()
        .any(|segment| !segment.self_replacements.is_empty())
        || antecedent_segment.default_effects.is_empty()
    {
        return None;
    }

    let [enabling_effect] = enabling_segment.default_effects.as_slice() else {
        return None;
    };
    let enabling_effect = enabling_effect
        .downcast_ref::<crate::effects::SequenceEffect>()
        .and_then(|sequence| {
            let [only] = sequence.effects.as_slice() else {
                return None;
            };
            Some(only)
        })
        .unwrap_or(enabling_effect);
    let enabling_with_id = enabling_effect.downcast_ref::<crate::effects::WithIdEffect>()?;
    enabling_with_id
        .effect
        .downcast_ref::<crate::effects::MayEffect>()?;

    let [conditional_effect] = conditional_segment.default_effects.as_slice() else {
        return None;
    };
    conditional_effect.downcast_ref::<crate::effects::IfEffect>()?;

    let mut combined = antecedent_segment.default_effects.clone();
    combined.push(enabling_effect.clone());
    combined.push(conditional_effect.clone());
    let rendered = describe_chain_copy_effect_list(&combined)?;
    Some((rendered, 3))
}

fn describe_cross_segment_chooser_target_exchange_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [target_segment, exchange_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !target_segment.self_replacements.is_empty()
        || !exchange_segment.self_replacements.is_empty()
    {
        return None;
    }
    let effects = target_segment
        .default_effects
        .iter()
        .chain(&exchange_segment.default_effects)
        .collect::<Vec<_>>();
    describe_target_only_then_exchange_control(&effects).map(|rendered| (rendered, 2))
}

fn describe_cross_segment_source_owner_consult_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [shuffle_segment, consult_segment, partition_segment] = segments.get(start..start + 3)?
    else {
        return None;
    };
    if shuffle_segment.starts_new_source_line
        || consult_segment.starts_new_source_line
        || partition_segment.starts_new_source_line
        || !shuffle_segment.self_replacements.is_empty()
        || !consult_segment.self_replacements.is_empty()
        || !partition_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [shuffle_effect] = shuffle_segment.default_effects.as_slice() else {
        return None;
    };
    let shuffle_with_id = shuffle_effect.downcast_ref::<crate::effects::WithIdEffect>()?;
    let [conditional_effect] = consult_segment.default_effects.as_slice() else {
        return None;
    };
    let conditional = conditional_effect.downcast_ref::<crate::effects::IfEffect>()?;
    if conditional.condition != shuffle_with_id.id
        || conditional.predicate != EffectPredicate::Happened
        || !conditional.else_.is_empty()
        || conditional.prior_result_replacement_surface
    {
        return None;
    }
    let [consult_effect] = conditional.then.as_slice() else {
        return None;
    };
    let [move_effect, remainder_effect] = partition_segment.default_effects.as_slice() else {
        return None;
    };
    describe_source_owner_shuffle_then_reveal_named_to_battlefield(&[
        shuffle_effect,
        consult_effect,
        move_effect,
        remainder_effect,
    ])
    .map(|rendered| (rendered, 3))
}

fn describe_cross_segment_created_token_followup_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [create_segment, followup_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !create_segment.self_replacements.is_empty()
        || !followup_segment.self_replacements.is_empty()
    {
        return None;
    }
    let [create_effect] = create_segment.default_effects.as_slice() else {
        return None;
    };
    let (created_tag, create) = tagged_create_token_effect_for_keyword(create_effect)?;
    if matches!(create.count.unhinted(), Value::Fixed(1)) {
        return None;
    }
    let [followup_effect] = followup_segment.default_effects.as_slice() else {
        return None;
    };

    let followup = if let Some(exile) =
        followup_effect.downcast_ref::<crate::effects::ExileTaggedWhenSourceLeavesEffect>()
        && &exile.tag == created_tag
    {
        "Exile those tokens when this permanent leaves the battlefield".to_string()
    } else if let Some(schedule) =
        followup_effect.downcast_ref::<crate::effects::ScheduleDelayedTriggerEffect>()
        && schedule.one_shot
        && schedule.start_next_turn
        && !schedule.until_end_of_turn
        && schedule.controller == PlayerFilter::You
        && schedule
            .trigger
            .downcast_ref::<crate::triggers::BeginningOfUpkeepTrigger>()
            .is_some()
    {
        let [delayed_effect] = schedule.effects.flattened_default_effects() else {
            return None;
        };
        let sacrifice = delayed_effect.downcast_ref::<crate::effects::SacrificeTargetEffect>()?;
        if !matches!(&sacrifice.target, ChooseSpec::Tagged(tag) if tag == created_tag) {
            return None;
        }
        "Sacrifice those tokens at the beginning of your next upkeep".to_string()
    } else {
        return None;
    };

    let creation = describe_effect(create_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    Some((format!("{creation}. {followup}"), 2))
}

fn describe_cross_segment_created_token_reciprocal_leave_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [create_segment, exile_segment, sacrifice_segment] = segments.get(start..start + 3)? else {
        return None;
    };
    if [create_segment, exile_segment, sacrifice_segment]
        .iter()
        .any(|segment| {
            segment.starts_new_source_line
                || !segment.self_replacements.is_empty()
                || segment.default_effects.len() != 1
        })
    {
        return None;
    }
    let create_effect = &create_segment.default_effects[0];
    let (created_tag, create) = tagged_create_token_effect_for_keyword(create_effect)?;
    let exile = exile_segment.default_effects[0]
        .downcast_ref::<crate::effects::ExileTaggedWhenSourceLeavesEffect>()?;
    let reciprocal = sacrifice_segment.default_effects[0]
        .downcast_ref::<crate::effects::ScheduleEffectsWhenTaggedLeavesEffect>()?;
    let [sacrifice_effect] = reciprocal.effects.as_slice() else {
        return None;
    };
    let sacrifice = sacrifice_effect.downcast_ref::<crate::effects::SacrificeTargetEffect>()?;
    if create.count.unhinted() != &Value::Fixed(1)
        || create.controller != PlayerFilter::You
        || exile.tag != *created_tag
        || exile.controller != PlayerFilter::You
        || reciprocal.tag != *created_tag
        || reciprocal.controller != PlayerFilter::You
        || reciprocal.ability_source != crate::effects::TaggedLeavesAbilitySource::CurrentSource
        || !matches!(sacrifice.target.unhinted(), ChooseSpec::Source)
    {
        return None;
    }
    let creation = describe_effect(create_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    Some((
        format!(
            "{creation}. Exile that token when this permanent leaves the battlefield. Sacrifice this permanent when that token leaves the battlefield"
        ),
        3,
    ))
}

fn describe_cross_segment_each_player_token_characteristic_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [create_segment, characteristic_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if create_segment.starts_new_source_line
        || characteristic_segment.starts_new_source_line
        || !create_segment.self_replacements.is_empty()
        || !characteristic_segment.self_replacements.is_empty()
    {
        return None;
    }

    let [for_players_effect] = create_segment.default_effects.as_slice() else {
        return None;
    };
    let for_players = for_players_effect.downcast_ref::<crate::effects::ForPlayersEffect>()?;
    if for_players.filter != PlayerFilter::Any
        || for_players.starting_with_controller
        || for_players.stop_after_first_happened
    {
        return None;
    }
    let [create_effect] = for_players.effects.as_slice() else {
        return None;
    };
    let (created_tag, create) = tagged_create_token_effect_for_keyword(create_effect)?;
    if create.count.unhinted() != &Value::Fixed(1)
        || create.controller != PlayerFilter::IteratedPlayer
        || create.controller_target.is_some()
        || create.use_source_chosen_color
        || create.use_source_chosen_creature_type
        || create.actor_surface_explicit
        || create.suppress_aura_attachment_choice
        || create.ability_presentation.is_some()
        || create.enters_tapped
        || create.enters_attacking
        || create.attack_target_mode.is_some()
        || create.exile_at_end_of_combat
        || create.sacrifice_at_end_of_combat
        || create.sacrifice_at_next_end_step
        || create.exile_at_next_end_step
        || !create.token.abilities.is_empty()
    {
        return None;
    }
    let token_blueprint = super::normalize_common::describe_token_blueprint(&create.token);
    let token_blueprint = token_blueprint.strip_prefix("0/0 ")?;

    let [characteristic_effect] = characteristic_segment.default_effects.as_slice() else {
        return None;
    };
    let tagged = unwrap_effect_for_keyword(characteristic_effect)
        .downcast_ref::<crate::effects::TaggedEffect>()?;
    let continuous = unwrap_effect_for_keyword(&tagged.effect)
        .downcast_ref::<crate::effects::ApplyContinuousEffect>()?;
    if continuous.target != crate::continuous::EffectTarget::Source
        || !matches!(
            &continuous.target_spec,
            Some(ChooseSpec::Tagged(tag)) if tag == created_tag
        )
        || !continuous.additional_modifications.is_empty()
        || !continuous.runtime_modifications.is_empty()
        || continuous.until != Until::Forever
        || continuous.condition.is_some()
        || continuous.source_type.is_some()
        || continuous.source_reference_surface.is_some()
        || continuous.set_quantifier_surface != Some(ironsmith_core::SetQuantifierSurface::Those)
        || continuous.type_retention_surface.is_some()
        || continuous.animation_pt_surface.is_some()
        || continuous.animation_duration_surface.is_some()
        || continuous.lock_filter_at_resolution
        || continuous.resolve_set_pt_values_at_resolution
        || continuous.require_creature_target
    {
        return None;
    }
    let Some(crate::continuous::Modification::AddAbility(characteristic)) =
        continuous.modification.as_ref()
    else {
        return None;
    };
    if characteristic.id() != crate::static_abilities::StaticAbilityId::CharacteristicDefiningPT {
        return None;
    }
    let characteristic_text = characteristic.display();
    if !characteristic_text.starts_with("This creature's power and toughness are each equal to ") {
        return None;
    }
    let quoted = super::normalize_common::quote_token_granted_ability_text(&characteristic_text);
    Some((
        format!("Each player creates a {token_blueprint}. Those creatures have {quoted}"),
        2,
    ))
}

fn describe_cross_segment_quantified_choice_exile_until_source_leaves_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [choice_segment, exile_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if [choice_segment, exile_segment]
        .iter()
        .any(|segment| segment.starts_new_source_line || !segment.self_replacements.is_empty())
    {
        return None;
    }
    let [for_players_effect] = choice_segment.default_effects.as_slice() else {
        return None;
    };
    let for_players = for_players_effect.downcast_ref::<crate::effects::ForPlayersEffect>()?;
    let [choose_effect] = for_players.effects.as_slice() else {
        return None;
    };
    let choose = choose_effect.downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    if for_players.filter != PlayerFilter::Any
        || for_players.starting_with_controller
        || for_players.stop_after_first_happened
        || choose.chooser != PlayerFilter::IteratedPlayer
        || choose.count != crate::effect::ChoiceCount::exactly(2)
        || choose.count_value.is_some()
        || choose.aggregate_constraint.is_some()
        || choose.zone != Some(Zone::Battlefield)
        || !choose.additional_zones.is_empty()
        || choose.filter.zone != Some(Zone::Battlefield)
        || choose.filter.controller != Some(PlayerFilter::IteratedPlayer)
        || choose.is_search
        || choose.reveal
        || choose.top_only
        || choose.bottom_only
        || choose.replace_tagged_objects
    {
        return None;
    }
    let [exile_effect] = exile_segment.default_effects.as_slice() else {
        return None;
    };
    let exile = exile_effect.downcast_ref::<crate::effects::ExileUntilEffect>()?;
    if exile.spec != ChooseSpec::Tagged(choose.tag.clone())
        || exile.duration != crate::effects::ExileUntilDuration::SourceLeavesBattlefield
        || exile.leave_watcher.is_some()
        || exile.return_zone != Zone::Battlefield
        || exile.face_down
        || exile.explicit_return_surface
    {
        return None;
    }
    let mut choice_filter = choose.filter.clone();
    choice_filter.zone = None;
    choice_filter.controller = None;
    choice_filter.card_types.clear();
    choice_filter.excluded_subtypes.clear();
    choice_filter.nontoken = false;
    choice_filter.union_surface = Default::default();
    let exact_nontoken_nonvehicle_creatures = choose.filter.card_types.as_slice()
        == [CardType::Creature]
        && choose.filter.excluded_subtypes.as_slice() == [Subtype::Vehicle]
        && choose.filter.nontoken
        && choice_filter == ObjectFilter::default();
    let choice = if exact_nontoken_nonvehicle_creatures {
        "Each player chooses two nontoken, non-Vehicle creatures they control".to_string()
    } else {
        describe_effect(for_players_effect)
            .trim()
            .trim_end_matches('.')
            .to_string()
    };
    Some((
        format!("{choice}. Exile them until this permanent leaves the battlefield"),
        2,
    ))
}

#[cfg(test)]
mod quantified_choice_exile_until_tests {
    use super::*;

    fn program(exile_tag: &str) -> crate::resolution::ResolutionProgram {
        let choice_tag = TagKey::from("participant_choice");
        let choose = crate::effects::ChooseObjectsEffect::new(
            ObjectFilter::creature()
                .controlled_by(PlayerFilter::IteratedPlayer)
                .in_zone(Zone::Battlefield),
            crate::effect::ChoiceCount::exactly(2),
            PlayerFilter::IteratedPlayer,
            choice_tag,
        )
        .in_zone(Zone::Battlefield);
        let players = Effect::new(crate::effects::ForPlayersEffect::new(
            PlayerFilter::Any,
            vec![Effect::new(choose)],
        ));
        let exile = Effect::new(crate::effects::ExileUntilEffect::new(
            ChooseSpec::Tagged(TagKey::from(exile_tag)),
            crate::effects::ExileUntilDuration::SourceLeavesBattlefield,
        ));
        crate::resolution::ResolutionProgram::new(vec![
            crate::resolution::ResolutionSegment::from_effects(vec![players]),
            crate::resolution::ResolutionSegment::from_effects(vec![exile]),
        ])
    }

    #[test]
    fn rejoins_the_exact_quantified_choice_collection() {
        let program = program("participant_choice");
        assert_eq!(
            describe_cross_segment_quantified_choice_exile_until_source_leaves_window(
                &program.segments,
                0,
            )
            .map(|(_, consumed)| consumed),
            Some(2)
        );
    }

    #[test]
    fn rejects_a_different_collection_tag() {
        let program = program("other_choice");
        assert_eq!(
            describe_cross_segment_quantified_choice_exile_until_source_leaves_window(
                &program.segments,
                0,
            ),
            None
        );
    }
}

fn describe_cross_segment_created_token_copy_retarget_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [create_copy_segment, retarget_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !create_copy_segment.self_replacements.is_empty()
        || !retarget_segment.self_replacements.is_empty()
    {
        return None;
    }

    let sequence_effect = match create_copy_segment.default_effects.as_slice() {
        [sequence_effect] => sequence_effect,
        [trigger_tag, sequence_effect]
            if trigger_tag
                .downcast_ref::<crate::effects::TagTriggeringObjectEffect>()
                .is_some() =>
        {
            sequence_effect
        }
        _ => return None,
    };
    let sequence = structural_unwrap_render_wrappers(sequence_effect)
        .downcast_ref::<crate::effects::SequenceEffect>()?;
    if sequence.surface != ironsmith_core::SequenceSurface::CommaThen {
        return None;
    }
    let [create_effect, copy_effect] = sequence.effects.as_slice() else {
        return None;
    };
    let [retarget_effect] = retarget_segment.default_effects.as_slice() else {
        return None;
    };

    super::render_effects::describe_create_token_then_copy_retarget_to_created_token(&[
        create_effect,
        copy_effect,
        retarget_effect,
    ])
    .map(|rendered| (rendered, 2))
}

fn describe_cross_segment_shuffle_exile_top_cast_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [producer_segment, permission_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !producer_segment.self_replacements.is_empty()
        || !permission_segment.self_replacements.is_empty()
    {
        return None;
    }
    let (shuffle_effect, exile_effect) = match producer_segment.default_effects.as_slice() {
        [shuffle_effect, exile_effect] => (shuffle_effect, exile_effect),
        [sequence_effect] => {
            let sequence = structural_unwrap_render_wrappers(sequence_effect)
                .downcast_ref::<crate::effects::SequenceEffect>()?;
            let [shuffle_effect, exile_effect] = sequence.effects.as_slice() else {
                return None;
            };
            (shuffle_effect, exile_effect)
        }
        _ => return None,
    };
    let [permission_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    render_shuffle_exile_top_then_cast_any_number_with_mana_value_cap(&[
        shuffle_effect,
        exile_effect,
        permission_effect,
    ])
    .map(|rendered| (rendered, 2))
}

/// Rejoin a coordinated producer sentence with the following permission
/// sentence when lowering placed them in adjacent resolution segments. The
/// shared exile tag proves the permission consumes the cards produced by the
/// first segment, so the typed effect-list renderer can recover the authored
/// duration surface and sentence boundary.
fn describe_cross_segment_linked_exile_top_play_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    fn flattened_segment_effects(
        segment: &crate::resolution::ResolutionSegment,
    ) -> Option<Vec<Effect>> {
        if !segment.self_replacements.is_empty() || segment.default_effects.is_empty() {
            return None;
        }
        if let [effect] = segment.default_effects.as_slice()
            && let Some(sequence) = structural_unwrap_render_wrappers(effect)
                .downcast_ref::<crate::effects::SequenceEffect>()
        {
            return Some(sequence.effects.clone());
        }
        Some(segment.default_effects.clone())
    }

    let mut effects = flattened_segment_effects(segments.get(start)?)?;
    let mut linked_tags = effects
        .iter()
        .filter_map(|effect| {
            structural_unwrap_render_wrappers(effect)
                .downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()
        })
        .flat_map(|exile| exile.moved_tags.iter().cloned())
        .collect::<Vec<_>>();
    let mut consumed_following_producer_segment = false;
    if linked_tags.is_empty() {
        // A preceding cost-reduction sentence can define the same authored X
        // used by an exile-top producer in the next source sentence. Start
        // the linked window at that typed reduction so the effect-list
        // renderer can emit the shared `where X is ...` basis only once.
        let [reduction_effect] = effects.as_slice() else {
            return None;
        };
        let reduction = structural_unwrap_render_wrappers(reduction_effect)
            .downcast_ref::<crate::effects::GrantNextSpellCostReductionEffect>()?;
        let reduction_value = reduction.generic_reduction.as_ref()?;
        let producer_effects = flattened_segment_effects(segments.get(start + 1)?)?;
        linked_tags = producer_effects
            .iter()
            .filter_map(|effect| {
                structural_unwrap_render_wrappers(effect)
                    .downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()
            })
            .filter(|exile| &exile.count == reduction_value)
            .flat_map(|exile| exile.moved_tags.iter().cloned())
            .collect();
        if linked_tags.is_empty() {
            return None;
        }
        effects.extend(producer_effects);
        consumed_following_producer_segment = true;
    }

    let next_segment = if consumed_following_producer_segment {
        start + 2
    } else {
        start + 1
    };
    let mut derived_tag_sources = std::collections::HashMap::new();
    for end in next_segment..(start + 5).min(segments.len()) {
        let segment_effects = flattened_segment_effects(&segments[end])?;
        for effect in &segment_effects {
            let Some(matching) = effect.downcast_ref::<crate::effects::TagMatchingObjectsEffect>()
            else {
                continue;
            };
            let source_tag = linked_tags.iter().find(|source_tag| {
                matching.filter
                    == ObjectFilter::nonland().in_zone(Zone::Exile).match_tagged(
                        (*source_tag).clone(),
                        crate::filter::TaggedOpbjectRelation::IsTaggedObject,
                    )
            });
            if let Some(source_tag) = source_tag {
                derived_tag_sources.insert(matching.tag.clone(), source_tag.clone());
            }
        }
        linked_tags.extend(derived_tag_sources.keys().cloned());

        let mut normalized_segment_effects = Vec::new();
        let mut has_linked_grant = false;
        for effect in segment_effects {
            if effect
                .downcast_ref::<crate::effects::TagMatchingObjectsEffect>()
                .is_some_and(|matching| derived_tag_sources.contains_key(&matching.tag))
            {
                continue;
            }
            if let Some(grant) = effect.downcast_ref::<crate::effects::GrantPlayTaggedEffect>()
                && let Some(source_tag) = derived_tag_sources.get(&grant.tag)
            {
                let mut normalized = grant.clone();
                normalized.tag = source_tag.clone();
                has_linked_grant = true;
                normalized_segment_effects.push(Effect::new(normalized));
                continue;
            }
            has_linked_grant |= effect
                .downcast_ref::<crate::effects::GrantPlayTaggedEffect>()
                .is_some_and(|grant| linked_tags.contains(&grant.tag));
            normalized_segment_effects.push(effect);
        }
        effects.extend(normalized_segment_effects);
        if has_linked_grant {
            return describe_linked_exile_top_play_clause(&effects)
                .map(|rendered| (rendered, end - start + 1));
        }
    }
    None
}

/// Render a narrowed temporary cast permission whose successful use grants an
/// ability to that exact card.  The helper tag used for the narrowed subset is
/// executable provenance; the authored surface is the spell filter plus the
/// prior exiled collection.
fn describe_cross_segment_filtered_exile_cast_then_has_ability_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [exile_segment, permission_segment, result_segment] = segments.get(start..start + 3)?
    else {
        return None;
    };
    if [exile_segment, permission_segment, result_segment]
        .iter()
        .any(|segment| segment.starts_new_source_line || !segment.self_replacements.is_empty())
    {
        return None;
    }

    let [exile_effect] = exile_segment.default_effects.as_slice() else {
        return None;
    };
    let exile = exile_effect.downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()?;
    let [exiled_tag] = exile.moved_tags.as_slice() else {
        return None;
    };
    if exile.player != PlayerFilter::You || exile.face_down || !exile.accumulated_tags.is_empty() {
        return None;
    }

    let [matching_effect, permission_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    let matching = matching_effect.downcast_ref::<crate::effects::TagMatchingObjectsEffect>()?;
    if matching.zone != Some(Zone::Exile) || !matching.additional_zones.is_empty() {
        return None;
    }
    let [constraint] = matching.filter.tagged_constraints.as_slice() else {
        return None;
    };
    if constraint.tag != *exiled_tag
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
        || matching.filter.zone != Some(Zone::Exile)
    {
        return None;
    }
    let mut spell_filter = matching.filter.clone();
    spell_filter.zone = None;
    spell_filter.tagged_constraints.clear();
    if spell_filter == ObjectFilter::default() {
        return None;
    }

    let with_id = permission_effect.downcast_ref::<crate::effects::WithIdEffect>()?;
    let grant = with_id
        .effect
        .downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    if grant.tag != matching.tag
        || grant.player != PlayerFilter::You
        || grant.duration != crate::effects::GrantPlayTaggedDuration::UntilEndOfTurn
        || grant.surface.is_some()
        || grant.allow_land
        || grant.mana_spend_mode != ironsmith_core::value_model::ManaSpendMode::Normal
        || grant.allow_any_color_for_cast
        || grant.while_on_top_of_library
        || grant.filter.is_some()
        || grant.during_turns_counter_put_on_source.is_some()
        || grant.spell_cost_increase.is_some()
        || grant.lands_enter_tapped
        || grant.cast_pool_is_plural
        || grant.max_plays.is_some()
    {
        return None;
    }

    let [result_effect] = result_segment.default_effects.as_slice() else {
        return None;
    };
    let result = result_effect.downcast_ref::<crate::effects::IfEffect>()?;
    if result.condition != with_id.id
        || result.predicate != EffectPredicate::Happened
        || !result.else_.is_empty()
        || result.per_player_result
        || result.prior_result_replacement_surface
    {
        return None;
    }
    let [apply_effect] = result.then.as_slice() else {
        return None;
    };
    let apply = apply_effect.downcast_ref::<crate::effects::ApplyContinuousEffect>()?;
    let Some(crate::continuous::Modification::AddAbility(ability)) = apply.modification.as_ref()
    else {
        return None;
    };
    if apply.target != crate::continuous::EffectTarget::Source
        || !matches!(&apply.target_spec, Some(ChooseSpec::Tagged(tag)) if tag == &matching.tag)
        || !apply.additional_modifications.is_empty()
        || !apply.runtime_modifications.is_empty()
        || apply.until != Until::Forever
        || apply.condition.is_some()
        || apply.source_type.is_some()
        || apply.source_reference_surface.is_some()
        || apply.set_quantifier_surface.is_some()
        || apply.type_retention_surface.is_some()
        || apply.animation_pt_surface.is_some()
        || apply.animation_duration_surface.is_some()
        || apply.lock_filter_at_resolution
        || apply.resolve_set_pt_values_at_resolution
        || apply.require_creature_target
    {
        return None;
    }

    let exile_text = describe_effect(exile_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    let spell = super::normalize_common::describe_cast_spell_filter(
        &spell_filter,
        super::normalize_common::CastSpellFilterContext::EnclosingPermission,
    );
    let ability = lowercase_first(ability.display().trim().trim_end_matches('.'));
    Some((
        format!(
            "{exile_text}. You may cast {} from among them this turn. If you do, it has {ability}",
            with_indefinite_article(&spell)
        ),
        3,
    ))
}

fn describe_cross_segment_filtered_exile_cast_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [exile_segment, permission_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if [exile_segment, permission_segment]
        .iter()
        .any(|segment| segment.starts_new_source_line || !segment.self_replacements.is_empty())
    {
        return None;
    }
    let [exile_effect] = exile_segment.default_effects.as_slice() else {
        return None;
    };
    let exile = exile_effect.downcast_ref::<crate::effects::ExileTopOfLibraryEffect>()?;
    let [exiled_tag] = exile.moved_tags.as_slice() else {
        return None;
    };
    if exile.player != PlayerFilter::You || exile.face_down || !exile.accumulated_tags.is_empty() {
        return None;
    }
    let [matching_effect, permission_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    let matching = matching_effect.downcast_ref::<crate::effects::TagMatchingObjectsEffect>()?;
    let [constraint] = matching.filter.tagged_constraints.as_slice() else {
        return None;
    };
    if matching.zone != Some(Zone::Exile)
        || !matching.additional_zones.is_empty()
        || matching.filter.zone != Some(Zone::Exile)
        || constraint.tag != *exiled_tag
        || constraint.relation != crate::filter::TaggedOpbjectRelation::IsTaggedObject
    {
        return None;
    }
    let mut spell_filter = matching.filter.clone();
    spell_filter.zone = None;
    spell_filter.tagged_constraints.clear();
    if spell_filter == ObjectFilter::default() {
        return None;
    }
    let grant = permission_effect.downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    if grant.tag != matching.tag
        || grant.player != PlayerFilter::You
        || grant.duration != crate::effects::GrantPlayTaggedDuration::UntilEndOfTurn
        || grant.surface.is_some()
        || grant.allow_land
        || grant.mana_spend_mode != ironsmith_core::value_model::ManaSpendMode::Normal
        || grant.allow_any_color_for_cast
        || grant.while_on_top_of_library
        || grant.filter.is_some()
        || grant.during_turns_counter_put_on_source.is_some()
        || grant.spell_cost_increase.is_some()
        || grant.lands_enter_tapped
        || grant.cast_pool_is_plural
        || grant.max_plays.is_some()
    {
        return None;
    }

    let exile_text = describe_effect(exile_effect)
        .trim()
        .trim_end_matches('.')
        .to_string();
    let spell = super::normalize_common::describe_cast_spell_filter(
        &spell_filter,
        super::normalize_common::CastSpellFilterContext::EnclosingPermission,
    );
    let spells = super::normalize_common::pluralize_cast_spell_description(&spell);
    Some((
        format!("{exile_text}. You may cast {spells} from among them this turn"),
        2,
    ))
}

#[cfg(test)]
mod filtered_exile_cast_then_has_ability_tests {
    use super::*;

    fn program(result_id: u32, result_tag: &str) -> crate::resolution::ResolutionProgram {
        let exiled_tag = TagKey::from("exiled_pool");
        let castable_tag = TagKey::from("castable_pool");
        let exile = Effect::new(
            crate::effects::ExileTopOfLibraryEffect::new(Value::Fixed(5), PlayerFilter::You)
                .tag_moved(exiled_tag.clone()),
        );
        let matching_filter = ObjectFilter::artifact().in_zone(Zone::Exile).match_tagged(
            exiled_tag,
            crate::filter::TaggedOpbjectRelation::IsTaggedObject,
        );
        let matching = Effect::new(
            crate::effects::TagMatchingObjectsEffect::new(matching_filter, castable_tag.clone())
                .in_zone(Zone::Exile),
        );
        let grant = Effect::new(crate::effects::WithIdEffect::new(
            crate::effect::EffectId(7),
            Effect::new(crate::effects::GrantPlayTaggedEffect::new(
                castable_tag,
                PlayerFilter::You,
                crate::effects::GrantPlayTaggedDuration::UntilEndOfTurn,
                false,
                ironsmith_core::value_model::ManaSpendMode::Normal,
            )),
        ));
        let mut apply = crate::effects::ApplyContinuousEffect::new(
            crate::continuous::EffectTarget::Source,
            crate::continuous::Modification::AddAbility(
                crate::static_abilities::StaticAbility::affinity_for_artifacts(),
            ),
            Until::Forever,
        );
        apply.target_spec = Some(ChooseSpec::Tagged(TagKey::from(result_tag)));
        let apply = Effect::new(apply);
        let result = Effect::if_then(
            crate::effect::EffectId(result_id),
            EffectPredicate::Happened,
            vec![apply],
        );
        crate::resolution::ResolutionProgram::new(vec![
            crate::resolution::ResolutionSegment::from_effects(vec![exile]),
            crate::resolution::ResolutionSegment::from_effects(vec![matching, grant]),
            crate::resolution::ResolutionSegment::from_effects(vec![result]),
        ])
    }

    #[test]
    fn renders_exact_filtered_exiled_subset_and_result_link() {
        let program = program(7, "castable_pool");
        assert_eq!(
            describe_cross_segment_filtered_exile_cast_then_has_ability_window(
                &program.segments,
                0,
            ),
            Some((
                "Exile the top five cards of your library. You may cast an artifact spell from among them this turn. If you do, it has affinity for artifacts"
                    .to_string(),
                3,
            ))
        );
    }

    #[test]
    fn rejects_changed_result_id_or_subset_tag() {
        for program in [program(8, "castable_pool"), program(7, "other_pool")] {
            assert_eq!(
                describe_cross_segment_filtered_exile_cast_then_has_ability_window(
                    &program.segments,
                    0,
                ),
                None
            );
        }
    }

    #[test]
    fn direct_filtered_permission_uses_the_plural_spell_collection() {
        let mut program = program(7, "castable_pool");
        let with_id = program.segments[1].default_effects[1]
            .downcast_ref::<crate::effects::WithIdEffect>()
            .expect("permission result")
            .clone();
        program.segments[1].default_effects[1] = *with_id.effect;
        program.segments.pop();
        assert_eq!(
            describe_cross_segment_filtered_exile_cast_window(&program.segments, 0),
            Some((
                "Exile the top five cards of your library. You may cast artifact spells from among them this turn"
                    .to_string(),
                2,
            ))
        );
    }
}

/// Rejoin an exact singleton top-card observation with its following
/// while-exiled permission. The parser keeps the semantically useful
/// look/choose/exile provenance even when Oracle's singular wording does not
/// expose a choice, and the permission uses the shared source-exiled alias.
/// Match that full typed bridge so broader sequence rendering does not leak
/// the internal `choose one of those cards` step.
fn describe_cross_segment_treasure_look_exile_permission_window(
    segments: &[crate::resolution::ResolutionSegment],
    start: usize,
) -> Option<(String, usize)> {
    let [producer_segment, permission_segment] = segments.get(start..start + 2)? else {
        return None;
    };
    if !producer_segment.self_replacements.is_empty()
        || !permission_segment.self_replacements.is_empty()
        || producer_segment.starts_new_source_line
        || permission_segment.starts_new_source_line
    {
        return None;
    }
    let [sequence_effect] = producer_segment.default_effects.as_slice() else {
        return None;
    };
    let sequence = structural_unwrap_render_wrappers(sequence_effect)
        .downcast_ref::<crate::effects::SequenceEffect>()?;
    if sequence.surface != ironsmith_core::SequenceSurface::CommaThen
        || sequence.result_label.is_some()
    {
        return None;
    }
    let [create_effect, look_effect, choose_effect, exile_effect] = sequence.effects.as_slice()
    else {
        return None;
    };
    let (_, create) = tagged_create_token_effect_for_keyword(create_effect)?;
    if create.count.unhinted() != &Value::Fixed(1)
        || create.controller != PlayerFilter::You
        || create.controller_target.is_some()
        || create.use_source_chosen_color
        || create.use_source_chosen_creature_type
        || create.actor_surface_explicit
        || create.suppress_aura_attachment_choice
        || create.ability_presentation.is_some()
        || create.enters_tapped
        || create.enters_attacking
        || create.attack_target_mode.is_some()
        || create.exile_at_end_of_combat
        || create.sacrifice_at_end_of_combat
        || create.sacrifice_at_next_end_step
        || create.exile_at_next_end_step
        || create.token.card.name != "Treasure"
        || !create.token.card.is_token
        || create.token.card.card_types.as_slice() != [CardType::Artifact]
        || create.token.card.subtypes.as_slice() != [crate::types::Subtype::Treasure]
    {
        return None;
    }

    let look = structural_unwrap_render_wrappers(look_effect)
        .downcast_ref::<crate::effects::LookAtTopCardsEffect>()?;
    if look.player != PlayerFilter::IteratedPlayer
        || look.count.unhinted() != &Value::Fixed(1)
        || look.reveal
    {
        return None;
    }
    let choose = structural_unwrap_render_wrappers(choose_effect)
        .downcast_ref::<crate::effects::ChooseObjectsEffect>()?;
    let expected_choice_filter = ObjectFilter::default().in_zone(Zone::Library).match_tagged(
        look.tag.clone(),
        crate::filter::TaggedOpbjectRelation::IsTaggedObject,
    );
    if choose.filter != expected_choice_filter
        || !choose.count.is_single()
        || choose.count_value.is_some()
        || choose.aggregate_constraint.is_some()
        || choose.chooser != PlayerFilter::You
        || choose.zone != Some(Zone::Library)
        || !choose.additional_zones.is_empty()
        || choose.description != "Choose"
        || choose.is_search
        || choose.reveal
        || choose.search_mode != crate::effect::SearchSelectionMode::Exact
        || choose.search_reveal_reference_surface.is_some()
        || choose.search_result_reference_surface.is_some()
        || choose.search_top_in_any_order_surface.is_some()
        || choose.top_only
        || choose.bottom_only
        || choose.replace_tagged_objects
        || choose.remember_as_chosen_object
    {
        return None;
    }
    let exile = structural_unwrap_render_wrappers(exile_effect)
        .downcast_ref::<crate::effects::ExileEffect>()?;
    if !exile.face_down
        || exile.turn_face_up
        || !matches!(exile.spec.base(), ChooseSpec::Tagged(tag) if tag == &choose.tag)
    {
        return None;
    }

    let [permission_effect] = permission_segment.default_effects.as_slice() else {
        return None;
    };
    let grant = structural_unwrap_render_wrappers(permission_effect)
        .downcast_ref::<crate::effects::GrantPlayTaggedEffect>()?;
    if grant.tag.as_str() != crate::tag::SOURCE_EXILED_TAG
        || grant.player != PlayerFilter::You
        || grant.duration != crate::effects::GrantPlayTaggedDuration::ForAsLongAsExiled
        || grant.surface.is_some()
        || grant.allow_land
        || grant.mana_spend_mode != ironsmith_core::value_model::ManaSpendMode::Normal
        || grant.allow_any_color_for_cast
        || grant.while_on_top_of_library
        || grant.filter.is_some()
        || grant.during_turns_counter_put_on_source.is_some()
        || grant.spell_cost_increase.is_some()
        || grant.lands_enter_tapped
        || grant.cast_pool_is_plural
        || grant.max_plays.is_some()
    {
        return None;
    }

    Some((
        "Create a Treasure token, then look at the top card of that player's library and exile it face down. You may cast that card for as long as it remains exiled"
            .to_string(),
        2,
    ))
}

#[cfg(test)]
mod cross_segment_treasure_look_exile_permission_tests {
    use super::*;

    const LINE: &str = "Whenever one or more creatures you control deal combat damage to a player, create a Treasure token, then look at the top card of that player's library and exile it face down. You may cast that card for as long as it remains exiled.";

    fn program() -> crate::resolution::ResolutionProgram {
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Treasure Observation Probe",
        )
        .card_types(vec![CardType::Creature])
        .parse_text(LINE)
        .expect("public triggered line should parse");
        definition
            .abilities
            .into_iter()
            .find_map(|ability| match ability.kind {
                AbilityKind::Triggered(triggered) => Some(triggered.effects),
                _ => None,
            })
            .expect("line should lower to a triggered program")
    }

    #[test]
    fn singleton_look_choice_bridge_renders_atomically_and_tag_near_miss_does_not() {
        let exact = program();
        assert_eq!(
            describe_cross_segment_treasure_look_exile_permission_window(&exact.segments, 0),
            Some((
                "Create a Treasure token, then look at the top card of that player's library and exile it face down. You may cast that card for as long as it remains exiled"
                    .to_string(),
                2,
            )),
            "{exact:#?}"
        );
        let definition = crate::cards::builders::CardDefinitionBuilder::new(
            crate::ids::CardId::new(),
            "Treasure Observation Probe",
        )
        .card_types(vec![CardType::Creature])
        .parse_text(LINE)
        .expect("public triggered line should parse");
        assert_eq!(
            crate::compiled_text::compiled_text_lines(&definition).join("\n"),
            LINE
        );

        let mut near_miss_segments = exact.segments.clone();
        let permission = near_miss_segments[1].default_effects[0]
            .downcast_ref::<crate::effects::GrantPlayTaggedEffect>()
            .expect("second segment should retain the typed permission");
        let mut wrong_permission = permission.clone();
        wrong_permission.tag = "unrelated_exiled_set".into();
        near_miss_segments[1].default_effects = vec![Effect::new(wrong_permission)];
        assert_eq!(
            describe_cross_segment_treasure_look_exile_permission_window(&near_miss_segments, 0,),
            None
        );
    }
}

